// ====== ALMACENAMIENTO FIRESTORE (con cache localStorage como respaldo offline) ======
const CACHE_PREFIX = 'agrifumiga_cache_';
const CACHE_VERSION = 'v4';

// Limpiar cache de versiones anteriores en todos los dispositivos (una sola vez)
(function limpiarCacheViejo() {
  try {
    if (localStorage.getItem('agrifumiga_cache_version') !== CACHE_VERSION) {
      Object.keys(localStorage)
        .filter(k => k.startsWith('agrifumiga_cache_') || k === 'agrifumiga_migrado_v3')
        .forEach(k => localStorage.removeItem(k));
      localStorage.setItem('agrifumiga_cache_version', CACHE_VERSION);
      console.info('[AgriFumiga] Cache limpiado — versión', CACHE_VERSION);
    }
  } catch {}
})();

function cacheGet<T>(clave: string, def: T): T {
  try {
    const v = localStorage.getItem(CACHE_PREFIX + clave);
    return v ? JSON.parse(v) : def;
  } catch { return def; }
}
function cacheSet(clave: string, valor: any) {
  try { localStorage.setItem(CACHE_PREFIX + clave, JSON.stringify(valor)); } catch {}
}
function leer<T>(clave: string, def: T): T { return cacheGet(clave, def); }

// ====== Fecha/hora Bolivia ======
// new Date().toISOString().slice(0,10) da la fecha en UTC, no en Bolivia (UTC-4).
// Entre las 20:00 y 23:59 hora Bolivia, el UTC ya es el día siguiente → fecha corrida.
// Estas funciones usan los componentes LOCALES del Date (mismo criterio que ya
// usa el resto del archivo con toLocaleTimeString('es-BO') y toTimeString()).
function fechaLocalISO(d: Date = new Date()): string {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}
function horaLocalHHMM(d: Date = new Date()): string {
  const h = String(d.getHours()).padStart(2, '0');
  const min = String(d.getMinutes()).padStart(2, '0');
  return `${h}:${min}`;
}
// Extrae hora HH:MM local de Bolivia a partir de un ISO string guardado en UTC
// (creadoEn, actualizadoEn, etc). NO usar .slice(11,16) sobre esos strings: eso
// da la hora UTC, corrida +4h respecto a la hora real de Bolivia.
function horaDesdeISOBolivia(iso: string): string {
  return horaLocalHHMM(new Date(iso));
}
// Formato para <input type="datetime-local">: ese input interpreta el value como
// hora local sin timezone. Rellenarlo con toISOString() (UTC) muestra la hora
// corrida +4h. Esto arma "YYYY-MM-DDTHH:MM" a partir de componentes locales.
function fechaHoraLocalDatetime(d: Date = new Date()): string {
  return `${fechaLocalISO(d)}T${horaLocalHHMM(d)}`;
}
// Tiempo transcurrido entre un ISO string guardado y ahora (o entre dos ISO strings).
// Devuelve minutos totales y un texto legible "Xh Ym" / "Xm".
function tiempoTranscurrido(desdeIso: string, hastaIso?: string): { minutos: number; texto: string } {
  const desde = new Date(desdeIso).getTime();
  const hasta = hastaIso ? new Date(hastaIso).getTime() : Date.now();
  if (isNaN(desde) || isNaN(hasta) || hasta < desde) return { minutos: 0, texto: '—' };
  const minutos = Math.floor((hasta - desde) / 60000);
  const h = Math.floor(minutos / 60);
  const m = minutos % 60;
  const texto = h > 0 ? `${h}h ${m}m` : `${m}m`;
  return { minutos, texto };
}

// ====== NUEVO: Guardar documento INDIVIDUAL en Firestore ======
// Cada predictivo, OT y parte tiene su propio documento
// → Varios usuarios pueden guardar al mismo tiempo sin pisarse
// Elimina recursivamente todos los campos undefined (Firestore no los acepta)
function limpiarUndefined(obj: any): any {
  if (Array.isArray(obj)) return obj.map(limpiarUndefined);
  if (obj !== null && typeof obj === 'object') {
    return Object.fromEntries(
      Object.entries(obj)
        .filter(([, v]) => v !== undefined)
        .map(([k, v]) => [k, limpiarUndefined(v)])
    );
  }
  return obj;
}

async function dbSet(coleccion: string, id: string, data: any) {
  // 1. Guardar en Firestore PRIMERO — limpiar undefined antes de enviar.
  //    Si esto falla (sin señal, permisos, etc.) la caché local NO se toca,
  //    para no dejar "trabajo fantasma" visible solo en este dispositivo.
  const dataLimpia = limpiarUndefined(data);
  try {
    await setDoc(doc(db, coleccion, id), dataLimpia);
  } catch (e: any) {
    console.error('[dbSet] ERROR:', coleccion, id, e?.code, e?.message);
    throw e; // que quien llamó con await se entere del fallo real, no quede creyendo que guardó
  }
  // 2. Solo si Firestore confirmó la escritura, reflejarlo en caché local
  const arr = cacheGet<any[]>(coleccion, []);
  const idx = arr.findIndex((x: any) => x.id === id);
  const updated = idx >= 0 ? arr.map((x: any) => x.id === id ? data : x) : [...arr, data];
  cacheSet(coleccion, updated);
}

// ====== NUEVO: Eliminar documento individual ======
async function dbDelete(coleccion: string, id: string) {
  cacheSet(coleccion, cacheGet<any[]>(coleccion, []).filter((x: any) => x.id !== id));
  try {
    await deleteDoc(doc(db, coleccion, id));
  } catch (e) {
    console.warn('dbDelete offline:', coleccion, id);
  }
}

// AGREGADO 23/9/2026 (pedido explícito — "agrifumiga tambien, debe tener y disparar una
// solicitud a almacen, para que prepare producto para las maquinas"): al crear una OT nueva de
// maquinaria, genera su solicitud de Almacén (misma colección/pestaña que usa AgriRiego). ID
// determinístico (`sol_<otId>`) para poder encontrarla de nuevo al completar el Parte, sin tener
// que guardar la referencia en ningún otro lado.
async function generarSolicitudDesdeOT(ot: OT) {
  try {
    const productos = (ot.productos || [])
      .filter(p => p.nombre && (parseFloat(String(p.cantTotal)) || 0) > 0)
      .map(p => ({ nombre: p.nombre, dosis: p.dosis, unidad: p.unidadDosis, cantidadEstimada: parseFloat(String(p.cantTotal)) || 0, entregado: false }));
    if (productos.length === 0) return; // OT sin productos cargados — nada que pedirle a almacén
    const solicitud: SolicitudRiego = {
      id: `sol_${ot.id}`,
      origen: 'maquinaria',
      otNumero: ot.numeroOT || ot.id.slice(-6),
      maquina: ot.maquina,
      lotes: ot.lotes || [],
      fecha: ot.fecha,
      campaña: ot.campana || '',
      productos,
      estado: 'pendiente',
      solicitadoPor: ot.creadoPor || ot.jefeCampo || '',
      solicitadoEn: new Date().toISOString(),
    };
    await setDoc(doc(db, COL.almacen_solicitudes_riego, solicitud.id), solicitud);
  } catch (e) { console.error('[generarSolicitudDesdeOT] ERROR:', e); }
}

// AGREGADO 23/9/2026 (pedido explícito — planilla de historial, campos pedidos: "quien genero,
// producto cantidad, lote pivote, nuemro de orden, fecha quien entrego hora y fecha"): UNA FILA
// POR PRODUCTO de la solicitud, escrita en el momento del cierre — queda fija para siempre, no se
// vuelve a tocar aunque el documento de trabajo (`almacen_solicitudes_riego`) se edite o se borre
// después. ID determinístico (`${sol.id}_${i}`) — si por algo se llama 2 veces para la misma
// solicitud (reintento), pisa la misma fila en vez de duplicarla.
interface FilaHistorialSolicitud {
  id: string;
  solicitudId: string;
  origen: 'riego' | 'maquinaria';
  numeroOrden: string;
  pivoteOMaquina: string;
  lotes: string[];
  producto: string;
  unidad: string;
  cantidad: number;
  entregadoCompleto: boolean;
  campaña: string;
  generadoPor: string;
  generadoEn: string;
  entregadoPor: string;
  entregadoEn: string;
}
async function registrarHistorialSolicitud(sol: SolicitudRiego) {
  if (sol.estado !== 'cerrado' || !sol.cerradoEn) return;
  try {
    const batch = writeBatch(db);
    sol.productos.forEach((p, i) => {
      const fila: FilaHistorialSolicitud = {
        id: `${sol.id}_${i}`,
        solicitudId: sol.id,
        origen: sol.origen,
        numeroOrden: sol.origen === 'maquinaria' ? (sol.otNumero || '') : (sol.otRiegoNumero || ''),
        pivoteOMaquina: sol.origen === 'maquinaria' ? (sol.maquina || '') : (sol.pivot || ''),
        lotes: sol.lotes || [],
        producto: p.nombre,
        unidad: p.unidad,
        cantidad: p.entregado ? (p.cantidadEntregada ?? p.cantidadEstimada) : p.cantidadEstimada,
        entregadoCompleto: !!p.entregado,
        campaña: sol.campaña,
        generadoPor: sol.solicitadoPor,
        generadoEn: sol.solicitadoEn,
        entregadoPor: sol.cerradoPor || '',
        entregadoEn: sol.cerradoEn || '',
      };
      batch.set(doc(db, COL.almacen_solicitudes_historial, fila.id), fila);
    });
    await batch.commit();
  } catch (e) { console.error('[registrarHistorialSolicitud] ERROR:', e); }
}

// AGREGADO 23/9/2026: al completar el Parte de esa OT, cierra su solicitud sola, con lo
// REALMENTE aplicado (`productosEntregados` del Parte) — sin que almacén tenga que ir a marcar
// "Entregar" a mano para maquinaria (para riego sí sigue siendo manual, ver PestanaAlmacen).
async function cerrarSolicitudPorParte(otId: string, productosEntregados: Producto[], responsable: string) {
  try {
    const ref = doc(db, COL.almacen_solicitudes_riego, `sol_${otId}`);
    const snap = await getDoc(ref);
    if (!snap.exists()) return;
    const sol = snap.data() as SolicitudRiego;
    if (sol.estado === 'cerrado') return;
    const productosCerrados = sol.productos.map(p => {
      const real = (productosEntregados || []).find(pe => normalizarNombreProducto(pe.nombre) === normalizarNombreProducto(p.nombre));
      return real ? { ...p, entregado: true, cantidadEntregada: parseFloat(String(real.cantTotal)) || 0 } : p;
    });
    const solCerrada: SolicitudRiego = { ...sol, productos: productosCerrados, estado: 'cerrado', cerradoPor: responsable, cerradoEn: new Date().toISOString() };
    await setDoc(ref, solCerrada);
    await registrarHistorialSolicitud(solCerrada);
  } catch (e) { console.error('[cerrarSolicitudPorParte] ERROR:', e); }
}

// AGREGADO 23/9/2026: exporta la planilla de historial de solicitudes a Excel — mismo patrón que
// el resto de los exportadores de esta app (XLSX.utils.json_to_sheet + writeFile).
function exportarHistorialSolicitudesExcel(filas: FilaHistorialSolicitud[]) {
  const datos = filas.map(f => ({
    'Fecha entrega': f.entregadoEn ? new Date(f.entregadoEn).toLocaleString('es-BO', { hour12: false }) : '',
    'N° Orden': f.numeroOrden,
    'Origen': f.origen === 'maquinaria' ? 'Maquinaria' : 'Riego',
    'Pivote/Máquina': f.pivoteOMaquina,
    'Lote(s)': (f.lotes || []).join(', '),
    'Producto': f.producto,
    'Cantidad': f.cantidad,
    'Unidad': f.unidad,
    'Entrega completa': f.entregadoCompleto ? 'Sí' : 'Parcial/estimado',
    'Campaña': f.campaña,
    'Generó': f.generadoPor,
    'Fecha generación': f.generadoEn ? new Date(f.generadoEn).toLocaleString('es-BO', { hour12: false }) : '',
    'Entregó': f.entregadoPor,
  }));
  const ws = XLSX.utils.json_to_sheet(datos);
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, 'Historial Solicitudes');
  XLSX.writeFile(wb, `Historial_Solicitudes_Almacen_${new Date().toISOString().slice(0, 10)}.xlsx`);
}

// ====== NUEVO: Migrar datos viejos (formato array → documentos individuales) ======
async function migrarDatosViejos() {
  if (localStorage.getItem('agrifumiga_migrado_v3')) return;
  try {
    // Leer del formato viejo (array en un solo doc)
    const oldPath = `artifacts/fumigacion-prod/public`;
    const colecciones = [COL.predictivos, COL.ots, COL.partes];
    const batch = writeBatch(db);
    let total = 0;
    for (const col of colecciones) {
      const snap = await getDoc(doc(db, oldPath, col));
      if (snap.exists()) {
        const items: any[] = snap.data().datos || [];
        for (const item of items) {
          if (item?.id) {
            batch.set(doc(db, col, item.id), item);
            total++;
          }
        }
      }
      // También migrar desde localStorage
      const local = cacheGet<any[]>(col, []);
      for (const item of local) {
        if (item?.id) {
          batch.set(doc(db, col, item.id), item);
          total++;
        }
      }
    }
    if (total > 0) await batch.commit();
    localStorage.setItem('agrifumiga_migrado_v3', '1');
    console.info(`Migración completada: ${total} documentos`);
  } catch (e) {
    console.warn('Migración falló (se intentará de nuevo):', e);
  }
}

// guardar() — para almacén y config (no usan onSnapshot aún)
async function guardar(clave: string, valor: any) {
  cacheSet(clave, valor);
  if (Array.isArray(valor)) {
    try {
      const batch = writeBatch(db);
      for (const item of valor) {
        if (item?.id) batch.set(doc(db, clave, item.id), item);
      }
      await batch.commit();
    } catch {}
  } else {
    try {
      await setDoc(doc(db, COL.config, clave), { valor, ts: Date.now() });
    } catch {}
  }
}

// leerFirestore() — compatibilidad para almacén y config
async function leerFirestore<T>(clave: string, def: T): Promise<T> {
  try {
    if (Array.isArray(def) || def === null) {
      const snap = await getDocs(collection(db, clave));
      if (!snap.empty) {
        const data = snap.docs.map(d => d.data()) as unknown as T;
        cacheSet(clave, data);
        return data;
      }
    } else {
      const snap = await getDoc(doc(db, COL.config, clave));
      if (snap.exists()) return snap.data().valor as T;
    }
  } catch {}
  return cacheGet<T>(clave, def);
}


