// ====== FOLIOS DE OT (numeración controlada para auditoría) ======
// Un "folio" es un número de OT pre-reservado dentro de un rango que el
// Maestro registró de antemano (ej. 22000 a 22099). Al crear una OT nueva,
// en vez de escribir el número libremente, se elige uno disponible de la
// lista — así ningún número queda repetido ni fuera de secuencia, y queda
// trazabilidad de en qué OT se usó cada uno, cuándo, y por quién.
interface RangoFolios {
  id: string;
  desde: number;
  hasta: number;
  creadoEn: string;
  creadoPor: string;
}
// Un documento por folio SOLO una vez que deja de estar "disponible" — no
// se crean documentos para cada número disponible (podrían ser miles), solo
// para los que ya se usaron o se eliminaron. "Disponible" = está dentro de
// algún RangoFolios y NO tiene documento acá.
interface FolioHistorial {
  id: string; // el propio número de folio, como string
  numero: number;
  estado: 'usado' | 'eliminado';
  otId?: string;
  otNumero?: string;
  usadoEn?: string;
  usadoPor?: string;
  eliminadoEn?: string;
  eliminadoPor?: string;
  motivoEliminacion?: string;
}

interface ExpedienteArchivo {
  id: string;
  campana: string;
  fechaCierre: string;
  cerradoPor: string;
  predictivo: any;
  ots: any[];
  partes: any[];
  _maquinas: string[];
  _operadores: string[];
  _productos: string[];
  _lotes: string[];
  _cultivo: string;
  _fechaInicio: string;
}

// ====== CICLO DE VIDA DE PREDICTIVO ======
type CicloEstado = 'sin_ot' | 'ot_creada' | 'ot_autorizada' | 'en_ejecucion' | 'completado' | 'archivado';
interface CicloInfo { estado: CicloEstado; label: string; color: string; descripcion: string; }

function calcularCiclo(pred: any, ots: any[], partes: any[]): CicloInfo {
  if (pred.archivado) return { estado: 'archivado', label: '📁 Archivado', color: 'bg-gray-600 text-white', descripcion: 'Expediente cerrado y archivado' };
  const otsPred = ots.filter((o: any) => o.predictivoId === pred.id && !o.archivado);
  if (otsPred.length === 0) return { estado: 'sin_ot', label: '⏳ Sin OT', color: 'bg-yellow-100 text-yellow-800 border border-yellow-300', descripcion: 'No se ha creado ninguna Orden de Trabajo' };
  const todasCompletadas = otsPred.every((ot: any) => partes.some((p: any) => p.otId === ot.id && p.estado === 'completado'));
  if (todasCompletadas) return { estado: 'completado', label: '✔️ Trabajo Completado', color: 'bg-green-600 text-white', descripcion: 'Todos los partes completados. Listo para archivar.' };
  const hayBorrador = otsPred.some((ot: any) => partes.some((p: any) => p.otId === ot.id && p.estado === 'borrador'));
  if (hayBorrador) return { estado: 'en_ejecucion', label: '🚜 En Ejecución', color: 'bg-orange-500 text-white font-bold', descripcion: 'Parte diario en curso' };
  const hayAutorizada = otsPred.some((o: any) => o.validacionTecnica?.autorizado);
  if (hayAutorizada) return { estado: 'ot_autorizada', label: '✅ OT Autorizada', color: 'bg-indigo-100 text-indigo-800 border border-indigo-300', descripcion: 'OT autorizada. Esperando al operador.' };
  return { estado: 'ot_creada', label: '📝 OT Creada', color: 'bg-blue-100 text-blue-800 border border-blue-300', descripcion: 'OT pendiente de validación técnica' };
}

function puedeEditarPredictivo(pred: any, ots: any[], partes: any[]): boolean {
  if (pred.archivado) return false;
  return !ots.filter((o: any) => o.predictivoId === pred.id).some((ot: any) => partes.some((p: any) => p.otId === ot.id && p.estado === 'completado'));
}
function puedeEditarOT(ot: any, partes: any[]): boolean {
  if (ot.archivado) return false;
  const p = partes.find((pa: any) => pa.otId === ot.id);
  return !p || p.estado === 'borrador';
}



interface Predictivo {
  id: string;
  campana?: string; // heredado de campanaActiva al crearse, congelado
  // Cabecera
  idOrdenServicio: string;
  tipo: string; // "Insecticida y Herbicida", "Fungicida", etc.
  fechaDesde: string;
  fechaHasta: string;
  propiedad: string;
  temporada: string;
  cultivo: string;
  // Áreas y productos
  areas: Area[];
  productos: Producto[];
  // Parámetros
  caudal: number;
  cantTotalMezcla: number;
  capacidadTanque: number;
  tanquesNecesarios: number;
  cantUltimoTanque: number;
  periodoReingreso: number;
  periodoCarencia: number;
  // Firmas
  responsable: string;
  creador: string;
  // Estado del flujo
  estado: EstadoPredictivo;
  // Metadatos de auditoría
  creadoEn: string;
  creadoPor?: string;       // Nombre del usuario que lo creó
  editadoEn?: string;       // Última modificación
  editadoPor?: string;      // Nombre del editor
  archivado?: boolean;      // true = en el archivo, no editable
  // Análisis de deposición de gotas (PDF, opcional) — se puede subir una vez
  // que el Parte Diario quedó completado, y no bloquea el archivado si
  // queda vacío. Solo modo Maestro. Guardado como base64 directo en el
  // documento (data URL) — el proyecto está en plan Firebase gratuito
  // (Spark), donde Firebase Storage no funciona sin plan Blaze, así que
  // se usa Firestore en vez de Storage. Por eso el archivo se limita a
  // un tamaño chico (ver MAX_MB_ANALISIS_GOTAS): Firestore tope 1MB/doc.
  analisisGotasBase64?: string;
  analisisGotasNombre?: string;
  analisisGotasSubidoPor?: string;
  analisisGotasSubidoEn?: string;
}

// ╔══════════════════════════════════════════════════════════════════╗
// ║         PARSER DE PDF CROPWISE (Fase 2)                           ║
// ╚══════════════════════════════════════════════════════════════════╝

// Convierte número formato Cropwise ("5.000,000" o "2,800") a número real
function parseNum(s: string): number {
  if (!s) return 0;
  // Quitar separadores de miles (puntos) y reemplazar coma decimal por punto
  const normalized = s.trim().replace(/\./g, '').replace(',', '.');
  const n = parseFloat(normalized);
  return isNaN(n) ? 0 : n;
}

// Extraer texto del PDF reconstruyendo líneas por posición Y
async function extraerTextoPDF(file: File): Promise<string> {
  // Carga diferida — pdfjs-dist pesa ~1.25MB con su worker. La mayoría de
  // los usos de la app (Parte Diaria, Orden de Trabajo, Almacén) nunca
  // suben un PDF, así que no tiene sentido bajar esto en cada apertura.
  const pdfjsLib = await import('pdfjs-dist');
  const workerUrl = (await import('pdfjs-dist/build/pdf.worker.min.mjs?url')).default;
  pdfjsLib.GlobalWorkerOptions.workerSrc = workerUrl;

  const arrayBuffer = await file.arrayBuffer();
  const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;

  let textoCompleto = '';
  for (let i = 1; i <= pdf.numPages; i++) {
    const page = await pdf.getPage(i);
    const content = await page.getTextContent();

    // Agrupar items por posición Y (reconstruir líneas)
    const items = content.items as any[];
    if (items.length === 0) continue;

    // Ordenar por Y descendente (los PDFs tienen Y=0 abajo)
    const sorted = [...items].sort((a, b) => {
      const yDiff = b.transform[5] - a.transform[5];
      if (Math.abs(yDiff) > 3) return yDiff;
      return a.transform[4] - b.transform[4]; // misma línea: ordenar por X
    });

    let currentY = sorted[0].transform[5];
    let line = '';
    const lines: string[] = [];

    for (const item of sorted) {
      const y = item.transform[5];
      if (Math.abs(y - currentY) < 3) {
        // Misma línea
        line += (line ? ' ' : '') + item.str;
      } else {
        // Nueva línea
        if (line.trim()) lines.push(line.trim());
        line = item.str;
        currentY = y;
      }
    }
    if (line.trim()) lines.push(line.trim());

    textoCompleto += lines.join('\n') + '\n';
  }

  return textoCompleto;
}

// Parser del texto extraído → objeto Predictivo parcial
function parsearPDFCropwise(texto: string): {
  datos: Partial<Predictivo>;
  camposLeidos: number;
  textoRaw: string;
} {
  const datos: Partial<Predictivo> = {};
  let camposLeidos = 0;

  // ID Orden de Servicio
  const idMatch = texto.match(/Orden de Servicio \(ID\):\s*#?(\d+)/i);
  if (idMatch) {
    datos.idOrdenServicio = idMatch[1];
    camposLeidos++;
  }

  // Tipo de prescripción
  const tipoMatch = texto.match(/Prescripci[oó]n:\s*(.+?)(?:\n|$)/i);
  if (tipoMatch) {
    datos.tipo = tipoMatch[1].trim();
    camposLeidos++;
  }

  // Fechas: "20/05/26 12:35h → 20/05/26 12:35h"
  const fechaMatch = texto.match(
    /(\d{2})\/(\d{2})\/(\d{2})\s+(\d{2}:\d{2})h?\s*[→\-]+\s*(\d{2})\/(\d{2})\/(\d{2})\s+(\d{2}:\d{2})h?/
  );
  if (fechaMatch) {
    const [, dd1, mm1, yy1, hh1, dd2, mm2, yy2, hh2] = fechaMatch;
    datos.fechaDesde = `20${yy1}-${mm1}-${dd1}T${hh1}`;
    datos.fechaHasta = `20${yy2}-${mm2}-${dd2}T${hh2}`;
    camposLeidos += 2;
  }

  // Propiedad, Temporada, Cultivo
  const propMatch = texto.match(
    /Agripac Boliviana\s*[•·]\s*([^•·\n]+?)\s*[•·]\s*Temporada:\s*([^•·\n]+?)\s*[•·]\s*Cultivo:\s*(\S+)/i
  );
  if (propMatch) {
    datos.propiedad = propMatch[1].trim();
    datos.temporada = propMatch[2].trim();
    datos.cultivo = propMatch[3].trim().toUpperCase();
    camposLeidos += 3;
  }

  // ÁREAS — 2 formatos: CON variedad (5 cols) o SIN variedad (4 cols)
  const areas: Area[] = [];

  const areasMatchConVariedad = texto.match(
    /[ÁA]rea\s+Regi[oó]n\s+Variedad\s+[ÁA]rea a aplicar\s+[ÁA]rea total([\s\S]*?)Productos\s*\(/i
  );
  const areasMatchSinVariedad = texto.match(
    /[ÁA]rea\s+Regi[oó]n\s+[ÁA]rea a aplicar\s+[ÁA]rea total([\s\S]*?)Productos\s*\(/i
  );

  const areasMatch = areasMatchConVariedad || areasMatchSinVariedad;
  const tieneVariedad = !!areasMatchConVariedad;

  if (areasMatch) {
    const lineas = areasMatch[1].split('\n').map(l => l.trim()).filter(l => l);
    for (const linea of lineas) {
      if (tieneVariedad) {
        const m = linea.match(
          /^(\S+)\s+(\S+)\s+(.+?)\s+([\d.,]+)\s*ha\s+([\d.,]+)\s*ha\s*$/i
        );
        if (m) {
          areas.push({
            lote: m[1], region: m[2], variedad: m[3].trim(),
            areaAplicar: parseNum(m[4]), areaTotal: parseNum(m[5]),
          });
        }
      } else {
        const m = linea.match(
          /^(\S+)\s+(\S+)\s+([\d.,]+)\s*ha\s+([\d.,]+)\s*ha\s*$/i
        );
        if (m) {
          areas.push({
            lote: m[1], region: m[2], variedad: '',
            areaAplicar: parseNum(m[3]), areaTotal: parseNum(m[4]),
          });
        }
      }
    }
  }
  if (areas.length > 0) {
    datos.areas = areas;
    camposLeidos += areas.length;
  }

  // PRODUCTOS — 2 formatos: CON columnas de tanque o SIN columnas de tanque
  const productos: Producto[] = [];

  const prodMatchConTanques = texto.match(
    /Orden\s+Producto\s+Dosis\s+Cant\.\s*total\s+Cant\.\s*por tanque\s+[ÚU]ltimo tanque([\s\S]*?)(?:Leyenda|Caudal)/i
  );
  const prodMatchSinTanques = texto.match(
    /Orden\s+Producto\s+Dosis\s+Cant\.\s*total([\s\S]*?)(?:Leyenda|Caudal)/i
  );

  const prodMatch = prodMatchConTanques || prodMatchSinTanques;
  const tieneTanques = !!prodMatchConTanques;

  if (prodMatch) {
    const lineas = prodMatch[1].split('\n').map(l => l.trim()).filter(l => l);
    for (const linea of lineas) {
      if (tieneTanques) {
        const m = linea.match(
          /^(\d+)\s+(.+?)\s+([\d.,]+)\s*\((L\/ha|kg\/ha|g\/ha|ml\/ha)\)\s+([\d.,]+)\s*\S+\s+([\d.,]+)\s*\S+\s+([\d.,]+)\s*\S+\s*$/i
        );
        if (m) {
          productos.push({
            orden: parseInt(m[1]), nombre: m[2].trim(),
            dosis: parseNum(m[3]), unidadDosis: m[4],
            cantTotal: parseNum(m[5]), cantPorTanque: parseNum(m[6]), ultimoTanque: parseNum(m[7]),
          });
        }
      } else {
        // Sin columnas de tanque: "1 Boxster 0,400 (L/ha) 20,000 L"
        const m = linea.match(
          /^(\d+)\s+(.+?)\s+([\d.,]+)\s*\((L\/ha|kg\/ha|g\/ha|ml\/ha)\)\s+([\d.,]+)\s*\S+\s*$/i
        );
        if (m) {
          productos.push({
            orden: parseInt(m[1]), nombre: m[2].trim(),
            dosis: parseNum(m[3]), unidadDosis: m[4],
            cantTotal: parseNum(m[5]), cantPorTanque: 0, ultimoTanque: 0,
          });
        }
      }
    }
  }
  if (productos.length > 0) {
    datos.productos = productos;
    camposLeidos += productos.length;
  }

  // PARÁMETROS — el PDF los pone en columnas (etiquetas en una fila, valores debajo)
  // Convertimos texto en líneas para poder buscar pares "fila etiquetas → fila valores"
  const lineasParam = texto.split('\n').map(l => l.trim());

  // Helper: dada una línea de etiquetas, retorna la siguiente línea de valores
  function siguienteLineaValores(etiquetasIncluyen: string[]): string | null {
    for (let i = 0; i < lineasParam.length - 1; i++) {
      const linea = lineasParam[i].toLowerCase();
      if (etiquetasIncluyen.every(e => linea.includes(e.toLowerCase()))) {
        return lineasParam[i + 1];
      }
    }
    return null;
  }

  // Helper: divide línea por 2+ espacios consecutivos (separador de columnas)
  function dividirPorColumnas(linea: string): string[] {
    return linea.split(/\s{2,}/).map(s => s.trim()).filter(s => s);
  }

  // Caudal + Cantidad Total de Mezcla (2 columnas)
  let vals = siguienteLineaValores(['Caudal', 'Cantidad Total de Mezcla']);
  if (vals) {
    const cols = dividirPorColumnas(vals);
    if (cols.length >= 2) {
      const caudalM = cols[0].match(/([\d.,]+)/);
      const mezclaM = cols[1].match(/([\d.,]+)/);
      if (caudalM) { datos.caudal = parseNum(caudalM[1]); camposLeidos++; }
      if (mezclaM) { datos.cantTotalMezcla = parseNum(mezclaM[1]); camposLeidos++; }
    }
  }

  // Capacidad del Tanque + Tanques Necesarios + Cantidad en el Último Tanque (3 columnas)
  vals = siguienteLineaValores(['Capacidad del Tanque', 'Tanques Necesarios']);
  if (vals) {
    const cols = dividirPorColumnas(vals);
    if (cols.length >= 3) {
      const capM = cols[0].match(/([\d.,]+)/);
      const tanM = cols[1].match(/([\d.,]+)/);
      const ultM = cols[2].match(/([\d.,]+)/);
      if (capM) { datos.capacidadTanque = parseNum(capM[1]); camposLeidos++; }
      if (tanM) { datos.tanquesNecesarios = parseNum(tanM[1]); camposLeidos++; }
      if (ultM) { datos.cantUltimoTanque = parseNum(ultM[1]); camposLeidos++; }
    }
  }

  // Período de Reingreso + Período de Carencia (2 columnas)
  vals = siguienteLineaValores(['Reingreso', 'Carencia']);
  if (vals) {
    const cols = dividirPorColumnas(vals);
    if (cols.length >= 2) {
      const reingM = cols[0].match(/(\d+)/);
      const carencM = cols[1].match(/(\d+)/);
      if (reingM) { datos.periodoReingreso = parseInt(reingM[1]); camposLeidos++; }
      if (carencM) { datos.periodoCarencia = parseInt(carencM[1]); camposLeidos++; }
    }
  }

  // RESPONSABLE y CREADOR — los nombres aparecen en la línea ANTERIOR a "Responsable  Creador"
  for (let i = 1; i < lineasParam.length; i++) {
    const linea = lineasParam[i].toLowerCase();
    if (linea.includes('responsable') && linea.includes('creador')) {
      const cols = dividirPorColumnas(lineasParam[i - 1]);
      if (cols.length >= 2) {
        datos.responsable = cols[0];
        datos.creador = cols[1];
        camposLeidos += 2;
      } else if (cols.length === 1) {
        datos.responsable = cols[0];
        camposLeidos++;
      }
      break;
    }
    // Caso alternativo: solo "Responsable" en la línea (sin Creador)
    if (linea === 'responsable') {
      datos.responsable = lineasParam[i - 1].trim();
      camposLeidos++;
    }
    if (linea === 'creador') {
      datos.creador = lineasParam[i - 1].trim();
      camposLeidos++;
    }
  }

  return { datos, camposLeidos, textoRaw: texto };
}

