// ╔══════════════════════════════════════════════════════════════════╗
// ║                    PESTAÑA ALMACÉN COMPLETO                        ║
// ╚══════════════════════════════════════════════════════════════════╝

// ====== Dashboard de Almacén — gráficos SVG hechos a mano, sin librerías ======
// Alcance: datos EN VIVO (ots/partes activos), no incluye lo ya archivado.
// Ampliar a histórico archivado queda para una segunda vuelta si hace falta.
// Con 15-20 productos distintos, la barra apilada quedaba en franjas
// invisibles y la leyenda en una pared de textos ilegible (justo lo que
// reportó Juan Carlos). Se queda con los N productos de mayor volumen TOTAL
// (sumando todas las máquinas) y el resto se junta en "Otros" — mismo
// criterio de agrupación en todas las máquinas, para que el color de cada
// producto signifique lo mismo en toda la barra.
function agruparTopProductos(
  datos: { maquina: string; productos: { nombre: string; cantidad: number }[] }[],
  topN: number
): { maquina: string; productos: { nombre: string; cantidad: number }[] }[] {
  const totalesPorProducto: Record<string, number> = {};
  datos.forEach(m => m.productos.forEach(p => {
    totalesPorProducto[p.nombre] = (totalesPorProducto[p.nombre] || 0) + p.cantidad;
  }));
  const nombresTop = new Set(
    Object.entries(totalesPorProducto)
      .sort((a, b) => b[1] - a[1])
      .slice(0, topN)
      .map(([nombre]) => nombre)
  );
  if (Object.keys(totalesPorProducto).length <= topN) return datos; // no hace falta agrupar
  return datos.map(m => {
    const top: { nombre: string; cantidad: number }[] = [];
    let otros = 0;
    m.productos.forEach(p => {
      if (nombresTop.has(p.nombre)) top.push(p);
      else otros += p.cantidad;
    });
    if (otros > 0) top.push({ nombre: 'Otros', cantidad: otros });
    return { maquina: m.maquina, productos: top };
  });
}

function BarraHorizontal({ datos, colorClase }: { datos: { etiqueta: string; valor: number }[]; colorClase: string }) {
  const max = Math.max(...datos.map(d => d.valor), 0.0001);
  return (
    <div className="space-y-1.5">
      {datos.map((d, i) => (
        <div key={i} className="flex items-center gap-2 text-xs">
          <span className="w-20 shrink-0 text-gray-600 truncate">{d.etiqueta}</span>
          <div className="flex-1 bg-gray-100 rounded h-4 overflow-hidden">
            <div className={`h-full ${colorClase} rounded flex items-center justify-end pr-1`} style={{ width: `${(d.valor / max) * 100}%` }}>
              <span className="text-[10px] text-white font-semibold">{d.valor.toFixed(1)}</span>
            </div>
          </div>
        </div>
      ))}
      {datos.length === 0 && <p className="text-xs text-gray-400 italic">Sin datos todavía.</p>}
    </div>
  );
}

// Paleta fija para que cada producto tenga siempre el mismo color entre renders
const PALETA_PRODUCTOS = ['#10b981','#3b82f6','#f59e0b','#ef4444','#8b5cf6','#ec4899','#14b8a6','#f97316','#6366f1','#84cc16'];
function colorProducto(nombre: string, indice: Record<string, number>): string {
  if (!(nombre in indice)) indice[nombre] = Object.keys(indice).length;
  if (nombre === 'Otros') return '#9ca3af'; // gris neutro fijo — no es un producto real, es la bolsa de "el resto"
  return PALETA_PRODUCTOS[indice[nombre] % PALETA_PRODUCTOS.length];
}

// Barra apilada: una fila por máquina, segmentada por producto (cada uno su color),
// para poder ver de qué está compuesto el total, no solo el total en un color plano.
function BarraApilada({ porMaquina, indiceColor }: { porMaquina: { maquina: string; productos: { nombre: string; cantidad: number }[] }[]; indiceColor: Record<string, number> }) {
  const totales = porMaquina.map(m => m.productos.reduce((s, p) => s + p.cantidad, 0));
  const max = Math.max(...totales, 0.0001);
  return (
    <div className="space-y-2">
      {porMaquina.map((m, i) => {
        const total = totales[i];
        return (
          <div key={i} className="flex items-center gap-2 text-xs">
            <span className="w-20 shrink-0 text-gray-600 truncate">{m.maquina}</span>
            <div className="flex-1 bg-gray-100 rounded h-4 overflow-hidden flex">
              {m.productos.map((p, j) => (
                <div
                  key={j}
                  title={`${p.nombre}: ${p.cantidad.toFixed(1)}`}
                  style={{ width: `${(p.cantidad / max) * 100}%`, background: colorProducto(p.nombre, indiceColor) }}
                />
              ))}
            </div>
            <span className="w-14 shrink-0 text-gray-500 text-right">{total.toFixed(1)}</span>
          </div>
        );
      })}
      {porMaquina.length === 0 && <p className="text-xs text-gray-400 italic">Sin datos todavía.</p>}
    </div>
  );
}
function LeyendaProductos({ indiceColor }: { indiceColor: Record<string, number> }) {
  const entradas = Object.entries(indiceColor);
  if (entradas.length === 0) return null;
  return (
    <div className="flex flex-wrap gap-x-3 gap-y-1 mt-2 text-[10px] text-gray-500">
      {entradas.map(([nombre]) => (
        <span key={nombre} className="flex items-center gap-1">
          <span className="w-2.5 h-2.5 rounded-sm inline-block" style={{ background: colorProducto(nombre, indiceColor) }} />
          {nombre}
        </span>
      ))}
    </div>
  );
}
function LineaSimple({ puntos, colorTrazo, unidad }: { puntos: { fecha: string; valor: number }[]; colorTrazo: string; unidad: string }) {
  if (puntos.length === 0) return <p className="text-xs text-gray-400 italic">Sin datos todavía.</p>;
  const w = 560, h = 170, pad = 34, padInferior = 24;
  const valores = puntos.map(p => p.valor);
  const min = Math.min(...valores), max = Math.max(...valores, min + 0.0001);
  const altoUtil = h - pad - padInferior;
  const paso = puntos.length > 1 ? (w - pad * 2) / (puntos.length - 1) : 0;
  const y = (v: number) => pad + altoUtil - ((v - min) / (max - min)) * altoUtil;
  const puntosSvg = puntos.map((p, i) => `${pad + i * paso},${y(p.valor)}`).join(' ');
  const areaSvg = `${pad},${pad + altoUtil} ${puntosSvg} ${pad + (puntos.length - 1) * paso},${pad + altoUtil}`;
  // Si hay muchos puntos, no mostrar todas las fechas para que no se pisen —
  // mostrar aprox. una de cada N, siempre incluyendo la primera y la última.
  const saltoEtiqueta = Math.max(1, Math.ceil(puntos.length / 8));
  // 3 líneas de referencia horizontales (grilla) — ayudan a leer valores
  // intermedios de un vistazo en vez de tener que estimar a ojo.
  const lineasGuia = [0, 0.5, 1].map(f => pad + altoUtil * f);
  return (
    <svg viewBox={`0 0 ${w} ${h}`} className="w-full">
      {lineasGuia.map((ly, i) => (
        <line key={i} x1={pad} y1={ly} x2={w - pad} y2={ly} stroke="#f1f5f9" strokeWidth="1" />
      ))}
      <line x1={pad} y1={pad+altoUtil} x2={w-pad} y2={pad+altoUtil} stroke="#e5e7eb" strokeWidth="1" />
      <polygon points={areaSvg} fill={colorTrazo} opacity="0.08" />
      <polyline points={puntosSvg} fill="none" stroke={colorTrazo} strokeWidth="2" />
      {puntos.map((p, i) => (
        <circle key={i} cx={pad + i * paso} cy={y(p.valor)} r="3" fill={colorTrazo} />
      ))}
      {puntos.map((p, i) => (
        (i % saltoEtiqueta === 0 || i === puntos.length - 1) && (
          <text key={i} x={pad + i * paso} y={h - 6} fontSize="9" fill="#6b7280" textAnchor="middle">
            {p.fecha.slice(5)}
          </text>
        )
      ))}
      <text x={2} y={pad + 3} fontSize="10" fill="#6b7280">{max.toFixed(1)}{unidad}</text>
      <text x={2} y={pad+altoUtil} fontSize="10" fill="#6b7280">{min.toFixed(1)}{unidad}</text>
    </svg>
  );
}

// ====== CONSUMO REAL DE PRODUCTOS (derivado de OT/Parte, en vivo + archivo) ======
// El auto-descuento de completarParte() solo alimenta af_alm_mov hacia
// adelante (y con el nombre EXACTO del producto de la OT). Todo lo ya
// archivado, y cualquier parte reparado a mano (firebase-admin), nunca
// generó ese movimiento — por eso Movimientos/Dashboard/Por Lote quedaban
// vacíos aunque en Archivo hubiera decenas de fumigaciones reales.
// Esta función reconstruye el consumo REAL directamente desde la fuente
// confiable (igual que usa PestanaArchivo/el Excel): OT + Parte completado
// (usa productosEntregados del Parte —lo realmente aplicado— y si no
// existe, cae a productos de la OT), tanto en vivo como ya archivado.
function normalizarNombreProducto(n: string): string {
  return (n || '').trim().toLowerCase();
}

function productosRealesDeAplicacion(ot: OT, parte?: ParteDiario): Producto[] {
  const entregados = (parte as any)?.productosEntregados as Producto[] | undefined;
  if (Array.isArray(entregados) && entregados.length > 0) return entregados;
  return ot.productos || [];
}

interface AplicacionReal {
  id: string;
  productoId: string;
  productoNombre: string;
  unidad: string;
  tipo: 'egreso';
  tipoAplicacion: 'maquinaria';
  cantidad: number;
  stockAntes: number;
  stockDespues: number;
  otNumero: string;
  maquina?: string;
  pivot?: string;
  lotes: string[];
  campaña: string;
  responsable: string;
  observaciones: string;
  fecha: string;
  creadoEn: string;
}

function construirAplicacionesReales(
  ots: OT[],
  partes: ParteDiario[],
  expedientesArchivo: ExpedienteArchivo[],
): AplicacionReal[] {
  const salida: AplicacionReal[] = [];
  const partesPorOt: Record<string, ParteDiario[]> = {};
  partes.forEach(p => { (partesPorOt[p.otId] = partesPorOt[p.otId] || []).push(p); });

  function procesar(ot: OT, partesDeEsaOt: ParteDiario[]) {
    if (!ot?.maquina) return;
    const parteCompletado = partesDeEsaOt.find(p => p.estado === 'completado') || partesDeEsaOt[0];
    const productos = productosRealesDeAplicacion(ot, parteCompletado);
    const fecha = parteCompletado?.fecha || ot.fecha || '';
    productos.forEach((pr, i) => {
      const cant = parseFloat(String(pr.cantTotal)) || 0;
      if (!pr.nombre || !(cant > 0)) return;
      salida.push({
        id: `real_${ot.id}_${parteCompletado?.id || 'sinparte'}_${i}`,
        productoId: normalizarNombreProducto(pr.nombre),
        productoNombre: pr.nombre,
        unidad: (pr.unidadDosis || '').split('/')[0] || 'LTS',
        tipo: 'egreso',
        tipoAplicacion: 'maquinaria',
        cantidad: cant,
        stockAntes: 0,
        stockDespues: 0,
        otNumero: ot.numeroOT || ot.id.slice(-6),
        maquina: ot.maquina,
        lotes: ot.lotes || [],
        campaña: ot.campana || '',
        responsable: parteCompletado?.operador || '',
        observaciones: '',
        fecha,
        creadoEn: fecha,
      });
    });
  }

  ots.filter(o => !o.archivado).forEach(ot => procesar(ot, partesPorOt[ot.id] || []));
  expedientesArchivo.forEach(exp => {
    (exp.ots || []).forEach(ot => {
      const partesDeEsaOt = (exp.partes || []).filter(p => p.otId === ot.id);
      procesar(ot, partesDeEsaOt);
    });
  });
  return salida;
}

function DashboardAlmacen({
  ots, partes, movimientos, archivoExpedientes, confirmadoServidor,
}: {
  ots: OT[]; partes: ParteDiario[]; movimientos: MovimientoAlmacen[]; archivoExpedientes: ExpedienteArchivo[]; confirmadoServidor: boolean;
}) {
  // "En vivo" + archivado: antes este dashboard solo veía ots/partes en
  // memoria (los todavía abiertos), por eso máquinas con decenas de
  // fumigaciones archivadas aparecían con 1-2 horas. Ahora se suma lo que
  // ya está en af_archivo para reflejar el histórico real de la campaña.
  // OJO: archivar NO borra la OT/Parte de la colección en vivo (af_ots/af_partes),
  // solo la marca `archivado:true` y además la copia dentro de af_archivo. Si no
  // se filtra `archivado` acá, cada OT/Parte ya archivado se cuenta DOS veces
  // (una en `ots`/`partes` en vivo, otra en el expediente de af_archivo).
  const otsCompletas: OT[] = [...ots.filter(o => !o.archivado), ...archivoExpedientes.flatMap(e => e.ots || [])];
  const partesCompletos: ParteDiario[] = [...partes.filter(p => !p.archivado), ...archivoExpedientes.flatMap(e => e.partes || [])];

  // Gráfico 1: producto consumido por máquina, apilado por producto.
  // Separado por unidad (LTS vs KGS) para no mezclar litros con kilos en
  // la misma barra ni en el mismo total.
  const egresos = movimientos.filter(m => m.tipo === 'egreso' && m.maquina);
  const unidades = [...new Set(egresos.map(m => m.unidad))];
  const gruposPorUnidad = unidades.map(unidad => {
    const porMaquina: Record<string, Record<string, number>> = {};
    egresos.filter(m => m.unidad === unidad).forEach(m => {
      if (!porMaquina[m.maquina!]) porMaquina[m.maquina!] = {};
      porMaquina[m.maquina!][m.productoNombre] = (porMaquina[m.maquina!][m.productoNombre] || 0) + m.cantidad;
    });
    const datos = Object.entries(porMaquina)
      .map(([maquina, productos]) => ({
        maquina,
        productos: Object.entries(productos).map(([nombre, cantidad]) => ({ nombre, cantidad })),
      }))
      .sort((a, b) => b.productos.reduce((s,p)=>s+p.cantidad,0) - a.productos.reduce((s,p)=>s+p.cantidad,0));
    return { unidad, datos: agruparTopProductos(datos, 6) };
  });

  // Gráfico 2: horas trabajadas por máquina (registrosLote de cada parte, vía la OT)
  const otPorId: Record<string, OT> = {};
  otsCompletas.forEach(o => { otPorId[o.id] = o; });
  const horasPorMaquina: Record<string, number> = {};
  partesCompletos.forEach(p => {
    const ot = otPorId[p.otId];
    if (!ot?.maquina) return;
    const horas = (p.registrosLote || []).reduce((s, r) => s + (r.horasTrabajadas || 0), 0);
    horasPorMaquina[ot.maquina] = Math.round(((horasPorMaquina[ot.maquina] || 0) + horas) * 100) / 100;
  });
  const datosHoras = Object.entries(horasPorMaquina)
    .map(([etiqueta, valor]) => ({ etiqueta, valor }))
    .sort((a, b) => b.valor - a.valor);

  // Gráfico 3: humedad relativa y ΔT por fecha de parte
  const puntosHumedad = partesCompletos
    .filter(p => p.controlTecnico?.humedadRelativa)
    .map(p => ({ fecha: p.fecha, valor: p.controlTecnico.humedadRelativa }))
    .sort((a, b) => a.fecha.localeCompare(b.fecha));
  const puntosDeltaT = partesCompletos
    .filter(p => p.controlTecnico?.deltaT !== undefined && p.controlTecnico?.deltaT !== null)
    .map(p => ({ fecha: p.fecha, valor: p.controlTecnico.deltaT }))
    .sort((a, b) => a.fecha.localeCompare(b.fecha));

  return (
    <div className="p-3 space-y-4">
      <p className="text-xs text-gray-400 italic">
        Incluye OTs/partes en vivo de esta campaña + expedientes ya archivados.
      </p>
      {!confirmadoServidor && (
        <p className="text-xs text-gray-400 italic">
          🔄 Actualizando desde el servidor — recién se abrió la app, estos números todavía pueden estar incompletos.
        </p>
      )}

      <div className="bg-gray-50 border rounded-lg p-3">
        <h3 className="text-sm font-bold text-gray-700 mb-2">📦 Producto consumido por máquina</h3>
        {gruposPorUnidad.map(({ unidad, datos }) => {
          const indiceColor: Record<string, number> = {};
          return (
            <div key={unidad} className="mb-3 last:mb-0">
              <p className="text-[11px] text-gray-500 font-semibold mb-1">{unidad}</p>
              <BarraApilada porMaquina={datos} indiceColor={indiceColor} />
              <LeyendaProductos indiceColor={indiceColor} />
            </div>
          );
        })}
        {gruposPorUnidad.length === 0 && <p className="text-xs text-gray-400 italic">Sin datos todavía.</p>}
      </div>

      <div className="bg-gray-50 border rounded-lg p-3">
        <h3 className="text-sm font-bold text-gray-700 mb-2">⏱️ Horas trabajadas por máquina</h3>
        <BarraHorizontal datos={datosHoras} colorClase="bg-blue-500" />
      </div>

      <div className="bg-gray-50 border rounded-lg p-3">
        <h3 className="text-sm font-bold text-gray-700 mb-2">💦 Humedad relativa por fecha</h3>
        <LineaSimple puntos={puntosHumedad} colorTrazo="#0ea5e9" unidad="%" />
      </div>

      <div className="bg-gray-50 border rounded-lg p-3">
        <h3 className="text-sm font-bold text-gray-700 mb-2">🌡️ ΔT por fecha</h3>
        <LineaSimple puntos={puntosDeltaT} colorTrazo="#f97316" unidad="" />
      </div>
    </div>
  );
}

// ===== Panel de presencia (solo maestro) =====
// Lee en vivo af_presencia y muestra quién usó la app y cuándo. Oculta
// entradas de más de 48h (mismo criterio que ya usás en AgriRiego) en vez
// de acumularlas para siempre.
function PanelPresencia({ onCerrar }: { onCerrar: () => void }) {
  const [usuarios, setUsuarios] = useState<{ nombre: string; rol: string; ultimaActividad: string; version?: string }[]>([]);
  const [cargando, setCargando] = useState(true);

  useEffect(() => {
    const unsub = onSnapshot(collection(db, COL.presencia), (snap) => {
      const lista = snap.docs.map(d => d.data() as any);
      setUsuarios(lista);
      setCargando(false);
    }, () => setCargando(false));
    return () => unsub();
  }, []);

  const LIMITE_48H_MIN = 48 * 60;
  const visibles = usuarios
    .map(u => ({ ...u, t: tiempoTranscurrido(u.ultimaActividad) }))
    .filter(u => u.t.minutos < LIMITE_48H_MIN)
    .sort((a, b) => a.t.minutos - b.t.minutos);
  const desactualizados = visibles.filter(u => u.version && u.version !== APP_VERSION).length;

  return (
    <div className="fixed inset-0 bg-black/60 z-50 flex items-end md:items-center justify-center">
      <div className="bg-white rounded-t-2xl md:rounded-xl w-full md:max-w-md max-h-[80vh] flex flex-col shadow-2xl">
        <div className="p-4 border-b flex items-center justify-between">
          <div>
            <h3 className="font-bold">🟢 Usuarios conectados</h3>
            <p className="text-[11px] text-gray-400">Versión actual: v{APP_VERSION}{desactualizados > 0 && <span className="text-red-600 font-semibold"> · {desactualizados} con versión vieja</span>}</p>
          </div>
          <button onClick={onCerrar} className="text-gray-400 text-xl leading-none">×</button>
        </div>
        <div className="p-4 overflow-y-auto flex-1 space-y-2">
          {cargando && <p className="text-xs text-gray-400 italic">Cargando…</p>}
          {!cargando && visibles.length === 0 && (
            <p className="text-xs text-gray-400 italic">Nadie usó la app en las últimas 48h.</p>
          )}
          {visibles.map((u, i) => {
            const activo = u.t.minutos < 5;
            // Sin `version` = usuario que todavía no pasó por este heartbeat
            // actualizado (versión anterior a que existiera este campo) —
            // también cuenta como "hay que actualizar", no se sabe cuál tiene.
            const desactualizado = !u.version || u.version !== APP_VERSION;
            return (
              <div key={i} className="flex items-center justify-between bg-gray-50 rounded px-3 py-2 text-sm">
                <div className="flex items-center gap-2">
                  <span className={`w-2 h-2 rounded-full ${activo ? 'bg-green-500' : 'bg-gray-300'}`} />
                  <div>
                    <p className="font-semibold">{u.nombre}</p>
                    <p className="text-[11px] text-gray-500">
                      {u.rol}
                      {' · '}
                      <span className={desactualizado ? 'text-red-600 font-semibold' : 'text-gray-400'}>
                        v{u.version || '?'}
                      </span>
                    </p>
                  </div>
                </div>
                <span className="text-xs text-gray-500">
                  {activo ? 'activo ahora' : `hace ${u.t.texto}`}
                </span>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

// AGREGADO 23/9/2026 (pedido explícito — "permitir que el jefe de agrifumiga pueda generar una OT
// para aplicacion con pivote... porq el que nos da la orden de aplicar con pivotes son los de
// fumigacion"): pestaña donde el jefe (rol maestro) crea la orden; AgriRiego la lee (conexión
// directa a este mismo proyecto Firebase desde AgriRiego) y cuando la convierte en Programación
// real, escribe de vuelta acá `estado/otRiegoNumero/fechaProgramadaReal` — esta pestaña solo LEE
// esos campos, nunca los toca desde acá salvo Anular.
// AGREGADO 23/9/2026: lectura de solo-lectura del proyecto de AgriRiego (registrosRiego) para
// saber qué pivotes están regando AHORA MISMO — así fumigación programa su aplicación sabiendo
// qué pivotes están ocupados. Solo se leen los campos mínimos necesarios.
interface LogRiegoMin {
  id: string;
  action: 'ARRANQUE' | 'PARO' | 'REANUDACION';
  pivot: string;
  timestamp: string;
  operator?: string;
  lotes?: string[];
  campana?: string;
  // AGREGADO 23/9/2026 (pedido explícito — "todo la hora de arranque, tiempo estimado q termina"):
  // AgriRiego ya calcula y guarda estos 2 campos directo en el documento de ARRANQUE (se usan ahí
  // mismo para su propio cronómetro en vivo) — se leen tal cual, sin recalcular nada acá, porque
  // reproducir esa cuenta (depende de velocidad, pasadas y calibración propia de cada pivote) no
  // tendría sentido duplicarlo en este proyecto.
  ot?: string;
  fechaFinEstimada?: string;
  hrsEstimadas?: number;
}

function usePivotesRegandoAhora() {
  const [logs, setLogs] = useState<LogRiegoMin[]>([]);
  const [cargando, setCargando] = useState(true);
  // FIX 23/9/2026 (bug real reportado, con captura — "esos lotes estan parados y sale regando"):
  // ANTES este hook reconstruía "quién está regando" por su cuenta, quedándose con el evento más
  // reciente de los últimos 500 logs crudos — una versión simplificada que no tenía en cuenta paros
  // no-definitivos, reanudaciones, riegos huérfanos, ni desempates por hora, TODO lo que sí maneja
  // `getPivotState` en AgriRiego (con meses de bugs reales ya corregidos ahí). Podía decir "regando"
  // un pivote que Control, del otro lado, ya mostraba parado. Ahora se lee directo el estado YA
  // CALCULADO que AgriRiego publica (una sola fuente de verdad, ver `estadoPivotesParaCompartirRef`
  // en su App.tsx) — acá no se reconstruye nada, solo se muestra.
  // AMPLIADO 24/9/2026 (pedido explícito — "debe verse la velocidad del pivote"): `velocidadTexto`
  // ya viene formateado desde AgriRiego (`formatearVelocidadTramo`) — puede ser "100%" o, si los
  // lotes de ese tramo tienen velocidades distintas, "70–100%". No se recalcula acá.
  const [estadoPublicado, setEstadoPublicado] = useState<Record<string, { status: string; operator: string; lotes: string[]; desde: string | null; horaArranque?: string | null; fechaFinEstimada?: string | null; velocidadTexto?: string | null; producto: { estado: string; productos: string[] } | null }>>({});
  // AGREGADO 23/9/2026 (pedido explícito — "y muestra la programacion? y lo que estan pedientes
  // sin regar?"): Programaciones que todavía no arrancaron, por pivote.
  const [programacionesPublicadas, setProgramacionesPublicadas] = useState<Record<string, { fechaProgramada: string; ot: string; lotes: string[]; aplicacion: string; programador: string; velocidadTexto?: string | null }[]>>({});
  // AGREGADO 23/9/2026 (pedido explícito — "los cerrados o concluidos las ultimas 24 hrs
  // tambien... con sus horas de arranque y cierre estimado"): riegos cerrados en las últimas 24hs.
  const [cerradosPublicados, setCerradosPublicados] = useState<Record<string, { horaArranque: string; horaCierre: string; fechaFinEstimada: string | null; lotes: string[]; operator: string; velocidadTexto?: string | null; producto: { estado: string; productos: string[] } | null }>>({});

  useEffect(() => {
    const ref = doc(riegoDb, 'artifacts', RIEGO_DB_APP_ID, 'public', 'data', 'estado', 'estadoPivotesActual');
    const unsub = onSnapshot(ref, (snap) => {
      const data = snap.exists() ? (snap.data() as any) : {};
      setEstadoPublicado(data.pivotes || {});
      setProgramacionesPublicadas(data.programaciones || {});
      setCerradosPublicados(data.cerrados || {});
      setCargando(false);
    }, () => setCargando(false));
    return () => unsub();
  }, []);

  // Este segundo listener (crudo, últimos ~500 eventos) sigue existiendo SOLO para
  // `arranquesPorOTRiego` más abajo (hora de arranque real + fin estimado de una OT puntual) — no
  // se usa más para decidir "quién está regando ahora", eso ya viene resuelto del doc de arriba.
  useEffect(() => {
    const q = query(
      collection(riegoDb, 'artifacts', RIEGO_DB_APP_ID, 'public', 'data', 'registrosRiego'),
      orderBy('timestamp', 'desc'),
      limit(500),
    );
    const unsub = onSnapshot(q, (snap) => {
      const data = snap.docs
        .map(d => d.data() as any)
        .filter(l => l.action === 'ARRANQUE')
        .map(l => ({ id: l.id, action: l.action, pivot: l.pivot, timestamp: l.timestamp, operator: l.operator, lotes: l.lotes || l.detallesLotes?.map((x: any) => x.lote) || [], campana: l.campana, ot: l.ot, fechaFinEstimada: l.fechaFinEstimada, hrsEstimadas: l.hrsEstimadas } as LogRiegoMin));
      setLogs(data);
    }, () => {});
    return () => unsub();
  }, []);

  const pivotesRegando = useMemo(() => {
    // FIX 23/9/2026 (bug real reportado — "existen parados por corte de energia, debe jalar el
    // evento tambien hasta q no esté cerrado"): antes SOLO se mostraba un pivote si estaba
    // REGANDO/PENDIENTE_CIERRE — un PARO_ACTIVO (por corte de energía, lluvia, lo que sea) hacía
    // que el pivote desapareciera del todo de este panel, como si el riego ya hubiera terminado.
    // Pero un PARO_ACTIVO NO es un riego cerrado — sigue siendo un evento ABIERTO en AgriRiego
    // (puede reanudarse en cualquier momento) hasta que alguien lo cierre de verdad. Ahora se
    // muestran los 3 estados "abiertos" (todo menos LIBRE), cada uno con su propio color, igual
    // que Control en AgriRiego.
    const resultado: Record<string, { regando: boolean; estado: string; desde: string; horaArranque: string | null; fechaFinEstimada: string | null; velocidadTexto: string | null; operator?: string; lotes: string[]; producto: { estado: string; productos: string[] } | null }> = {};
    Object.entries(estadoPublicado).forEach(([pivote, info]) => {
      resultado[pivote] = {
        regando: info.status === 'REGANDO' || info.status === 'PENDIENTE_CIERRE',
        estado: info.status,
        desde: info.desde || '',
        horaArranque: info.horaArranque || null,
        fechaFinEstimada: info.fechaFinEstimada || null,
        velocidadTexto: info.velocidadTexto || null,
        operator: info.operator,
        lotes: info.lotes || [],
        producto: info.producto || null,
      };
    });
    return resultado;
  }, [estadoPublicado]);

  // AGREGADO 23/9/2026: por N° de OT de riego (el mismo que queda guardado en OTPivote.otRiegoNumero
  // una vez que AgriRiego la programa), la hora real de arranque + fin estimado — para mostrarlo en
  // la propia OT Pivote acá, sin que fumigación tenga que ir y volver entre las dos apps.
  const arranquesPorOTRiego = useMemo(() => {
    const resultado: Record<string, { horaArranqueReal: string; fechaFinEstimada: string | null; hrsEstimadas: number; operator?: string }> = {};
    logs.filter(l => l.action === 'ARRANQUE' && l.ot).forEach(l => {
      const existente = resultado[l.ot!];
      if (!existente || new Date(l.timestamp).getTime() > new Date(existente.horaArranqueReal).getTime()) {
        resultado[l.ot!] = { horaArranqueReal: l.timestamp, fechaFinEstimada: l.fechaFinEstimada || null, hrsEstimadas: l.hrsEstimadas || 0, operator: l.operator };
      }
    });
    return resultado;
  }, [logs]);

  return { pivotesRegando, arranquesPorOTRiego, programacionesPublicadas, cerradosPublicados, cargando };
}

// AGREGADO 23/9/2026 (pedido explícito — "no podrias poner los lotes en ves de L1,2,3 L1L2L3?"):
// primera versión juntaba lotes consecutivos en rangos ("L1-L3, L5") — con lotes NO consecutivos
// (ej. L1 y L3) esto daba "L1, L3", que en la pantalla de Almacén se pegaba después del pivote
// como "P4L1, 3" (el pivote ya trae su propia "L" — ver `ot.pivote} — {ot.lotes...`), no lo que
// se pidió.
// FIX 23/9/2026 (2) (pedido explícito — "dice P4L1,3 en vez de decir P4L1L3"): se saca la lógica
// de rangos con coma y se vuelve a la concatenación simple "L"+número pegado sin separador, que
// es como el resto de la app (AgriRiego) ya arma secuencias de lotes en todos lados.
function formatearLotesLegible(lotes: string[]): string {
  const nums = lotes.map(l => parseInt(String(l).replace(/\D/g, ''), 10)).filter(n => !isNaN(n)).sort((a, b) => a - b);
  return nums.map(n => `L${n}`).join('');
}

// AGREGADO 23/9/2026 (pedido explícito — "no puede mostrar la hora de arranque que horas falta
// para terminar porcentaje nada?"): a partir de la hora de arranque real + fin estimado que ya
// viene publicado desde AgriRiego, calcula cuánto tiempo lleva, cuánto falta y el % avanzado.
function calcularAvancePivote(horaArranque: string | null, fechaFinEstimada: string | null, ahora: Date): { pct: number; faltanTexto: string; vencido: boolean } | null {
  if (!horaArranque || !fechaFinEstimada) return null;
  const ini = new Date(horaArranque).getTime();
  const fin = new Date(fechaFinEstimada).getTime();
  const now = ahora.getTime();
  if (isNaN(ini) || isNaN(fin) || fin <= ini) return null;
  const pct = Math.max(0, Math.min(100, Math.round(((now - ini) / (fin - ini)) * 100)));
  const msFaltan = fin - now;
  const vencido = msFaltan <= 0;
  const minAbs = Math.round(Math.abs(msFaltan) / 60000);
  const h = Math.floor(minAbs / 60), m = minAbs % 60;
  const texto = `${h > 0 ? `${h}h ` : ''}${m}min`;
  return { pct, faltanTexto: vencido ? `pasó la hora hace ${texto}` : `faltan ${texto}`, vencido };
}

function PestanaOTPivote({
  rol,
  campanaActiva,
  usuarioActivo,
}: {
  rol: Rol;
  campanaActiva: string;
  usuarioActivo: string;
}) {
  const [otsPivote, setOtsPivote] = useState<OTPivote[]>([]);
  const [cargando, setCargando] = useState(true);
  const [modalNuevo, setModalNuevo] = useState(false);
  // AGREGADO 24/9/2026 (pedido explícito — "debe tambien poder generar un comprobante para enviar
  // a almacen... ya sea que se genere en ot pivote o en nueva programacion de agririego"): se abre
  // solo, apenas se guarda una OT Pivote nueva, con la tarjeta lista para compartir por WhatsApp.
  const [comprobanteOTPivote, setComprobanteOTPivote] = useState<OTPivote | null>(null);
  const { pivotesRegando, arranquesPorOTRiego, programacionesPublicadas, cerradosPublicados, cargando: cargandoRiego } = usePivotesRegandoAhora();
  // AGREGADO 23/9/2026 (pedido explícito — "no puede mostrar la hora de arranque que horas falta
  // para terminar porcentaje nada?"): reloj propio para que el % avanzado / tiempo restante se
  // recalcule solo mientras la pestaña sigue abierta, sin depender de que llegue un evento nuevo.
  const [nowPivote, setNowPivote] = useState(() => new Date());
  useEffect(() => {
    const t = setInterval(() => setNowPivote(new Date()), 60000);
    return () => clearInterval(t);
  }, []);

  useEffect(() => {
    const cached = cacheGet<OTPivote[]>(COL.ot_pivote, []);
    if (cached.length > 0) { setOtsPivote(cached); setCargando(false); }
    const unsub = onSnapshot(collection(db, COL.ot_pivote), (snap) => {
      const data = snap.docs.map(d => d.data() as OTPivote)
        .sort((a, b) => (b.creadoEn || '').localeCompare(a.creadoEn || ''));
      setOtsPivote(data);
      cacheSet(COL.ot_pivote, data);
      setCargando(false);
    }, () => setCargando(false));
    return () => unsub();
  }, []);

  async function crearOT(ot: Omit<OTPivote, 'id' | 'creadoEn' | 'estado'>) {
    const id = `otpiv_${Date.now()}`;
    const doc: OTPivote = { ...ot, id, creadoPor: ot.creadoPor?.trim() || usuarioActivo, creadoEn: new Date().toISOString(), estado: 'pendiente_programar' };
    setOtsPivote(prev => [doc, ...prev]);
    await dbSet(COL.ot_pivote, id, doc);
    setModalNuevo(false);
    setComprobanteOTPivote(doc);
  }

  async function anularOT(ot: OTPivote) {
    const motivo = window.prompt('Motivo de anulación:');
    if (motivo === null) return; // canceló
    const actualizada: OTPivote = { ...ot, estado: 'anulada', motivoAnulacion: motivo || '(sin motivo)' };
    setOtsPivote(prev => prev.map(o => o.id === ot.id ? actualizada : o));
    await dbSet(COL.ot_pivote, ot.id, actualizada);
  }

  const badge = (estado: OTPivote['estado']) => {
    switch (estado) {
      case 'pendiente_programar': return <span className="text-xs bg-sky-100 text-sky-800 px-2 py-0.5 rounded font-bold">💧 PENDIENTE DE PROGRAMAR</span>;
      case 'programado': return <span className="text-xs bg-amber-100 text-amber-800 px-2 py-0.5 rounded font-bold">🗓️ PROGRAMADO POR RIEGO</span>;
      case 'entregado': return <span className="text-xs bg-green-100 text-green-800 px-2 py-0.5 rounded font-bold">✅ ENTREGADO</span>;
      case 'anulada': return <span className="text-xs bg-gray-200 text-gray-600 px-2 py-0.5 rounded font-bold">✕ ANULADA</span>;
    }
  };

  if (cargando) return <div className="flex justify-center py-20 text-gray-400"><p>⏳ Cargando...</p></div>;

  // REDISEÑO 23/9/2026 (pedido explícito — "debes de tomar este formato, que es para maquinaria",
  // con foto de "Nueva Orden de Trabajo"): antes era un modal chico flotante; ahora es una página
  // completa igual que el formulario de OT de maquinaria — mismo patrón de cabecera con título +
  // botones arriba a la derecha, secciones con título en mayúscula, tabla de productos.
  if (modalNuevo) {
    return (
      <FormularioOTPivote
        campanaActiva={campanaActiva}
        usuarioActivo={usuarioActivo}
        onCancelar={() => setModalNuevo(false)}
        onGuardar={crearOT}
      />
    );
  }

  return (
    <>
    <div className="space-y-3">
      <div className="flex items-center justify-between flex-wrap gap-2">
        <p className="text-sm text-gray-600">
          Orden de aplicación con pivote — la crea fumigación acá, la programa Riego en su propia app.
        </p>
        {rol === 'maestro' && (
          <button onClick={() => setModalNuevo(true)} className="bg-sky-600 text-white px-3 py-1.5 rounded text-sm font-semibold">+ Nueva OT Pivote</button>
        )}
      </div>

      {/* AGREGADO 23/9/2026 — "de igual forma agrifumiga vea lo que se rego y que pivotes estan
          regando, para ellos programar su fumigacion". Lectura en vivo, solo-lectura, del proyecto
          de AgriRiego. Si no aparece nada acá, revisar las reglas de seguridad de Firestore del
          proyecto agririego-app (puede que no dejen leer desde acá).
          FIX 23/9/2026 (bug real reportado — "existen parados por corte de energia, debe jalar el
          evento tambien hasta q no esté cerrado"): ahora se muestra CUALQUIER pivote con un riego
          todavía abierto en AgriRiego, no solo el que está regando en este instante — un PARO por
          corte de energía sigue siendo un riego sin cerrar, así que sigue apareciendo acá (en
          naranja) hasta que alguien lo cierre de verdad del otro lado. */}
      <div className="border border-blue-200 bg-blue-50 rounded-lg p-3">
        <p className="text-xs font-bold text-blue-900 mb-2">💧 Pivotes con riego en curso (AgriRiego)</p>
        {cargandoRiego ? (
          <p className="text-xs text-blue-700">⏳ Cargando estado de riego...</p>
        ) : (
          (() => {
            const abiertos = Object.entries(pivotesRegando); // ya viene filtrado a "todo menos LIBRE" desde AgriRiego
            if (abiertos.length === 0) return <p className="text-xs text-blue-700">Ningún pivote con riego abierto en este momento.</p>;
            const estiloPorEstado: Record<string, { icono: string; clase: string; texto: string }> = {
              REGANDO: { icono: '🟢', clase: 'bg-white border-blue-300 text-blue-900', texto: 'Regando' },
              PENDIENTE_CIERRE: { icono: '🟡', clase: 'bg-amber-50 border-amber-300 text-amber-900', texto: 'Pasó la hora, sin cerrar' },
              PARO_ACTIVO: { icono: '🟠', clase: 'bg-orange-50 border-orange-400 text-orange-900', texto: 'Parado (sin cerrar) — corte, lluvia, etc.' },
            };
            return (
              <div className="flex flex-wrap gap-2">
                {abiertos.map(([pivote, v]) => {
                  const est = estiloPorEstado[v.estado] || estiloPorEstado.REGANDO;
                  const avance = calcularAvancePivote(v.horaArranque, v.fechaFinEstimada, nowPivote);
                  return (
                    <div key={pivote} className={`border rounded px-2 py-1 text-xs ${est.clase}`}>
                      <span className="font-bold">{est.icono} {pivote}</span>
                      <span className="text-gray-500"> · {est.texto}</span>
                      {v.lotes.length > 0 && <span className="text-gray-500"> · {formatearLotesLegible(v.lotes)}</span>}
                      {/* AGREGADO 24/9/2026 (pedido explícito — "debe verse la velocidad del
                          pivote"): viene ya formateado desde AgriRiego (ver `velocidadTexto`). */}
                      {v.velocidadTexto && <span className="text-gray-500"> · Vel: {v.velocidadTexto}</span>}
                      {v.operator && <span className="text-gray-500"> · {v.operator}</span>}
                      {/* AGREGADO 23/9/2026 (pedido explícito — "y los que estan aplicando producto
                          con pivote?"): además de "regando", si ahora mismo hay agroquímico
                          aplicándose de verdad (no solo agua), se marca aparte. */}
                      {v.producto?.estado === 'aplicando' && (
                        <span className="ml-1 bg-red-600 text-white rounded px-1.5 py-0.5 font-bold">☣️ Aplicando: {v.producto.productos.join(', ')}</span>
                      )}
                      {v.producto && v.producto.estado !== 'aplicando' && v.producto.estado !== 'sin_producto' && (
                        <span className="ml-1 text-gray-500">({v.producto.estado === 'concluido' ? 'producto ya aplicado' : v.producto.estado === 'cortado_paro' ? 'producto cortado por el paro' : 'producto pendiente'})</span>
                      )}
                      {/* AGREGADO 23/9/2026 (pedido explícito — "no puede mostrar la hora de
                          arranque que horas falta para terminar porcentaje nada?"): hora de
                          arranque real + % avanzado / tiempo restante contra el fin estimado. */}
                      {v.horaArranque && (
                        <div className="w-full mt-1 pt-1 border-t border-black/10 flex items-center gap-1.5">
                          <span className="text-gray-500">⏱️ Arrancó {new Date(v.horaArranque).toLocaleString('es-BO', { hour12: false, day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' })}</span>
                          {avance && (
                            <>
                              <span className="text-gray-300">·</span>
                              <span className="w-16 h-1.5 bg-black/10 rounded-full overflow-hidden inline-block align-middle">
                                <span className={`h-full block ${avance.vencido ? 'bg-red-500' : 'bg-blue-500'}`} style={{ width: `${avance.pct}%` }} />
                              </span>
                              <span className={avance.vencido ? 'font-bold text-red-700' : 'text-gray-500'}>{avance.pct}% · {avance.faltanTexto}</span>
                            </>
                          )}
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            );
          })()
        )}
      </div>

      {/* AGREGADO 23/9/2026 (pedido explícito — "y muestra la programacion? y lo que estan
          pedientes sin regar?"): Programaciones que Riego ya cargó para este pivote pero todavía
          no arrancó — para que fumigación sepa qué viene, no solo qué está pasando ahora. */}
      {Object.keys(programacionesPublicadas).length > 0 && (
        <div className="border border-sky-200 bg-sky-50 rounded-lg p-3">
          <p className="text-xs font-bold text-sky-900 mb-2">🗓️ Programaciones de riego pendientes de arrancar</p>
          <div className="space-y-1">
            {Object.entries(programacionesPublicadas).flatMap(([pivote, progs]) =>
              progs.map((p, i) => (
                <div key={`${pivote}-${i}`} className="bg-white border border-sky-200 rounded px-2 py-1 text-xs">
                  <span className="font-bold text-sky-900">{pivote}</span>
                  <span className="text-gray-500"> · {p.fechaProgramada ? new Date(p.fechaProgramada).toLocaleString('es-BO', { hour12: false }) : '—'}</span>
                  {p.lotes.length > 0 && <span className="text-gray-500"> · {formatearLotesLegible(p.lotes)}</span>}
                  {p.velocidadTexto && <span className="text-gray-500"> · Vel: {p.velocidadTexto}</span>}
                  {p.aplicacion === 'AGROQUIMICOS' && <span className="ml-1 bg-amber-100 text-amber-800 rounded px-1 font-bold">🧪 con químico</span>}
                  {p.ot && <span className="text-gray-400"> · OT {p.ot}</span>}
                </div>
              ))
            )}
          </div>
        </div>
      )}

      {/* AGREGADO 23/9/2026 (pedido explícito — "los cerrados o concluidos las ultimas 24 hrs
          tambien, con sus horas de arranque y cierre estimado"): riegos que YA cerraron.
          FIX 23/9/2026 (2) (pedido explícito — "borrar lo que dice riegos últimas 24 horas, pone
          mejor los riegos recientes hasta 12 horas nomás"): el corte real ya se achicó a 12h del
          lado de AgriRiego (ver `pivotesRecienCerradosData` en su App.tsx) — acá solo se actualiza
          el texto para que diga lo mismo que de verdad se está filtrando. */}
      {Object.keys(cerradosPublicados).length > 0 && (
        <div className="border border-gray-200 bg-gray-50 rounded-lg p-3">
          <p className="text-xs font-bold text-gray-700 mb-2">✅ Riegos cerrados (últimas 12 hs)</p>
          <div className="space-y-1">
            {Object.entries(cerradosPublicados).map(([pivote, c]) => (
              <div key={pivote} className="bg-white border border-gray-200 rounded px-2 py-1 text-xs">
                <span className="font-bold text-gray-800">{pivote}</span>
                <span className="text-gray-500"> · Arrancó {c.horaArranque ? new Date(c.horaArranque).toLocaleString('es-BO', { hour12: false }) : '—'}</span>
                <span className="text-gray-500"> · Cerró {c.horaCierre ? new Date(c.horaCierre).toLocaleString('es-BO', { hour12: false }) : '—'}</span>
                {c.fechaFinEstimada && <span className="text-gray-400"> (estimado: {new Date(c.fechaFinEstimada).toLocaleString('es-BO', { hour12: false })})</span>}
                {c.lotes.length > 0 && <span className="text-gray-500"> · {formatearLotesLegible(c.lotes)}</span>}
                {c.velocidadTexto && <span className="text-gray-500"> · Vel: {c.velocidadTexto}</span>}
                {c.producto && c.producto.estado !== 'sin_producto' && (
                  <span className="ml-1 bg-amber-100 text-amber-800 rounded px-1 font-bold">🧪 {c.producto.productos.join(', ')}</span>
                )}
              </div>
            ))}
          </div>
        </div>
      )}

      {otsPivote.length === 0 && <p className="text-center text-gray-400 text-sm py-8">Sin OTs de pivote todavía.</p>}

      <div className="space-y-2">
        {otsPivote.map(ot => (
          <div key={ot.id} className={`border rounded-lg p-3 ${ot.estado === 'anulada' ? 'bg-gray-50 border-gray-200 opacity-60' : 'bg-white border-gray-200'}`}>
            <div className="flex items-start justify-between flex-wrap gap-1">
              <div>
                <p className="font-bold text-gray-800 text-sm">💧 {ot.pivote} — {ot.lotes.join(', ')}</p>
                <p className="text-xs text-gray-500">Fecha sugerida: {ot.fechaSugerida} · {ot.campaña}</p>
                <p className="text-[11px] text-gray-400">Creada por {ot.creadoPor} · {new Date(ot.creadoEn).toLocaleString('es-BO')}</p>
              </div>
              {badge(ot.estado)}
            </div>
            {ot.observaciones && <p className="text-xs text-gray-600 mt-1 italic">"{ot.observaciones}"</p>}
            <div className="mt-2 space-y-1">
              {ot.productos.map((p, i) => (
                <p key={i} className="text-xs text-gray-700">• {p.nombre} — {p.dosis} {p.unidad}/ha</p>
              ))}
            </div>
            {/* REDISEÑO 23/9/2026 (pedido explícito — "todo la hora de arranque, tiempo estimado
                q termina osea mas o menos una vista desplegable como en pestaña OT de bitacora"):
                antes era una sola línea fija; ahora es un desplegable con el detalle real de
                ejecución que se lee en vivo desde AgriRiego (hora de arranque real, fin estimado)
                — no solo la fecha PLANEADA que quedó grabada acá al momento de programar. */}
            {(ot.estado === 'programado' || ot.estado === 'entregado') && (() => {
              const ejec = ot.otRiegoNumero ? arranquesPorOTRiego[ot.otRiegoNumero] : undefined;
              return (
                <details className="mt-2 bg-amber-50 rounded px-2 py-1.5 text-xs">
                  <summary className="cursor-pointer font-semibold text-amber-800">
                    🗓️ OT Riego {ot.otRiegoNumero || '—'} — programada {ot.fechaProgramadaReal || '—'}
                    {ejec ? <span className="text-emerald-700"> · ✅ arrancó</span> : <span className="text-gray-500"> · aún no arranca</span>}
                  </summary>
                  <div className="mt-1.5 space-y-0.5 text-gray-700">
                    <p>Programado por: {ot.programadoPor || '—'}</p>
                    {ejec ? (
                      <>
                        <p>Hora de arranque real: <b>{new Date(ejec.horaArranqueReal).toLocaleString('es-BO', { hour12: false })}</b>{ejec.operator ? ` (${ejec.operator})` : ''}</p>
                        <p>Duración estimada: <b>{ejec.hrsEstimadas ? `${ejec.hrsEstimadas.toFixed(1)} h` : '—'}</b></p>
                        <p>Hora estimada de fin: <b>{ejec.fechaFinEstimada ? new Date(ejec.fechaFinEstimada).toLocaleString('es-BO', { hour12: false }) : '—'}</b></p>
                        <p className="text-[10px] text-gray-400">Ojo: es una estimación calculada por AgriRiego al momento de arrancar (según velocidad y pasadas) — si el riego se corta o se retoma en el medio, puede correrse.</p>
                      </>
                    ) : (
                      <p className="text-gray-500">Todavía no se arrancó este riego en AgriRiego.</p>
                    )}
                  </div>
                </details>
              );
            })()}
            {ot.estado === 'anulada' && ot.motivoAnulacion && (
              <p className="text-xs text-gray-500 mt-2">Motivo: {ot.motivoAnulacion}</p>
            )}
            {rol === 'maestro' && ot.estado === 'pendiente_programar' && (
              <button onClick={() => anularOT(ot)} className="mt-2 text-xs text-red-600 font-semibold">✕ Anular</button>
            )}
          </div>
        ))}
      </div>
    </div>
    {comprobanteOTPivote && (
      <ModalCompartirWhatsApp
        contenido={<TarjetaOTPivoteCreada ot={comprobanteOTPivote} />}
        id="ot-pivote-creada-card"
        titulo={`OTPivote_${comprobanteOTPivote.pivote}_${comprobanteOTPivote.fechaSugerida}`}
        onCerrar={() => setComprobanteOTPivote(null)}
      />
    )}
    </>
  );
}

// REDISEÑO 23/9/2026 (pedido explícito, con foto de "Nueva Orden de Trabajo" — "para generar OT
// pivote debes de tomar este formato, que es para maquinaria"): antes `ModalNuevaOTPivote` era un
// popup chico y aparte. Ahora es una página completa con el mismo patrón visual que el formulario
// de OT de maquinaria (título + Cancelar/Guardar arriba a la derecha, secciones con encabezado en
// mayúscula, tabla de productos) — sin los campos que no aplican acá (máquina, implemento,
// validación técnica: eso es de fumigación con máquina, esto es una orden simple para que Riego
// programe una aplicación con pivote).
function FormularioOTPivote({
  campanaActiva, usuarioActivo, onCancelar, onGuardar,
}: {
  campanaActiva: string;
  usuarioActivo: string;
  onCancelar: () => void;
  onGuardar: (ot: Omit<OTPivote, 'id' | 'creadoEn' | 'estado'>) => void;
}) {
  const [pivote, setPivote] = useState('');
  const [lotes, setLotes] = useState('');
  const [fechaSugerida, setFechaSugerida] = useState(fechaLocalISO());
  const [horaSugerida, setHoraSugerida] = useState('08:00');
  const [registradoPor, setRegistradoPor] = useState(usuarioActivo || '');
  const [observaciones, setObservaciones] = useState('');
  const [productos, setProductos] = useState<ProductoOTPivote[]>([{ nombre: '', dosis: 0, unidad: 'L' }]);

  function actualizarProducto(i: number, campo: keyof ProductoOTPivote, valor: string) {
    setProductos(prev => prev.map((p, idx) => idx === i ? { ...p, [campo]: campo === 'dosis' ? (parseFloat(valor) || 0) : valor } : p));
  }

  function confirmar() {
    const lotesArr = lotes.split(',').map(l => l.trim()).filter(Boolean);
    const productosValidos = productos.filter(p => p.nombre.trim() && p.dosis > 0);
    if (!pivote) { alert('Seleccione el pivote.'); return; }
    if (lotesArr.length === 0) { alert('Ingrese al menos un lote.'); return; }
    if (productosValidos.length === 0) { alert('Ingrese al menos un producto con dosis.'); return; }
    if (!registradoPor.trim()) { alert('Ingrese quién registra la OT.'); return; }
    onGuardar({
      pivote, lotes: lotesArr, productos: productosValidos,
      fechaSugerida, horaSugerida: horaSugerida || undefined,
      campaña: campanaActiva, observaciones: observaciones.trim() || undefined,
      creadoPor: registradoPor.trim(),
    });
  }

  return (
    <div className="bg-white rounded-lg p-4 md:p-6 shadow space-y-6">
      <div className="flex items-center justify-between flex-wrap gap-2">
        <h2 className="text-xl font-bold text-gray-800">💧 Nueva OT Pivote</h2>
        <div className="flex gap-2">
          <button onClick={onCancelar} className="bg-gray-200 hover:bg-gray-300 text-gray-700 px-4 py-2 rounded-lg font-medium">
            Cancelar
          </button>
          <button onClick={confirmar} className="bg-sky-600 hover:bg-sky-700 text-white px-4 py-2 rounded-lg font-semibold">
            💾 Guardar OT
          </button>
        </div>
      </div>
      <p className="text-sm text-gray-500 -mt-4">Orden para que Riego programe una aplicación con pivote — no consume stock acá, solo dispara la solicitud a Almacén cuando Riego la programa de verdad.</p>

      {/* Lotes que cubre esta OT — mismo patrón que la OT de maquinaria */}
      <section>
        <h3 className="font-semibold text-gray-700 mb-3 text-sm uppercase tracking-wide">📍 Lotes que cubre esta OT</h3>
        <input
          type="text"
          value={lotes}
          onChange={e => setLotes(e.target.value)}
          placeholder="P6-L3, P6-L4 (separar por coma)"
          className="input"
        />
        <p className="text-xs text-gray-500 mt-1">Escriba los lotes separados por coma</p>
      </section>

      {/* Cabecera */}
      <section>
        <h3 className="font-semibold text-gray-700 mb-3 text-sm uppercase tracking-wide">Cabecera</h3>
        <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
          <Campo label="Pivote">
            <select value={pivote} onChange={e => setPivote(e.target.value)} className="input">
              <option value="">— Seleccionar —</option>
              {PIVOTES_LISTA.map(p => <option key={p}>{p}</option>)}
            </select>
          </Campo>
          <Campo label="Fecha sugerida">
            <input type="date" value={fechaSugerida} onChange={e => setFechaSugerida(e.target.value)} className="input" />
          </Campo>
          <Campo label="Hora sugerida">
            <input type="time" value={horaSugerida} onChange={e => setHoraSugerida(e.target.value)} className="input" />
          </Campo>
          <Campo label="Registrado por (Jefe/Encargado)">
            <input
              type="text"
              value={registradoPor}
              onChange={e => setRegistradoPor(e.target.value)}
              placeholder="Nombre del jefe o encargado"
              className="input"
            />
          </Campo>
        </div>
      </section>

      {/* Productos — mismo patrón de tabla que la OT de maquinaria, sin columnas de tanque (acá
          no aplica, la mezcla la arma Riego al programar de verdad). */}
      <section>
        <div className="flex items-center justify-between mb-2">
          <h3 className="font-semibold text-gray-700 text-sm uppercase tracking-wide">🧪 Productos ({productos.filter(p => p.nombre.trim()).length})</h3>
          <button onClick={() => setProductos(prev => [...prev, { nombre: '', dosis: 0, unidad: 'L' }])} className="text-sm text-sky-600 font-semibold">
            + Agregar producto
          </button>
        </div>
        <div className="overflow-x-auto border border-gray-200 rounded-lg">
          <table className="w-full text-sm">
            <thead className="bg-gray-100">
              <tr>
                <th className="px-2 py-2 text-left w-10">#</th>
                <th className="px-2 py-2 text-left">Producto</th>
                <th className="px-2 py-2 text-right w-28">Dosis</th>
                <th className="px-2 py-2 text-left w-24">Unidad</th>
                <th className="px-2 py-2 w-10"></th>
              </tr>
            </thead>
            <tbody>
              {productos.map((p, i) => (
                <tr key={i} className="border-t border-gray-200">
                  <td className="px-2 py-1 text-gray-400">{i + 1}</td>
                  <td className="px-1 py-1">
                    <input type="text" value={p.nombre} onChange={e => actualizarProducto(i, 'nombre', e.target.value)} placeholder="Nombre del producto" className="input-table w-full" />
                  </td>
                  <td className="px-1 py-1">
                    <input type="number" value={p.dosis || ''} onChange={e => actualizarProducto(i, 'dosis', e.target.value)} placeholder="0" className="input-table w-full text-right" />
                  </td>
                  <td className="px-1 py-1">
                    <input type="text" value={p.unidad} onChange={e => actualizarProducto(i, 'unidad', e.target.value)} placeholder="L/ha" className="input-table w-full" />
                  </td>
                  <td className="px-1 py-1 text-center">
                    <button onClick={() => setProductos(prev => prev.filter((_, idx) => idx !== i))} className="text-red-500 text-xs">✕</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </section>

      <section>
        <h3 className="font-semibold text-gray-700 mb-2 text-sm uppercase tracking-wide">Observaciones (opcional)</h3>
        <textarea value={observaciones} onChange={e => setObservaciones(e.target.value)} rows={2} className="input w-full" />
      </section>

      {/* Mismo CSS inline que usa el formulario de OT de maquinaria — se repite acá porque esta
          pestaña puede abrirse sin haber pasado antes por Predictivo/OT, donde vive el original. */}
      <style>{`
        .input {
          width: 100%;
          padding: 0.5rem 0.75rem;
          border: 1px solid #d1d5db;
          border-radius: 0.5rem;
          font-size: 0.875rem;
          background: white;
        }
        .input:focus {
          outline: none;
          border-color: #16a34a;
          box-shadow: 0 0 0 2px rgba(22,163,74,0.2);
        }
        .input-table {
          width: 100%;
          padding: 0.25rem 0.5rem;
          border: 1px solid #d1d5db;
          border-radius: 0.25rem;
          font-size: 0.875rem;
          background: white;
        }
        .input-table:focus {
          outline: none;
          border-color: #16a34a;
        }
      `}</style>
    </div>
  );
}

function PestanaAlmacen({
  rol,
  ots,
  campanaActiva,
  usuarioActivo,
}: {
  rol: Rol;
  ots: OT[];
  campanaActiva: string;
  usuarioActivo: string;
}) {
  const [productos, setProductos] = useState<ProductoAlmacen[]>([]);
  const [movimientos, setMovimientos] = useState<MovimientoAlmacen[]>([]);
  const [arqueos, setArqueos] = useState<ArqueoAlmacen[]>([]);
  // Responsables de arqueo — lista base + los que se agreguen desde el modal
  const [responsablesExtra, setResponsablesExtra] = useState<string[]>([]);
  // AGREGADO 24/9/2026 (pedido explícito — "que pongan su nombre y q quede logueado... pero ya
  // saca el desplegable por defecto q tomaba a los operadores, igual en almacén arqueo sale por
  // defecto los operadores, está mal"): antes, tanto "Registrar entrega" como "Nuevo arqueo"
  // pre-llenaban el Responsable con `usuarioActivo` — la identidad general de sesión de la app
  // (quien tipeó su nombre al entrar con el PIN compartido de maestro/operador), que no tiene
  // nada que ver con quién es realmente personal de almacén. Si esa sesión quedaba con el nombre
  // de un operador (o del propio jefe, solo revisando algo), ESO se pre-cargaba como si fuera
  // quien entrega o cuenta stock. Ahora hay un identificador APARTE, específico de Almacén,
  // guardado en este dispositivo: se completa recién cuando alguien elige/escribe su nombre acá
  // (nunca automático desde la sesión general), y de ahí en adelante ese dispositivo lo sugiere
  // de nuevo la próxima vez — pero siempre visible y cambiable con un clic, nunca oculto.
  const [responsableAlmacenActivo, setResponsableAlmacenActivo] = useState<string>(() => {
    try { return localStorage.getItem('agrifumiga_almacen_responsable') || ''; } catch { return ''; }
  });
  function usarResponsableAlmacen(nombre: string) {
    const limpio = nombre.trim();
    if (!limpio) return;
    setResponsableAlmacenActivo(limpio);
    try { localStorage.setItem('agrifumiga_almacen_responsable', limpio); } catch {}
  }
  const [cargando, setCargando] = useState(true);
  const [subtab, setSubtab] = useState<'inventario'|'arqueo'|'solicitudes'|'historial'>('inventario');
  const [busqueda, setBusqueda] = useState('');
  const [filtroCategoria, setFiltroCategoria] = useState('');
  const [modalMovimiento, setModalMovimiento] = useState<ProductoAlmacen|null>(null);
  const [modalArqueo, setModalArqueo] = useState(false);
  const [arqueoActivo, setArqueoActivo] = useState<ArqueoAlmacen|null>(null);
  const [modalNuevo, setModalNuevo] = useState(false);
  // AGREGADO 23/9/2026 (solicitudes de riego, ver COL/interfaces arriba)
  const [solicitudesRiego, setSolicitudesRiego] = useState<SolicitudRiego[]>([]);
  // AGREGADO 23/9/2026 (pedido explícito — planilla de historial permanente, aparte del documento
  // de trabajo de arriba): ver `registrarHistorialSolicitud`.
  const [historialSolicitudes, setHistorialSolicitudes] = useState<FilaHistorialSolicitud[]>([]);
  // Contexto de qué solicitud/producto se está entregando cuando se abre el modal de movimiento
  // desde una solicitud (en vez de desde la lista normal de Inventario) — null = modal "normal".
  const [modalMovContexto, setModalMovContexto] = useState<{ solicitudId: string; idx: number } | null>(null);
  // Qué producto REAL del catálogo (af_alm_prod) corresponde a cada línea pedida por texto libre
  // desde AgriRiego — pedido explícito del usuario (opción "B": texto libre allá, se empareja acá
  // a mano, no automático, para no descontar stock del producto equivocado por un nombre parecido
  // pero distinto). Clave: `${solicitudId}-${idx}`.
  const [matchProductoSolicitud, setMatchProductoSolicitud] = useState<Record<string, string>>({});
  // FIX 24/9/2026: texto que el encargado está escribiendo para filtrar el producto real (reemplaza
  // el <select> con cientos de opciones que era imposible de usar — "ay cientos de productos para
  // buscar y así no sirve, mejor si pones texto libre y q vaya filtrando"). Se limpia al elegir uno.
  const [matchProductoBusqueda, setMatchProductoBusqueda] = useState<Record<string, string>>({});
  // AGREGADO 24/9/2026 (pedido explícito — "se podria filtrar por veneno, por foliar, ect
  // diferentes áreas o partes de un químico. Eso ayuda a almacén a llenar la solicitud de
  // productos"): filtro de categoría opcional, junto al texto libre, para achicar la lista antes
  // de escribir el nombre. Usa las mismas CATEGORIAS_ALMACEN del filtro de Inventario.
  const [matchProductoCategoria, setMatchProductoCategoria] = useState<Record<string, string>>({});
  // AGREGADO 24/9/2026 (pedido explícito — "me preocupa que almacén va a tener que tikear producto
  // por producto y se va a molestar... esto lo estoy haciendo para que funcione y sea fácil"):
  // marca los productos donde el emparejamiento automático por nombre EXACTO fue rechazado a mano
  // (botón "cambiar") — para que no se vuelva a auto-completar solo. OJO: esto sigue sin ser
  // matching "parecido" (la decisión anterior de NO auto-matchear por nombre similar sigue en
  // pie) — es solo cuando el nombre coincide EXACTO, letra por letra, con un producto único del
  // catálogo, que es un caso seguro y muy común (el pedido ya nace con el nombre real del
  // producto). Clave: `${solicitudId}-${idx}`, igual que matchProductoSolicitud.
  const [matchProductoAutoOff, setMatchProductoAutoOff] = useState<Record<string, boolean>>({});
  // AGREGADO 24/9/2026: solicitud que se está entregando de una sola vez (todos sus productos
  // pendientes juntos, una sola fecha/responsable) en vez de producto por producto.
  const [modalEntregaTotal, setModalEntregaTotal] = useState<SolicitudRiego | null>(null);
  // AGREGADO 23/9/2026 (pedido explícito — "agregalo, porq asi esta todo desparramau", en
  // respuesta a "el documento final de entrega, como se hace?? que hace?"): el rastro de una
  // entrega queda repartido en Inventario (stock), Movimientos (uno por línea) e Historial (una
  // fila por producto) — no existía un solo comprobante que junte TODO lo de esa solicitud. Este
  // modal arma esa tarjeta consolidada (mismo patrón ya usado para Foto OT / tarjetas de WhatsApp,
  // `capturarYCompartir` + `ModalCompartirWhatsApp`) para una solicitud ya CERRADA.
  const [modalComprobante, setModalComprobante] = useState<SolicitudRiego | null>(null);

  useEffect(() => {
    // Mostrar cache local inmediatamente mientras llega Firestore
    const cachedProds = cacheGet<ProductoAlmacen[]>(COL.almacen_productos, []);
    const cachedMovs = cacheGet<MovimientoAlmacen[]>(COL.almacen_movimientos, []);
    const cachedArqs = cacheGet<ArqueoAlmacen[]>(COL.almacen_arqueos, []);
    if (cachedProds.length > 0 || cachedMovs.length > 0) {
      setProductos(cachedProds);
      setMovimientos(cachedMovs);
      setArqueos(cachedArqs);
      setCargando(false);
    }

    // Listeners en tiempo real para almacén
    const unsubs = [
      onSnapshot(collection(db, COL.almacen_productos), (snap) => {
        const data = snap.docs.map(d => d.data() as ProductoAlmacen);
        setProductos(data);
        cacheSet(COL.almacen_productos, data);
        setCargando(false);
      }, () => setCargando(false)),
      onSnapshot(collection(db, COL.almacen_movimientos), (snap) => {
        const data = snap.docs.map(d => d.data() as MovimientoAlmacen)
          .sort((a,b) => (b.creadoEn||'').localeCompare(a.creadoEn||''));
        setMovimientos(data);
        cacheSet(COL.almacen_movimientos, data);
      }, () => {}),
      onSnapshot(collection(db, COL.almacen_arqueos), (snap) => {
        const data = snap.docs.map(d => d.data() as ArqueoAlmacen)
          .sort((a,b) => (b.fecha||'').localeCompare(a.fecha||''));
        setArqueos(data);
        cacheSet(COL.almacen_arqueos, data);
      }, () => {}),
      // Responsables de almacén agregados a mano desde el modal de arqueo
      onSnapshot(collection(db, COL.almacen_responsables), (snap) => {
        setResponsablesExtra(snap.docs.map(d => (d.data() as any).nombre).filter(Boolean));
      }, () => {}),
      // AGREGADO 23/9/2026: solicitudes que llegan desde AgriRiego (otro proyecto Firebase) y las
      // que genera la propia AgriFumiga por maquinaria — este es el documento DE TRABAJO (se puede
      // editar, cerrar, o borrar a mano si quedó duplicado, ver `eliminarSolicitud`). El registro
      // permanente que no se toca más vive aparte, en `almacen_solicitudes_historial` (abajo).
      onSnapshot(collection(db, COL.almacen_solicitudes_riego), (snap) => {
        const data = snap.docs.map(d => d.data() as SolicitudRiego)
          .sort((a, b) => (b.solicitadoEn || '').localeCompare(a.solicitadoEn || ''));
        setSolicitudesRiego(data);
        cacheSet(COL.almacen_solicitudes_riego, data);
      }, () => {}),
      // AGREGADO 23/9/2026: planilla de historial — una fila por producto entregado, permanente.
      onSnapshot(collection(db, COL.almacen_solicitudes_historial), (snap) => {
        const data = snap.docs.map(d => d.data() as FilaHistorialSolicitud)
          .sort((a, b) => (b.entregadoEn || '').localeCompare(a.entregadoEn || ''));
        setHistorialSolicitudes(data);
        cacheSet(COL.almacen_solicitudes_historial, data);
      }, () => {}),
    ];
    return () => unsubs.forEach(u => u());
  }, []);

  // Lista de responsables para el arqueo: base fija + los agregados a mano,
  // sin duplicados.
  const responsablesAlmacen = [...new Set([...RESPONSABLES_ALMACEN_BASE, ...responsablesExtra])];

  async function agregarResponsableAlmacen(nombre: string) {
    const limpio = nombre.trim();
    if (!limpio) return;
    if (responsablesAlmacen.some(r => r.toLowerCase() === limpio.toLowerCase())) return;
    setResponsablesExtra(prev => [...prev, limpio]);
    const id = limpio.toLowerCase().replace(/[^a-z0-9]+/g, '_');
    await dbSet(COL.almacen_responsables, id, { nombre: limpio, creadoEn: new Date().toISOString() });
  }

  // AGREGADO 24/9/2026 (pedido explícito — "entregada por Pablo vilca y ese es un operador de
  // maquinaria no un encargado o recepcionista de almacén eso no me cuadra"): esta lista es de
  // texto libre — "+ Agregar otro…" (acá y en Arqueo) deja escribir cualquier nombre sin validar
  // que sea realmente personal de almacén, y una vez agregado queda para siempre y aparece en
  // ambos lados. Esto permite sacar un nombre agregado por error (p. ej. el de un operador de
  // máquina que alguien tipeó sin pensar). Restringido a los agregados a mano — los 3 nombres
  // base (RESPONSABLES_ALMACEN_BASE) no se pueden borrar desde acá.
  async function eliminarResponsableAlmacen(nombre: string) {
    if (!confirm(`¿Quitar "${nombre}" de la lista de responsables de almacén?\n\nEsto NO cambia entregas ya registradas con ese nombre — solo evita que se pueda volver a elegir.`)) return;
    setResponsablesExtra(prev => prev.filter(r => r.toLowerCase() !== nombre.toLowerCase()));
    const id = nombre.toLowerCase().replace(/[^a-z0-9]+/g, '_');
    await dbDelete(COL.almacen_responsables, id);
  }

  async function saveProductos(p: ProductoAlmacen[]) {
    setProductos(p);
    cacheSet(COL.almacen_productos, p);
    await Promise.all(p.map(item => dbSet(COL.almacen_productos, item.id, item)));
  }
  async function saveMovimientos(m: MovimientoAlmacen[]) {
    setMovimientos(m);
    cacheSet(COL.almacen_movimientos, m);
    // Guardar todos los movimientos como documentos individuales
    await Promise.all(m.map(item => dbSet(COL.almacen_movimientos, item.id, item)));
  }
  async function saveArqueos(a: ArqueoAlmacen[]) {
    setArqueos(a);
    cacheSet(COL.almacen_arqueos, a);
    await Promise.all(a.map(item => dbSet(COL.almacen_arqueos, item.id, item)));
  }

  async function cargarCatalogo() {
    if (productos.length > 0 && !confirm(`Ya hay ${productos.length} productos. ¿Agregar solo los faltantes?`)) return;
    const exist = new Set(productos.map(p => p.nombre.toLowerCase()));
    const nuevos: ProductoAlmacen[] = CATALOGO_AGROQUIMICOS
      .filter(c => !exist.has(c.nombre.toLowerCase()))
      .map((c, i) => ({
        ...c, id: `prod_${Date.now()}_${i}`,
        stockActual: 0, stockMinimo: 0, observaciones: '', activo: true,
        actualizadoEn: new Date().toISOString(),
      }));
    await saveProductos([...productos, ...nuevos].sort((a,b) => a.nombre.localeCompare(b.nombre)));
    alert(`✅ ${nuevos.length} productos cargados del catálogo.`);
  }

  async function importarExcel(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0]; if (!file) return;
    try {
      const data = await file.arrayBuffer();
      const wb = XLSX.read(data);
      const ws = wb.Sheets[wb.SheetNames[0]];
      const rows = XLSX.utils.sheet_to_json<any>(ws, { header: 1 });
      let hdr = -1;
      for (let i = 0; i < Math.min(rows.length, 10); i++) {
        const r = (rows[i] as any[]).map((c: any) => String(c||'').toLowerCase());
        if (r.some((c: string) => c.includes('producto') || c.includes('codigo') || c.includes('nombre'))) { hdr = i; break; }
      }
      if (hdr < 0) { alert('No se encontró encabezado de productos.'); return; }
      const headers = (rows[hdr] as any[]).map((c: any) => String(c||'').toLowerCase());
      const iN = headers.findIndex((h: string) => h.includes('producto') || h.includes('codigo') || h.includes('nombre'));
      const iU = headers.findIndex((h: string) => h.includes('unidad') || h.includes('udm'));
      const iF = headers.findIndex((h: string) => h.includes('formulac'));
      const iI = headers.findIndex((h: string) => h.includes('ingrediente') || h.includes('activo'));
      const iS = headers.findIndex((h: string) => h.includes('stock') || h.includes('cantidad') || h.includes('existencia'));
      const iM = headers.findIndex((h: string) => h.includes('minim'));
      const exist = new Set(productos.map(p => p.nombre.toLowerCase()));
      const actualizados = [...productos];
      const nuevos: ProductoAlmacen[] = [];
      for (let i = hdr+1; i < rows.length; i++) {
        const row = rows[i] as any[];
        const nombre = iN >= 0 ? String(row[iN]||'').trim() : ''; if (!nombre) continue;
        const stock = iS >= 0 ? parseFloat(String(row[iS]||'0'))||0 : 0;
        if (exist.has(nombre.toLowerCase())) {
          const idx = actualizados.findIndex(p => p.nombre.toLowerCase() === nombre.toLowerCase());
          if (idx >= 0 && iS >= 0) actualizados[idx] = {...actualizados[idx], stockActual: stock, actualizadoEn: new Date().toISOString()};
        } else {
          nuevos.push({
            id: `prod_${Date.now()}_${i}`,
            nombre,
            unidad: iU >= 0 ? String(row[iU]||'').trim() : 'LTS',
            formulacion: iF >= 0 ? String(row[iF]||'').trim() : '',
            ingredienteActivo: iI >= 0 ? String(row[iI]||'').trim() : '',
            categoria: 'Sin categoría',
            stockActual: stock,
            stockMinimo: iM >= 0 ? parseFloat(String(row[iM]||'0'))||0 : 0,
            observaciones: '', activo: true,
            actualizadoEn: new Date().toISOString(),
          });
          exist.add(nombre.toLowerCase());
        }
      }
      await saveProductos([...actualizados, ...nuevos].sort((a,b) => a.nombre.localeCompare(b.nombre)));
      alert(`✅ Importación: ${nuevos.length} nuevos, ${actualizados.length} actualizados.`);
    } catch (err) { alert('Error al leer el Excel: ' + (err as Error).message); }
    e.target.value = '';
  }

  async function aplicarMovimiento(
    prod: ProductoAlmacen, tipo: 'ingreso'|'egreso'|'ajuste',
    cantidad: number, tipoAplicacion: TipoAplicacion,
    otNumero: string, otRiegoNumero: string, maquina: string,
    pivot: string, lotesSelec: string[], responsable: string, obs: string, fecha: string
  ) {
    const stockAntes = prod.stockActual;
    let stockDespues = tipo === 'ingreso' ? stockAntes + cantidad : tipo === 'egreso' ? Math.max(0, stockAntes - cantidad) : cantidad;
    const prodActualizado = { ...prod, stockActual: stockDespues, actualizadoEn: new Date().toISOString() };
    await saveProductos(productos.map(p => p.id === prod.id ? prodActualizado : p));
    const mov: MovimientoAlmacen = {
      id: `mov_${Date.now()}`,
      productoId: prod.id, productoNombre: prod.nombre, unidad: prod.unidad,
      tipo, tipoAplicacion: tipo === 'egreso' ? tipoAplicacion : undefined,
      cantidad, stockAntes, stockDespues,
      otNumero, otRiegoNumero: otRiegoNumero || undefined,
      maquina: maquina || undefined, pivot: pivot || undefined,
      lotes: lotesSelec, campaña: campanaActiva,
      responsable, observaciones: obs, fecha,
      creadoEn: new Date().toISOString(),
    };
    await saveMovimientos([mov, ...movimientos]);
    // AGREGADO 23/9/2026: si este movimiento se generó desde una solicitud de riego (botón
    // "Registrar entrega" de la sección Solicitudes), marcar ese producto como entregado en la
    // solicitud y recalcular su estado — sin esto, el movimiento queda igual creado (nada se
    // pierde) pero la solicitud se quedaría en "pendiente" para siempre.
    if (modalMovContexto) {
      await marcarSolicitudEntregada(modalMovContexto.solicitudId, modalMovContexto.idx, cantidad, mov.id, responsable, fecha);
      setModalMovContexto(null);
    }
    setModalMovimiento(null);
  }

  // AGREGADO 23/9/2026: marca una solicitud "en_curso" (almacén la abrió para atenderla) —
  // pedido explícito: "que almacen escoja cual atender al abrir que diga en curso".
  async function atenderSolicitud(sol: SolicitudRiego) {
    if (sol.estado !== 'pendiente') return;
    const actualizada: SolicitudRiego = { ...sol, estado: 'en_curso', abiertoPor: usuarioActivo, abiertoEn: new Date().toISOString() };
    setSolicitudesRiego(prev => prev.map(s => s.id === sol.id ? actualizada : s));
    await dbSet(COL.almacen_solicitudes_riego, sol.id, actualizada);
  }

  // AGREGADO 24/9/2026 (pedido explícito — "esto lo estoy haciendo para q funcione y sea fácil, q
  // me propones" — la preocupación era que almacén tenga que "tikear producto por producto" y se
  // moleste): producto de catálogo emparejado para la línea `idx` de la solicitud `solId`, SIN
  // tener que buscarlo a mano — pero solo cuando el nombre pedido coincide EXACTO (no "parecido")
  // con un único producto activo del catálogo. Esto no cambia la decisión anterior de no
  // auto-matchear por nombre similar (ver comentario junto a matchProductoSolicitud) — un nombre
  // idéntico letra por letra es un caso distinto y seguro, muy común porque el pedido ya nace con
  // el nombre real del producto (viene del Predictivo/OT, no de un texto tipeado a mano). Si el
  // encargado ya eligió uno a mano, o rechazó el automático con "cambiar", ese siempre manda.
  function obtenerMatchId(solId: string, idx: number, nombre: string): string | null {
    const key = `${solId}-${idx}`;
    const manual = matchProductoSolicitud[key];
    if (manual) return manual;
    if (matchProductoAutoOff[key]) return null;
    const limpio = nombre.trim().toLowerCase();
    const candidatos = productos.filter(pr => pr.activo !== false && pr.nombre.trim().toLowerCase() === limpio);
    return candidatos.length === 1 ? candidatos[0].id : null;
  }

  // AGREGADO 24/9/2026: entrega TODOS los productos pendientes de una solicitud de una sola vez —
  // una fecha, un responsable, una confirmación — en vez de repetir el flujo completo (buscar,
  // Entregar, confirmar) una vez por producto. Solo se habilita desde la UI cuando TODOS los
  // productos pendientes ya tienen un match (automático o manual) — acá se revalida por las
  // dudas. Construye el array final de productos de la solicitud EN UNA SOLA PASADA (no reusa
  // marcarSolicitudEntregada en loop — llamarla varias veces seguidas para la misma solicitud
  // pisaría cada vez el resultado de la anterior, porque parte de un snapshot que no se actualiza
  // entre llamadas dentro del mismo click).
  async function entregarSolicitudCompleta(sol: SolicitudRiego, cantidades: Record<number, number>, responsable: string, fecha: string) {
    const productosAct = [...productos];
    const movNuevos: MovimientoAlmacen[] = [];
    const solProductosAct = sol.productos.map((p, idx) => {
      if (p.entregado) return p;
      const matchId = obtenerMatchId(sol.id, idx, p.nombre);
      if (!matchId) return p; // no debería pasar — el botón queda deshabilitado si falta emparejar alguno
      const cantidad = cantidades[idx] ?? p.cantidadEstimada;
      const prodIdx = productosAct.findIndex(pr => pr.id === matchId);
      if (prodIdx < 0) return p;
      const prodActual = productosAct[prodIdx];
      const stockAntes = prodActual.stockActual;
      const stockDespues = Math.max(0, stockAntes - cantidad);
      productosAct[prodIdx] = { ...prodActual, stockActual: stockDespues, actualizadoEn: new Date().toISOString() };
      const mov: MovimientoAlmacen = {
        id: `mov_${Date.now()}_${idx}`,
        productoId: prodActual.id, productoNombre: prodActual.nombre, unidad: prodActual.unidad,
        tipo: 'egreso', tipoAplicacion: sol.origen === 'maquinaria' ? 'maquinaria' : 'pivote',
        cantidad, stockAntes, stockDespues,
        otNumero: sol.origen === 'maquinaria' ? (sol.otNumero || '') : '',
        otRiegoNumero: sol.origen === 'riego' ? (sol.otRiegoNumero || undefined) : undefined,
        maquina: sol.origen === 'maquinaria' ? sol.maquina : undefined,
        pivot: sol.origen === 'riego' ? sol.pivot : undefined,
        lotes: sol.lotes || [], campaña: sol.campaña,
        responsable, observaciones: `Entrega completa de solicitud (${sol.productos.length} producto${sol.productos.length===1?'':'s'})`, fecha,
        creadoEn: new Date().toISOString(),
      };
      movNuevos.push(mov);
      return { ...p, entregado: true, cantidadEntregada: cantidad, movimientoId: mov.id };
    });
    await saveProductos(productosAct);
    if (movNuevos.length > 0) await saveMovimientos([...movNuevos, ...movimientos]);
    const todosEntregados = solProductosAct.every(p => p.entregado);
    const solActualizada: SolicitudRiego = {
      ...sol, productos: solProductosAct,
      estado: todosEntregados ? 'cerrado' : 'en_curso',
      ...(todosEntregados ? { cerradoPor: responsable, cerradoEn: new Date().toISOString() } : {}),
    };
    setSolicitudesRiego(prev => prev.map(s => s.id === sol.id ? solActualizada : s));
    await dbSet(COL.almacen_solicitudes_riego, sol.id, solActualizada);
    if (todosEntregados) await registrarHistorialSolicitud(solActualizada);
    usarResponsableAlmacen(responsable);
    setModalEntregaTotal(null);
  }

  // AGREGADO 23/9/2026 (pedido explícito — "se podria eliminar cierto?", por si queda una
  // duplicada): borra el registro de la solicitud en sí. OJO — si ya estaba CERRADA (con productos
  // entregados de verdad), borrar esto NO deshace el movimiento de stock ya hecho en Inventario;
  // solo saca este "pedido" de la lista. Por eso queda restringido a maestro, con confirmación.
  async function eliminarSolicitud(sol: SolicitudRiego) {
    const msg = sol.estado === 'cerrado'
      ? '⚠️ Esta solicitud ya está CERRADA (con productos entregados). Borrarla acá NO revierte el movimiento de stock que ya se hizo — solo elimina este registro/pedido. ¿Seguro que es un duplicado y querés borrarla igual?'
      : '¿Eliminar esta solicitud? (por ejemplo, si quedó duplicada)';
    if (!window.confirm(msg)) return;
    setSolicitudesRiego(prev => prev.filter(s => s.id !== sol.id));
    try { await deleteDoc(doc(db, COL.almacen_solicitudes_riego, sol.id)); } catch (e) { console.error('[eliminarSolicitud] ERROR:', e); }
  }

  // AGREGADO 23/9/2026: actualiza el producto `idx` de una solicitud como entregado y recalcula
  // el estado global (cierra sola cuando TODOS sus productos quedan entregados).
  async function marcarSolicitudEntregada(solicitudId: string, idx: number, cantidadEntregada: number, movimientoId: string, responsable: string, fecha: string) {
    const sol = solicitudesRiego.find(s => s.id === solicitudId);
    if (!sol) return;
    const productosAct = sol.productos.map((p, i) => i === idx
      ? { ...p, entregado: true, cantidadEntregada, movimientoId }
      : p);
    const todosEntregados = productosAct.every(p => p.entregado);
    const estado: SolicitudRiego['estado'] = todosEntregados ? 'cerrado' : 'en_curso';
    const solActualizada: SolicitudRiego = {
      ...sol, productos: productosAct, estado,
      ...(todosEntregados ? { cerradoPor: responsable, cerradoEn: new Date().toISOString() } : {}),
    };
    setSolicitudesRiego(prev => prev.map(s => s.id === solicitudId ? solActualizada : s));
    await dbSet(COL.almacen_solicitudes_riego, solicitudId, solActualizada);
    if (todosEntregados) await registrarHistorialSolicitud(solActualizada);
  }

  // ===== VISTAS =====
  const productosFiltrados = productos
    .filter(p => p.activo !== false)
    .filter(p => !busqueda || p.nombre.toLowerCase().includes(busqueda.toLowerCase()) || p.ingredienteActivo.toLowerCase().includes(busqueda.toLowerCase()))
    .filter(p => !filtroCategoria || p.categoria === filtroCategoria)
    .sort((a,b) => a.nombre.localeCompare(b.nombre));

  const sinStock = productos.filter(p => p.activo !== false && p.stockActual === 0).length;
  const bajoMin = productos.filter(p => p.activo !== false && p.stockMinimo > 0 && p.stockActual <= p.stockMinimo && p.stockActual > 0).length;
  const solicitudesPendientesCount = solicitudesRiego.filter(s => s.estado !== 'cerrado').length;

  if (cargando) return <div className="flex justify-center py-20 text-gray-400"><p>⏳ Cargando almacén...</p></div>;

  return (
    <div className="space-y-4">
      {rol === 'operador' && (
        <div className="bg-amber-50 border border-amber-200 rounded px-3 py-1.5 text-amber-800 text-center text-xs font-semibold">
          🔒 Solo lectura — consulte con el encargado para movimientos o arqueos
        </div>
      )}
      {/* Alertas */}
      {(sinStock > 0 || bajoMin > 0 || solicitudesPendientesCount > 0) && (
        <div className="flex gap-2 flex-wrap">
          {solicitudesPendientesCount > 0 && (
            <button onClick={() => setSubtab('solicitudes')} className="bg-sky-100 border border-sky-300 rounded px-3 py-1.5 text-xs text-sky-800 font-semibold hover:bg-sky-200">
              📋 {solicitudesPendientesCount} solicitud{solicitudesPendientesCount === 1 ? '' : 'es'} pendiente{solicitudesPendientesCount === 1 ? '' : 's'}
            </button>
          )}
          {sinStock > 0 && <div className="bg-red-100 border border-red-300 rounded px-3 py-1.5 text-xs text-red-800 font-semibold">🔴 {sinStock} SIN STOCK</div>}
          {bajoMin > 0 && <div className="bg-yellow-100 border border-yellow-300 rounded px-3 py-1.5 text-xs text-yellow-800 font-semibold">🟡 {bajoMin} bajo mínimo</div>}
        </div>
      )}

      <div className="bg-white rounded-lg shadow overflow-hidden">
        {/* Sub-tabs */}
        <div className="bg-slate-800 flex overflow-x-auto">
          {[
            {id:'inventario',label:'📦 Inventario'},
            {id:'arqueo',label:'🔍 Arqueo'},
            {id:'solicitudes',label:`📋 Solicitudes${solicitudesPendientesCount > 0 ? ` (${solicitudesPendientesCount})` : ''}`},
            {id:'historial',label:'📜 Historial'},
          ].map(t => (
            <button key={t.id} onClick={() => setSubtab(t.id as any)}
              className={`px-4 py-2.5 font-semibold text-sm whitespace-nowrap transition-colors ${subtab===t.id ? 'bg-green-600 text-white' : 'bg-slate-700 text-slate-300 hover:bg-slate-600 hover:text-white'}`}>
              {t.label}
            </button>
          ))}
        </div>

        {/* ===== INVENTARIO — Semáforos + saldo ===== */}
        {subtab === 'inventario' && (
          <div className="p-3 space-y-2">
            {/* Cabecera + acciones */}
            <div className="flex items-center justify-between flex-wrap gap-2">
              <p className="text-xs text-gray-500 font-medium">
                {productosFiltrados.filter(p=>p.stockActual>0).length} con stock ·{' '}
                {productosFiltrados.filter(p=>p.stockActual===0).length} sin stock ·{' '}
                {productosFiltrados.filter(p=>p.stockMinimo>0 && p.stockActual>0 && p.stockActual<=p.stockMinimo).length} bajos
              </p>
              {rol === 'maestro' && (
                <div className="flex gap-1.5 flex-wrap">
                  <button onClick={cargarCatalogo} className="bg-gray-700 text-white px-2 py-1 rounded text-xs">📋 Catálogo</button>
                  <label className="bg-indigo-600 text-white px-2 py-1 rounded text-xs cursor-pointer">
                    📥 Excel<input type="file" accept=".xlsx,.xls" onChange={importarExcel} className="hidden" />
                  </label>
                  <button onClick={() => setModalNuevo(true)} className="bg-green-600 text-white px-2 py-1 rounded text-xs">+ Nuevo</button>
                </div>
              )}
            </div>
            {/* Filtros */}
            <div className="flex gap-2 flex-wrap">
              <input type="text" placeholder="🔍 Buscar..." value={busqueda} onChange={e => setBusqueda(e.target.value)} className="input flex-1 min-w-[120px] text-sm" />
              <select value={filtroCategoria} onChange={e => setFiltroCategoria(e.target.value)} className="input text-sm">
                <option value="">Todas</option>
                {CATEGORIAS_ALMACEN.map(c => <option key={c}>{c}</option>)}
              </select>
            </div>
            {productosFiltrados.length === 0 ? (
              <div className="text-center py-10 text-gray-400">
                <p className="text-3xl mb-2">📦</p>
                <p className="text-sm">{productos.length === 0 ? 'Sin productos. Use "Catálogo" para cargar los 85 del Excel.' : 'Sin resultados.'}</p>
              </div>
            ) : (
              /* Tabla compacta con semáforos */
              <div className="bg-white rounded border overflow-hidden">
                {/* Header tabla */}
                <div className="grid grid-cols-[20px_1fr_auto_auto] gap-2 px-3 py-1.5 bg-gray-100 text-xs text-gray-500 font-semibold border-b">
                  <span></span>
                  <span>Producto</span>
                  <span className="text-right">Saldo</span>
                  <span></span>
                </div>
                {productosFiltrados.map((p, idx) => {
                  const sin = p.stockActual === 0;
                  const bajo = p.stockMinimo > 0 && p.stockActual > 0 && p.stockActual <= p.stockMinimo;
                  const ok = !sin && !bajo;
                  const semaforo = sin ? '🔴' : bajo ? '🟡' : '🟢';
                  const movsProd = movimientos.filter(m => m.productoNombre === p.nombre).slice(0,1);
                  const ultimoMov = movsProd[0];
                  return (
                    <div key={p.id}
                      className={`grid grid-cols-[20px_1fr_auto_auto] gap-2 px-3 py-2 items-center text-xs border-b border-gray-50 ${
                        sin ? 'bg-red-50' : bajo ? 'bg-yellow-50' : idx%2===0 ? 'bg-white' : 'bg-gray-50'
                      }`}
                    >
                      {/* Semáforo */}
                      <span className="text-base leading-none" title={sin?'Sin stock':bajo?'Bajo mínimo':'Stock OK'}>
                        {semaforo}
                      </span>
                      {/* Nombre + última actividad */}
                      <div className="min-w-0">
                        <p className="font-semibold text-gray-800 truncate">{p.nombre}</p>
                        <p className="text-gray-400 text-[10px] truncate">
                          {p.categoria}
                          {ultimoMov && ` · último mov: ${ultimoMov.fecha}`}
                        </p>
                      </div>
                      {/* Saldo disponible */}
                      <div className="text-right flex-shrink-0">
                        <span className={`font-bold text-sm ${sin?'text-red-600':bajo?'text-yellow-600':'text-green-700'}`}>
                          {p.stockActual % 1 === 0 ? p.stockActual : p.stockActual.toFixed(2)}
                        </span>
                        <span className="text-gray-400 ml-1 text-[10px]">{p.unidad}</span>
                        {p.stockMinimo > 0 && (
                          <p className="text-[10px] text-gray-400">mín: {p.stockMinimo}</p>
                        )}
                      </div>
                      {/* Botón movimiento */}
                      {rol === 'maestro' && (
                        <button onClick={() => setModalMovimiento(p)}
                          className="bg-blue-600 hover:bg-blue-700 text-white px-2 py-1 rounded text-[10px] flex-shrink-0 whitespace-nowrap">
                          ±
                        </button>
                      )}
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        )}

        {/* ===== ARQUEO ===== */}
        {subtab === 'arqueo' && (
          <div className="p-3 space-y-3">
            <div className="flex items-center justify-between flex-wrap gap-2">
              <div>
                <h2 className="font-bold text-gray-800">🔍 Arqueos de Inventario</h2>
                <p className="text-xs text-gray-500">Compare stock teórico vs físico contado</p>
              </div>
              {rol === 'maestro' && productos.length > 0 && (
                <button
                  onClick={() => {
                    const borrador = arqueos.find(a => a.estado === 'borrador');
                    if (borrador) { setArqueoActivo(borrador); }
                    else {
                      setArqueoActivo({
                        id: `arq_${Date.now()}`,
                        fecha: fechaLocalISO(),
                        // FIX 24/9/2026: antes era `usuarioActivo` (identidad general de sesión,
                        // podía ser cualquiera) — ahora sugiere el último responsable DE ALMACÉN
                        // usado en este dispositivo, siempre visible/cambiable en el modal.
                        responsable: responsablesAlmacen.includes(responsableAlmacenActivo) ? responsableAlmacenActivo : '',
                        estado: 'borrador',
                        items: productos.filter(p => p.activo !== false).sort((a,b) => a.nombre.localeCompare(b.nombre)).map(p => ({
                          productoId: p.id, productoNombre: p.nombre, unidad: p.unidad,
                          stockTeorico: p.stockActual, stockFisico: p.stockActual, diferencia: 0, observaciones: '',
                        })),
                        creadoEn: new Date().toISOString(),
                      });
                    }
                    setModalArqueo(true);
                  }}
                  className="bg-purple-600 hover:bg-purple-700 text-white px-3 py-1.5 rounded text-xs font-semibold"
                >
                  {arqueos.find(a => a.estado === 'borrador') ? '📋 Continuar arqueo' : '+ Nuevo arqueo'}
                </button>
              )}
            </div>
            {rol === 'maestro' && arqueos.find(a => a.estado === 'borrador') && (
              <div className="bg-yellow-50 border-2 border-yellow-300 rounded-lg p-3 flex items-center justify-between">
                <div>
                  <span className="text-xs font-bold text-yellow-800 bg-yellow-200 px-2 py-0.5 rounded">⏳ EN CURSO</span>
                  <p className="text-sm font-semibold mt-1">Arqueo del {arqueos.find(a=>a.estado==='borrador')?.fecha}</p>
                </div>
                <button onClick={() => { setArqueoActivo(arqueos.find(a=>a.estado==='borrador')!); setModalArqueo(true); }}
                  className="bg-yellow-600 hover:bg-yellow-700 text-white px-3 py-1.5 rounded text-xs">Continuar →</button>
              </div>
            )}
            {arqueos.filter(a => a.estado === 'cerrado').length === 0 && !arqueos.find(a => a.estado === 'borrador') ? (
              <div className="text-center py-10 text-gray-400"><p className="text-3xl mb-2">🔍</p><p>Sin arqueos registrados.</p></div>
            ) : (
              <div className="space-y-2">
                {arqueos.filter(a => a.estado === 'cerrado').map(arq => {
                  const conDif = arq.items.filter(i => Math.abs(i.diferencia) > 0.001).length;
                  return (
                    <div key={arq.id} className="bg-white border border-gray-200 rounded-lg p-3">
                      <div className="flex items-center justify-between flex-wrap gap-2">
                        <div>
                          <p className="font-semibold text-sm">Arqueo {arq.fecha}</p>
                          <p className="text-xs text-gray-500">
                            {arq.responsable} · {arq.items.length} productos ·{' '}
                            {conDif > 0 ? <span className="text-red-600 font-semibold">{conDif} diferencia{conDif>1?'s':''}</span> : <span className="text-green-600 font-semibold">Sin diferencias ✅</span>}
                          </p>
                        </div>
                        <span className="text-xs bg-green-100 text-green-800 px-2 py-0.5 rounded font-bold">✅ CERRADO</span>
                      </div>
                      {conDif > 0 && (
                        <div className="mt-2 space-y-1">
                          {arq.items.filter(i => Math.abs(i.diferencia) > 0.001).map(it => (
                            <div key={it.productoId} className="flex justify-between text-xs">
                              <span className="text-gray-700">{it.productoNombre}</span>
                              <span className={it.diferencia<0?'text-red-600 font-semibold':'text-green-600 font-semibold'}>
                                {it.diferencia>0?'+':''}{it.diferencia.toFixed(2)} {it.unidad}
                              </span>
                            </div>
                          ))}
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        )}

        {/* ===== SOLICITUDES DE RIEGO — vienen de AgriRiego (otro proyecto Firebase) ===== */}
        {subtab === 'solicitudes' && (() => {
          // FIX 24/9/2026 (pedido explícito — "al cerrar los productos en almacen debe desaparecer
          // de pestaña solicitud y ponerce en historial archivado de almacen"): antes una solicitud
          // ya CERRADA se quedaba acá para siempre (solo bajaba al final de la lista) — se veía
          // duplicada, porque el mismo dato ya está en la pestaña Historial (una fila por producto
          // entregado, con fecha/OT/responsable). Ahora, apenas queda cerrada, desaparece de acá.
          const solicitudesAbiertas = solicitudesRiego.filter(s => s.estado !== 'cerrado');
          return (
          <div className="p-3 space-y-3">
            {solicitudesAbiertas.length === 0 && (
              <p className="text-center text-gray-400 text-sm py-8">Sin solicitudes pendientes — las entregadas quedan en Historial.</p>
            )}
            {[...solicitudesAbiertas].sort((a, b) => {
              const orden = { pendiente: 0, en_curso: 1, cerrado: 2 };
              return orden[a.estado] - orden[b.estado] || (b.solicitadoEn || '').localeCompare(a.solicitadoEn || '');
            }).map(sol => {
              const badge = sol.estado === 'cerrado'
                ? <span className="text-xs bg-green-100 text-green-800 px-2 py-0.5 rounded font-bold">✅ CERRADO</span>
                : sol.estado === 'en_curso'
                ? <span className="text-xs bg-amber-100 text-amber-800 px-2 py-0.5 rounded font-bold">🟡 EN CURSO</span>
                : <span className="text-xs bg-sky-100 text-sky-800 px-2 py-0.5 rounded font-bold">📋 PENDIENTE</span>;
              const origenIcono = sol.origen === 'maquinaria' ? '🚜' : '💧';
              return (
                <div key={sol.id} className={`border rounded-lg p-3 ${sol.estado === 'cerrado' ? 'bg-gray-50 border-gray-200' : 'bg-sky-50 border-sky-200'}`}>
                  <div className="flex items-start justify-between flex-wrap gap-1">
                    <div>
                      <p className="font-bold text-gray-800 text-sm">{origenIcono} {sol.origen === 'maquinaria' ? sol.maquina : sol.pivot} — {sol.lotes.join(', ')}</p>
                      <p className="text-xs text-gray-500">
                        {sol.origen === 'maquinaria' ? `OT Fumigación: ${sol.otNumero || '—'}` : `OT Riego: ${sol.otRiegoNumero || '—'}`} · Fecha: {sol.fecha} · {sol.campaña}
                      </p>
                      <p className="text-[11px] text-gray-400">Pedido por {sol.solicitadoPor} · {new Date(sol.solicitadoEn).toLocaleString('es-BO')}</p>
                      {sol.abiertoPor && <p className="text-[11px] text-amber-600">Atendido por {sol.abiertoPor} · {new Date(sol.abiertoEn!).toLocaleString('es-BO')}</p>}
                    </div>
                    <div className="flex items-center gap-1.5">
                      {badge}
                      {sol.estado === 'cerrado' && (
                        <button onClick={() => setModalComprobante(sol)} title="Ver/compartir comprobante de entrega" className="text-xs bg-gray-100 hover:bg-gray-200 text-gray-700 font-semibold px-2 py-0.5 rounded">🧾 Comprobante</button>
                      )}
                      {rol === 'maestro' && (
                        <button onClick={() => eliminarSolicitud(sol)} title="Eliminar (ej: duplicada)" className="text-gray-400 hover:text-red-600 text-xs px-1">✕</button>
                      )}
                    </div>
                  </div>
                  {sol.observaciones && <p className="text-xs text-gray-600 mt-1 italic">"{sol.observaciones}"</p>}

                  {/* FIX 24/9/2026 (pedido explícito — "si existe una solicitud en almacén y
                      derrepente quiero yo verificar si esa solicitud está bien hecha la abro y
                      queda como q yo la recepcione, y no soy yo el de almacén, y no debería de
                      ser así"): antes, mientras la solicitud estaba PENDIENTE, la lista de
                      productos ni se mostraba — la única forma de verla era clickear "Atender
                      esta solicitud", que YA marca `abiertoPor` = quien esté logueado en ese
                      momento. Revisar el pedido (ver si está bien armado) no debería contar como
                      atenderlo. Ahora los productos se ven SIEMPRE, sin necesidad de "atender"
                      primero; "Atender esta solicitud" queda como un paso aparte y explícito (más
                      abajo), solo para cuando alguien de almacén realmente va a empezar a
                      prepararla. */}
                  <div className="mt-2 space-y-1.5">
                    {sol.productos.map((p, idx) => {
                      const key = `${sol.id}-${idx}`;
                      return (
                        <div key={idx} className="flex items-center justify-between gap-2 bg-white rounded border border-gray-200 px-2 py-1.5">
                          <div className="min-w-0">
                            <p className="text-sm font-semibold text-gray-800 truncate">{p.nombre}</p>
                            <p className="text-xs text-gray-500">Dosis: {p.dosis} {p.unidad}/ha · Estimado: {p.cantidadEstimada.toFixed(2)} {p.unidad}</p>
                          </div>
                          {p.entregado ? (
                            <span className="text-xs text-green-700 font-semibold whitespace-nowrap">✅ {p.cantidadEntregada?.toFixed(2)} {p.unidad}</span>
                          ) : sol.estado === 'pendiente' ? (
                            <span className="text-xs text-gray-400 whitespace-nowrap" title="Todavía nadie de almacén la atendió">sin atender</span>
                          ) : rol === 'operador' ? (
                            <span className="text-xs text-gray-400 whitespace-nowrap">pendiente</span>
                          ) : (() => {
                              // AGREGADO 24/9/2026 (pedido explícito — "me preocupa q almacén va a
                              // tener q tikear producto por producto y se va a molestar"): si el
                              // nombre pedido coincide EXACTO con un único producto del catálogo
                              // (`obtenerMatchId`), se salta el paso de buscar/elegir — se muestra
                              // ya emparejado, con "cambiar" siempre a la vista por si no es el
                              // correcto. Sigue sin auto-matchear por nombre "parecido" (esa
                              // decisión no cambió), solo por nombre idéntico.
                              const matchId = obtenerMatchId(sol.id, idx, p.nombre);
                              const prodMatch = matchId ? productos.find(pr => pr.id === matchId) : null;
                              const esAuto = !!prodMatch && !matchProductoSolicitud[key];
                              if (prodMatch) {
                                return (
                                  <div className="flex items-center gap-1.5">
                                    <div className="text-right">
                                      <p className="text-xs text-gray-700 font-medium leading-tight">{prodMatch.nombre}</p>
                                      <p className="text-[10px] text-gray-400 leading-tight">
                                        Stock: {prodMatch.stockActual.toFixed(1)} {prodMatch.unidad}
                                        {esAuto && <span className="text-emerald-600"> · ✓ automático</span>}
                                        {' · '}
                                        <button type="button" onClick={() => {
                                          setMatchProductoSolicitud(m => ({ ...m, [key]: '' }));
                                          setMatchProductoAutoOff(m => ({ ...m, [key]: true }));
                                        }} className="text-sky-600 underline">cambiar</button>
                                      </p>
                                    </div>
                                    <button
                                      onClick={() => {
                                        setModalMovContexto({ solicitudId: sol.id, idx });
                                        setModalMovimiento(prodMatch);
                                      }}
                                      className="bg-sky-600 text-white text-xs px-2 py-1 rounded font-semibold whitespace-nowrap">
                                      Entregar
                                    </button>
                                  </div>
                                );
                              }
                              return (
                            <div
                              className="flex items-center gap-1 relative"
                              // FIX 24/9/2026 (2) (pedido explícito — "al escoger para tikear producto se
                              // queda pegada asi mira aunq de clic en otro lado de la pantalla"): la lista
                              // desplegable solo se ocultaba al elegir un producto — un click afuera (en
                              // cualquier otra parte de la pantalla) no la cerraba y se quedaba pegada. Ahora,
                              // cuando el foco sale de este grupo (input/select/botones de la lista) hacia
                              // cualquier otro lado, se cierra sola.
                              onBlur={(e) => {
                                if (!e.currentTarget.contains(e.relatedTarget as Node)) {
                                  setMatchProductoBusqueda(m => ({ ...m, [key]: '' }));
                                  setMatchProductoCategoria(m => ({ ...m, [key]: '' }));
                                }
                              }}
                            >
                              {/* FIX 24/9/2026: antes era un <select> con TODOS los productos activos (cientos),
                                  imposible de usar para buscar uno a la vez. Ahora es un filtro de categoría
                                  (veneno/foliar/etc, pedido explícito: "se podria filtrar por veneno, por
                                  foliar... eso ayuda a almacén a llenar la solicitud") + texto libre que
                                  filtra en vivo — el ID del producto elegido sigue guardándose en
                                  matchProductoSolicitud, igual que antes, para que el resto del flujo (botón
                                  Entregar, ModalMovAlmacen) no cambie. */}
                              {(() => {
                                const prodElegido = matchProductoSolicitud[key] ? productos.find(pr => pr.id === matchProductoSolicitud[key]) : null;
                                const texto = matchProductoBusqueda[key] ?? (prodElegido ? prodElegido.nombre : '');
                                const categoria = matchProductoCategoria[key] || '';
                                const mostrarLista = (!!matchProductoBusqueda[key] || !!categoria) && !matchProductoSolicitud[key];
                                const coincidencias = mostrarLista
                                  ? productos.filter(pr => pr.activo !== false
                                      && (!categoria || pr.categoria === categoria)
                                      && (!matchProductoBusqueda[key] || pr.nombre.toLowerCase().includes(matchProductoBusqueda[key].toLowerCase())))
                                      .sort((a, b) => a.nombre.localeCompare(b.nombre)).slice(0, 25)
                                  : [];
                                return (
                                  <>
                                    <select
                                      value={categoria}
                                      onChange={e => {
                                        setMatchProductoCategoria(m => ({ ...m, [key]: e.target.value }));
                                        if (matchProductoSolicitud[key]) setMatchProductoSolicitud(m => ({ ...m, [key]: '' }));
                                      }}
                                      className="input text-xs py-1 max-w-[90px]"
                                      title="Filtrar por categoría"
                                    >
                                      <option value="">Categoría</option>
                                      {CATEGORIAS_ALMACEN.map(c => <option key={c} value={c}>{c}</option>)}
                                    </select>
                                    <input
                                      type="text"
                                      value={texto}
                                      placeholder="Buscar producto..."
                                      onChange={e => {
                                        const v = e.target.value;
                                        setMatchProductoBusqueda(m => ({ ...m, [key]: v }));
                                        if (matchProductoSolicitud[key]) setMatchProductoSolicitud(m => ({ ...m, [key]: '' }));
                                      }}
                                      className="input text-xs py-1 max-w-[140px]"
                                    />
                                    {mostrarLista && (
                                      <div className="absolute z-20 top-full left-0 mt-0.5 bg-white border border-gray-200 rounded shadow-lg max-h-44 overflow-y-auto w-56">
                                        {coincidencias.length === 0 && <p className="px-2 py-1.5 text-xs text-gray-400">Sin resultados</p>}
                                        {coincidencias.map(pr => (
                                          <button key={pr.id} type="button"
                                            onClick={() => {
                                              setMatchProductoSolicitud(m => ({ ...m, [key]: pr.id }));
                                              setMatchProductoBusqueda(m => ({ ...m, [key]: '' }));
                                              setMatchProductoCategoria(m => ({ ...m, [key]: '' }));
                                            }}
                                            className="block w-full text-left px-2 py-1 text-xs hover:bg-sky-50 border-b border-gray-100 last:border-0">
                                            {pr.nombre} <span className="text-gray-400">({pr.stockActual.toFixed(1)} {pr.unidad})</span>
                                          </button>
                                        ))}
                                      </div>
                                    )}
                                  </>
                                );
                              })()}
                              <button
                                disabled={!matchProductoSolicitud[key]}
                                onClick={() => {
                                  const prodReal = productos.find(pr => pr.id === matchProductoSolicitud[key]);
                                  if (!prodReal) return;
                                  setModalMovContexto({ solicitudId: sol.id, idx });
                                  setModalMovimiento(prodReal);
                                }}
                                className="bg-sky-600 disabled:bg-gray-300 text-white text-xs px-2 py-1 rounded font-semibold whitespace-nowrap">
                                Entregar
                              </button>
                            </div>
                              );
                            })()}
                        </div>
                      );
                    })}
                  </div>
                  {/* AGREGADO 24/9/2026 (pedido explícito — "me preocupa q almacén va a tener q
                      tikear producto por producto y se va a molestar... esto lo estoy haciendo
                      para q funcione y sea fácil"): entrega TODO lo pendiente de la solicitud de
                      una sola vez — una fecha, un responsable, una confirmación — en vez de abrir
                      el modal de a un producto por vez. Se habilita solo cuando TODOS los
                      productos pendientes ya tienen un producto de catálogo emparejado (automático
                      por nombre exacto, o elegido a mano) — si falta alguno, hay que resolverlo
                      primero (mismo criterio de seguridad de siempre: nunca descontar del producto
                      equivocado). */}
                  {sol.estado === 'en_curso' && rol !== 'operador' && (() => {
                    const pendientes = sol.productos.map((p, i) => ({ p, i })).filter(x => !x.p.entregado);
                    if (pendientes.length === 0) return null;
                    const faltanEmparejar = pendientes.filter(({ p, i }) => !obtenerMatchId(sol.id, i, p.nombre)).length;
                    return (
                      <button
                        disabled={faltanEmparejar > 0}
                        onClick={() => setModalEntregaTotal(sol)}
                        title={faltanEmparejar > 0 ? `Faltan emparejar ${faltanEmparejar} producto${faltanEmparejar === 1 ? '' : 's'} con el catálogo` : 'Entregar todos los productos pendientes de una sola vez'}
                        className="mt-2 bg-emerald-600 hover:bg-emerald-700 disabled:bg-gray-300 text-white text-xs font-bold px-3 py-1.5 rounded"
                      >
                        🚀 Entregar todo ({pendientes.length})
                      </button>
                    );
                  })()}
                  {sol.estado === 'pendiente' && rol !== 'operador' && (
                    <button onClick={() => atenderSolicitud(sol)} className="mt-2 bg-amber-600 hover:bg-amber-700 text-white text-xs font-bold px-3 py-1.5 rounded">
                      📂 Atender esta solicitud (empezar a prepararla)
                    </button>
                  )}
                </div>
              );
            })}
          </div>
          );
        })()}

        {/* ===== HISTORIAL — planilla permanente, una fila por producto entregado, aparte del
            documento de trabajo de arriba (pedido explícito — "deben guardarse como una planilla
            de historial aparte del documento generado y cerrado") ===== */}
        {subtab === 'historial' && (() => {
          // REDISEÑO 24/9/2026 (pedido explícito — "el tema almacén de agrifumiga, se va llenar de
          // entrega de productos en el historial, en 3 entregas q aparecen ya tenemos como 20
          // líneas de producto, debemos de agrupar q sea plegable ahi para que se entren varios o
          // muchos"): antes era una fila por PRODUCTO entregado — una entrega de 6-7 productos ya
          // ocupaba 6-7 filas. Ahora se agrupa por ENTREGA (mismo solicitudId): una tarjeta
          // plegable por entrega, con el resumen arriba (fecha, N° orden, pivote/máquina, quién
          // entregó, comprobante) y el detalle de productos adentro, plegado por defecto — igual
          // de todo el historial queda, solo que no hay que scrollear entre filas sueltas para
          // verlo. `historialSolicitudes` ya viene ordenado por fecha de entrega (más reciente
          // primero) y todas las filas de una misma entrega comparten el mismo `entregadoEn`
          // (ver `registrarHistorialSolicitud`), así que agrupar preservando el orden de aparición
          // mantiene el orden cronológico entre entregas.
          const grupos: Record<string, FilaHistorialSolicitud[]> = {};
          const ordenGrupos: string[] = [];
          historialSolicitudes.forEach(f => {
            if (!grupos[f.solicitudId]) { grupos[f.solicitudId] = []; ordenGrupos.push(f.solicitudId); }
            grupos[f.solicitudId].push(f);
          });
          return (
          <div className="p-3 space-y-3">
            <div className="flex items-center justify-between flex-wrap gap-2">
              <p className="text-xs text-gray-500">{ordenGrupos.length} entrega(s) registrada(s) ({historialSolicitudes.length} línea{historialSolicitudes.length===1?'':'s'} de producto) — no se editan ni se borran.</p>
              <button
                onClick={() => exportarHistorialSolicitudesExcel(historialSolicitudes)}
                disabled={historialSolicitudes.length === 0}
                className="bg-emerald-600 hover:bg-emerald-700 disabled:bg-gray-300 text-white text-xs font-bold px-3 py-1.5 rounded flex items-center gap-1.5"
              >
                📥 Exportar Excel
              </button>
            </div>
            {ordenGrupos.length === 0 ? (
              <p className="text-center text-gray-400 text-sm py-8">Sin entregas registradas todavía.</p>
            ) : (
              <div className="space-y-1.5">
                {ordenGrupos.map(solicitudId => {
                  const filas = grupos[solicitudId];
                  const f0 = filas[0];
                  const solOriginal = solicitudesRiego.find(s => s.id === solicitudId);
                  return (
                    <details key={solicitudId} className="border border-gray-200 rounded-lg bg-white overflow-hidden">
                      <summary className="px-3 py-2 cursor-pointer list-none flex items-center justify-between flex-wrap gap-x-3 gap-y-1 text-xs hover:bg-gray-50">
                        <div className="flex items-center gap-x-3 gap-y-1 flex-wrap">
                          <span className="text-gray-400 whitespace-nowrap">{f0.entregadoEn ? new Date(f0.entregadoEn).toLocaleString('es-BO', { hour12: false }) : '—'}</span>
                          <span className="font-semibold whitespace-nowrap">{f0.origen === 'maquinaria' ? '🚜' : '💧'} {f0.pivoteOMaquina || '—'}</span>
                          <span className="text-gray-500 whitespace-nowrap">N° {f0.numeroOrden || '—'}</span>
                          <span className="text-gray-400 whitespace-nowrap">{filas.length} producto{filas.length===1?'':'s'}</span>
                        </div>
                        <div className="flex items-center gap-2">
                          <span className="text-gray-500 whitespace-nowrap">Entregó: <strong>{f0.entregadoPor || '—'}</strong></span>
                          {solOriginal ? (
                            <button type="button" onClick={(e) => { e.preventDefault(); setModalComprobante(solOriginal); }} title="Ver/compartir comprobante de entrega" className="bg-gray-100 hover:bg-gray-200 text-gray-700 font-semibold px-2 py-0.5 rounded whitespace-nowrap">🧾 Ver</button>
                          ) : (
                            <span className="text-gray-300 whitespace-nowrap" title="La solicitud original ya no está (se pudo haber borrado a mano)">— comprobante</span>
                          )}
                        </div>
                      </summary>
                      <table className="w-full text-xs border-t border-gray-100">
                        <thead className="bg-gray-50">
                          <tr>
                            <th className="px-2 py-1.5 text-left">Lote(s)</th>
                            <th className="px-2 py-1.5 text-left">Producto</th>
                            <th className="px-2 py-1.5 text-right">Cantidad</th>
                            <th className="px-2 py-1.5 text-left">Generó</th>
                          </tr>
                        </thead>
                        <tbody>
                          {filas.map(f => (
                            <tr key={f.id} className="border-t border-gray-100">
                              <td className="px-2 py-1.5">{(f.lotes || []).join(', ') || '—'}</td>
                              <td className="px-2 py-1.5">{f.producto}{!f.entregadoCompleto && <span className="text-amber-600"> (parcial/estimado)</span>}</td>
                              <td className="px-2 py-1.5 text-right">{f.cantidad.toFixed(2)} {f.unidad}</td>
                              <td className="px-2 py-1.5">{f.generadoPor || '—'}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </details>
                  );
                })}
              </div>
            )}
          </div>
          );
        })()}

      </div>

      {/* ===== MODAL MOVIMIENTO ===== */}
      {modalMovimiento && (() => {
        const solCtx = modalMovContexto ? solicitudesRiego.find(s => s.id === modalMovContexto.solicitudId) : null;
        const prodSol = solCtx && modalMovContexto ? solCtx.productos[modalMovContexto.idx] : null;
        const prefill = solCtx && prodSol ? {
          tipoApl: (solCtx.origen === 'maquinaria' ? 'maquinaria' : 'pivote') as TipoAplicacion,
          cantidad: String(prodSol.cantidadEstimada),
          otRiegoNum: solCtx.otRiegoNumero || '',
          otNumero: solCtx.otNumero || '',
          maquina: solCtx.maquina || '',
          pivot: solCtx.pivot || '',
          lotes: solCtx.lotes.join(', '),
        } : undefined;
        return (
          <ModalMovAlmacen
            producto={modalMovimiento}
            ots={ots}
            responsablesAlmacen={responsablesAlmacen}
            responsablesExtra={responsablesExtra}
            responsableActivo={responsableAlmacenActivo}
            onAgregarResponsable={agregarResponsableAlmacen}
            onEliminarResponsable={eliminarResponsableAlmacen}
            onUsarResponsable={usarResponsableAlmacen}
            prefill={prefill}
            onCerrar={() => { setModalMovimiento(null); setModalMovContexto(null); }}
            onGuardar={aplicarMovimiento}
          />
        );
      })()}

      {/* ===== MODAL ENTREGA TOTAL ===== */}
      {modalEntregaTotal && (
        <ModalEntregaTotal
          sol={modalEntregaTotal}
          productosCatalogo={productos}
          obtenerMatchId={obtenerMatchId}
          responsablesAlmacen={responsablesAlmacen}
          responsablesExtra={responsablesExtra}
          responsableActivo={responsableAlmacenActivo}
          onAgregarResponsable={agregarResponsableAlmacen}
          onEliminarResponsable={eliminarResponsableAlmacen}
          onCerrar={() => setModalEntregaTotal(null)}
          onConfirmar={entregarSolicitudCompleta}
        />
      )}

      {/* ===== MODAL ARQUEO ===== */}
      {modalArqueo && arqueoActivo && (
        <ModalArqueoAlmacen
          arqueo={arqueoActivo}
          responsables={responsablesAlmacen}
          responsablesExtra={responsablesExtra}
          onAgregarResponsable={agregarResponsableAlmacen}
          onEliminarResponsable={eliminarResponsableAlmacen}
          responsableActivo={responsableAlmacenActivo}
          onCerrar={() => { setModalArqueo(false); setArqueoActivo(null); }}
          onBorrador={async (a) => { const n = arqueos.filter(x => x.id !== a.id); await saveArqueos([...n, a]); setArqueoActivo(a); }}
          onCerrar2={async (a) => {
            const prodsAct = [...productos];
            const movNuevos: MovimientoAlmacen[] = [];
            for (const item of a.items) {
              if (Math.abs(item.diferencia) > 0.001) {
                const idx = prodsAct.findIndex(p => p.id === item.productoId);
                if (idx >= 0) {
                  prodsAct[idx] = { ...prodsAct[idx], stockActual: item.stockFisico, actualizadoEn: new Date().toISOString() };
                  movNuevos.push({
                    id: `mov_arq_${Date.now()}_${item.productoId}`,
                    productoId: item.productoId, productoNombre: item.productoNombre, unidad: item.unidad,
                    tipo: 'ajuste', tipoAplicacion: undefined,
                    cantidad: item.stockFisico, stockAntes: item.stockTeorico, stockDespues: item.stockFisico,
                    otNumero: '', lotes: [], campaña: campanaActiva,
                    responsable: a.responsable, observaciones: `Arqueo ${a.fecha}`,
                    fecha: a.fecha, creadoEn: new Date().toISOString(),
                  });
                }
              }
            }
            await saveProductos(prodsAct);
            if (movNuevos.length > 0) await saveMovimientos([...movNuevos, ...movimientos]);
            const cerrado: ArqueoAlmacen = { ...a, estado: 'cerrado', cerradoEn: new Date().toISOString() };
            await saveArqueos([...arqueos.filter(x => x.id !== a.id), cerrado]);
            usarResponsableAlmacen(a.responsable); // AGREGADO 24/9/2026: recordarlo para la próxima vez en este dispositivo
            setModalArqueo(false); setArqueoActivo(null);
            alert(`✅ Arqueo cerrado. ${movNuevos.length} ajuste${movNuevos.length!==1?'s':''} aplicado${movNuevos.length!==1?'s':''}.`);
          }}
        />
      )}

      {/* ===== MODAL NUEVO PRODUCTO ===== */}
      {modalNuevo && (
        <ModalNuevoProdAlmacen
          onCerrar={() => setModalNuevo(false)}
          onGuardar={async (prod) => {
            const nuevo: ProductoAlmacen = { ...prod, id: `prod_${Date.now()}`, activo: true, actualizadoEn: new Date().toISOString() };
            await saveProductos([...productos, nuevo].sort((a,b) => a.nombre.localeCompare(b.nombre)));
            setModalNuevo(false);
          }}
        />
      )}

      {/* ===== MODAL COMPROBANTE DE ENTREGA (solicitud ya cerrada) ===== */}
      {modalComprobante && (
        <ModalCompartirWhatsApp
          contenido={<TarjetaComprobanteEntrega sol={modalComprobante} />}
          id="comprobante-entrega-card"
          titulo={`Comprobante_${modalComprobante.origen === 'maquinaria' ? modalComprobante.maquina : modalComprobante.pivot}_${modalComprobante.fecha}`}
          onCerrar={() => setModalComprobante(null)}
        />
      )}
    </div>
  );
}

// ===== MODAL MOVIMIENTO CON TIPO APLICACIÓN =====
// ===== GRUPO DE MOVIMIENTOS POR MÁQUINA =====
function GrupoMovimientosAlmacen({ titulo, movimientos }: { titulo: string; movimientos: MovimientoAlmacen[] }) {
  const [abierto, setAbierto] = useState(false);
  const totalEgreso = movimientos.filter(m => m.tipo === 'egreso').reduce((s, m) => s + (m.cantidad || 0), 0);
  const totalIngreso = movimientos.filter(m => m.tipo === 'ingreso').reduce((s, m) => s + (m.cantidad || 0), 0);

  return (
    <div className="bg-white rounded-lg border overflow-hidden">
      <button
        onClick={() => setAbierto(!abierto)}
        className="w-full flex items-center justify-between px-3 py-2 bg-slate-800 text-white hover:bg-slate-700 transition-colors"
      >
        <span className="font-semibold text-sm">
          {titulo.startsWith('💧') || titulo.startsWith('📦') || titulo.startsWith('⇔') ? titulo : `🚜 ${titulo}`}
        </span>
        <div className="flex items-center gap-2 text-xs">
          {totalEgreso > 0 && <span className="text-red-300">↓{movimientos.filter(m=>m.tipo==='egreso').length} mov</span>}
          {totalIngreso > 0 && <span className="text-green-300">↑{movimientos.filter(m=>m.tipo==='ingreso').length} mov</span>}
          <span className="text-slate-400">{abierto ? '▲' : '▼'}</span>
        </div>
      </button>
      {abierto && (
        <div className="divide-y divide-gray-50">
          {movimientos.slice(0, 100).map(m => {
            const esEgreso = m.tipo === 'egreso';
            const esIngreso = m.tipo === 'ingreso';
            return (
              <div key={m.id} className="px-3 py-2 flex items-center gap-2 text-xs hover:bg-gray-50">
                {/* Tipo badge */}
                <span className={`px-1.5 py-0.5 rounded font-bold text-white flex-shrink-0 ${esEgreso ? 'bg-red-500' : esIngreso ? 'bg-green-600' : 'bg-blue-600'}`}>
                  {esEgreso ? '↓' : esIngreso ? '↑' : '⇔'}
                </span>
                {/* Producto */}
                <span className="font-medium text-gray-800 flex-1 truncate">{m.productoNombre}</span>
                {/* Lotes */}
                {m.lotes?.length > 0 && (
                  <span className="text-gray-400 truncate max-w-[80px]">📍{m.lotes.slice(0,2).join(',')}{m.lotes.length>2?'…':''}</span>
                )}
                {/* Fecha */}
                <span className="text-gray-400 flex-shrink-0">{m.fecha?.slice(8)}/{m.fecha?.slice(5,7)}</span>
                {/* Cantidad + saldo */}
                <div className="text-right flex-shrink-0">
                  <span className={`font-bold ${esEgreso ? 'text-red-600' : esIngreso ? 'text-green-700' : 'text-blue-600'}`}>
                    {esEgreso ? '-' : esIngreso ? '+' : '='}{m.cantidad} {m.unidad}
                  </span>
                  <div className="text-[10px] text-gray-400">{m.stockAntes}→{m.stockDespues}</div>
                </div>
              </div>
            );
          })}
          {movimientos.length > 100 && (
            <p className="text-center text-xs text-gray-400 py-2">... {movimientos.length - 100} más</p>
          )}
        </div>
      )}
    </div>
  );
}

// ===== GRUPO POR PIVOT =====
function GrupoPivotAlmacen({
  pivot, lotes, movimientos, totalProductos,
}: {
  pivot: string;
  lotes: string[];
  movimientos: MovimientoAlmacen[];
  totalProductos: number;
}) {
  const [abierto, setAbierto] = useState(false);

  return (
    <div className="bg-white rounded-lg border overflow-hidden">
      {/* Cabecera pivot */}
      <button
        onClick={() => setAbierto(!abierto)}
        className="w-full flex items-center justify-between px-3 py-2 bg-green-800 text-white hover:bg-green-700"
      >
        <span className="font-bold text-sm">🌾 Pivot {pivot}</span>
        <div className="flex items-center gap-2 text-xs">
          <span className="bg-green-700 px-2 py-0.5 rounded">{lotes.length} lote{lotes.length!==1?'s':''}</span>
          <span className="bg-green-700 px-2 py-0.5 rounded">{movimientos.length} aplic.</span>
          <span className="text-green-300">{abierto ? '▲' : '▼'}</span>
        </div>
      </button>
      {abierto && (
        <div className="divide-y divide-gray-100">
          {lotes.map(lote => {
            const movLote = movimientos.filter(m => m.lotes?.includes(lote));
            // Agrupar productos por nombre y sumar cantidades
            const resumen: Record<string, {cantidad: number; unidad: string; maquina: string; fecha: string}> = {};
            movLote.forEach(m => {
              if (!resumen[m.productoNombre]) {
                resumen[m.productoNombre] = { cantidad: 0, unidad: m.unidad, maquina: m.maquina || m.pivot || '', fecha: m.fecha };
              }
              resumen[m.productoNombre].cantidad += m.cantidad || 0;
            });
            const productosResumen = Object.entries(resumen);

            return (
              <div key={lote} className="px-3 py-2">
                {/* Lote header */}
                <div className="flex items-center gap-2 mb-1.5">
                  <span className="font-semibold text-gray-700 text-xs">📍 {lote}</span>
                  <span className="text-[10px] text-gray-400">
                    {[...new Set(movLote.map(m => m.maquina || m.pivot).filter(Boolean))].map(maq => `🚜${maq}`).join(' ')}
                  </span>
                  <span className="text-[10px] text-gray-400 ml-auto">
                    {[...new Set(movLote.map(m => m.fecha))].slice(0,2).join(', ')}
                  </span>
                </div>
                {/* Productos aplicados en ese lote — una línea por producto */}
                <div className="flex flex-wrap gap-1.5">
                  {productosResumen.map(([nombre, datos]) => (
                    <span key={nombre} className="text-[11px] bg-gray-100 text-gray-700 px-2 py-0.5 rounded">
                      {nombre}: <strong className="text-red-600">{datos.cantidad % 1 === 0 ? datos.cantidad : datos.cantidad.toFixed(2)} {datos.unidad}</strong>
                    </span>
                  ))}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

function ModalMovAlmacen({
  producto, ots, responsablesAlmacen, responsablesExtra, responsableActivo, onAgregarResponsable, onEliminarResponsable, onUsarResponsable, onCerrar, onGuardar, prefill,
}: {
  producto: ProductoAlmacen;
  ots: OT[];
  // FIX 24/9/2026: antes este campo usaba OPERADORES (los operadores de máquina fumigadora/pivote)
  // — pedido explícito: "una vez seleccionado el producto almacén tikea responsable y ahí salen
  // lista desplegable de los operadores y eso está mal, otros son los personales de almacén". Ahora
  // recibe la misma lista de personal de almacén que ya usa el Arqueo (base + agregados a mano).
  responsablesAlmacen: string[];
  // AGREGADO 24/9/2026: solo los agregados a mano (subconjunto de responsablesAlmacen) — para
  // poder ofrecer "quitar" únicamente sobre estos, nunca sobre los 3 nombres base.
  responsablesExtra: string[];
  // FIX 24/9/2026 (2) (pedido explícito — "que pongan su nombre y q quede logueado... pero ya saca
  // el desplegable por defecto q tomaba a los operadores"): antes el default salía de
  // `usuarioActivo` (la sesión general de la app — podía ser cualquiera, incluso un operador).
  // Ahora sale de acá: el último responsable DE ALMACÉN usado en ESTE dispositivo, nunca de la
  // sesión general. Sigue siendo 100% visible/cambiable en el propio selector.
  responsableActivo: string;
  onAgregarResponsable: (nombre: string) => Promise<void>;
  onEliminarResponsable: (nombre: string) => Promise<void>;
  onUsarResponsable: (nombre: string) => void;
  onCerrar: () => void;
  onGuardar: (prod: ProductoAlmacen, tipo: 'ingreso'|'egreso'|'ajuste', cantidad: number, tipoAplicacion: TipoAplicacion, otNumero: string, otRiegoNumero: string, maquina: string, pivot: string, lotes: string[], responsable: string, obs: string, fecha: string) => void;
  // AGREGADO 23/9/2026: valores iniciales cuando el modal se abre desde una solicitud de riego
  // (ver "Registrar entrega" en la sub-pestaña Solicitudes) — deja todo precargado, el egreso
  // real se sigue confirmando a mano igual que cualquier otro movimiento (nada se auto-guarda).
  prefill?: { tipoApl: TipoAplicacion; cantidad: string; otRiegoNum: string; otNumero?: string; maquina?: string; pivot: string; lotes: string };
}) {
  const [tipo, setTipo] = useState<'ingreso'|'egreso'|'ajuste'>(prefill ? 'egreso' : 'ingreso');
  const [tipoApl, setTipoApl] = useState<TipoAplicacion>(prefill?.tipoApl || 'manual');
  const [cantidad, setCantidad] = useState(prefill?.cantidad || '');
  const [responsable, setResponsable] = useState(responsablesAlmacen.includes(responsableActivo) ? responsableActivo : '');
  const [agregandoResp, setAgregandoResp] = useState(false);
  const [nombreNuevoResp, setNombreNuevoResp] = useState('');
  const [otNumero, setOtNumero] = useState(prefill?.otNumero || '');
  const [otRiegoNum, setOtRiegoNum] = useState(prefill?.otRiegoNum || '');
  const [maquina, setMaquina] = useState(prefill?.maquina || '');
  const [pivot, setPivot] = useState(prefill?.pivot || '');
  const [lotes, setLotes] = useState(prefill?.lotes || '');
  const [obs, setObs] = useState('');
  const [fecha, setFecha] = useState(fechaLocalISO());
  // FIX 24/9/2026: sin esto, el botón "Guardar movimiento" no mostraba ningún cambio mientras la
  // escritura a Firestore estaba en curso — pedido explícito: "escogí un nombre para ver el flujo y
  // le di guardar, ese botón no guardar no hace nada". En realidad SÍ guardaba, pero como no había
  // ninguna señal visual el usuario volvía a apretar "Guardar" varias veces, y cada click disparaba
  // otro movimiento duplicado (mismo producto, misma cantidad, mismo stock antes/después) porque el
  // modal seguía abierto con los mismos datos. Ahora el botón se deshabilita y cambia de texto en el
  // primer click, así que un doble click ya no puede duplicar el movimiento.
  const [guardando, setGuardando] = useState(false);

  const cant = parseFloat(cantidad)||0;
  const stockRes = tipo==='ingreso'?producto.stockActual+cant:tipo==='egreso'?producto.stockActual-cant:cant;

  function confirmar() {
    if (guardando) return;
    if (!cant || cant <= 0) { alert('Ingrese una cantidad válida.'); return; }
    if (!responsable.trim()) { alert('Ingrese el responsable.'); return; }
    if (tipo === 'egreso' && tipoApl === 'pivote' && !pivot) { alert('Seleccione el pivot.'); return; }
    setGuardando(true);
    // AGREGADO 24/9/2026: recuerda quién fue en ESTE dispositivo, para sugerirlo la próxima vez
    // (nunca automático la primera vez — recién queda guardado después de confirmar acá).
    onUsarResponsable(responsable.trim());
    onGuardar(producto, tipo, cant, tipoApl, otNumero, otRiegoNum, maquina, pivot, lotes.split(',').map(l=>l.trim()).filter(Boolean), responsable.trim(), obs.trim(), fecha);
  }

  return (
    <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-3">
      <div className="bg-white rounded-xl w-full max-w-md shadow-2xl overflow-y-auto max-h-[90vh]">
        <div className="p-4 border-b">
          <h3 className="font-bold text-gray-800">± Registrar movimiento</h3>
          <p className="text-sm text-blue-700 font-semibold">{producto.nombre}</p>
          <p className="text-xs text-gray-500">Stock actual: {producto.stockActual.toFixed(2)} {producto.unidad}</p>
        </div>
        <div className="p-4 space-y-3">
          {/* Tipo movimiento */}
          <div className="grid grid-cols-3 gap-1">
            {(['ingreso','egreso','ajuste'] as const).map(t => (
              <button key={t} onClick={() => { setTipo(t); if(t!=='egreso') setTipoApl('manual'); }}
                className={`py-2 rounded text-xs font-bold border-2 ${tipo===t?(t==='ingreso'?'bg-green-600 text-white border-green-600':t==='egreso'?'bg-red-600 text-white border-red-600':'bg-blue-600 text-white border-blue-600'):'border-gray-200 text-gray-600'}`}>
                {t==='ingreso'?'↑ Ingreso':t==='egreso'?'↓ Egreso':'⇔ Ajuste'}
              </button>
            ))}
          </div>

          {/* Tipo de aplicación (solo para EGRESO) */}
          {tipo === 'egreso' && (
            <div>
              <label className="text-xs text-gray-600 font-medium">Tipo de aplicación</label>
              <div className="grid grid-cols-3 gap-1 mt-1">
                {[
                  {id:'maquinaria',label:'🚜 Maquinaria'},
                  {id:'pivote',label:'💧 Pivote'},
                  {id:'manual',label:'📝 Manual'},
                ].map(t => (
                  <button key={t.id} onClick={() => setTipoApl(t.id as TipoAplicacion)}
                    className={`py-1.5 rounded text-xs font-semibold border ${tipoApl===t.id?'bg-gray-800 text-white border-gray-800':'border-gray-200 text-gray-600'}`}>
                    {t.label}
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* Campos según tipo de aplicación */}
          {tipo === 'egreso' && tipoApl === 'maquinaria' && (
            <div className="grid grid-cols-2 gap-2">
              <div>
                <label className="text-xs text-gray-600">Máquina</label>
                <select value={maquina} onChange={e => setMaquina(e.target.value)} className="input w-full mt-1 text-sm">
                  <option value="">— Seleccionar —</option>
                  {MAQUINAS.map(m => <option key={m}>{m}</option>)}
                </select>
              </div>
              <div>
                <label className="text-xs text-gray-600">N° OT Fumigación</label>
                <select value={otNumero} onChange={e => setOtNumero(e.target.value)} className="input w-full mt-1 text-sm">
                  <option value="">— Seleccionar —</option>
                  {ots.filter(o=>o.estado!=='completada'||true).map(o => <option key={o.id} value={o.numeroOT||o.id.slice(-6)}>{o.numeroOT||o.id.slice(-6)} · {o.maquina}</option>)}
                </select>
              </div>
            </div>
          )}

          {tipo === 'egreso' && tipoApl === 'pivote' && (
            <div className="space-y-2">
              <div className="grid grid-cols-2 gap-2">
                <div>
                  <label className="text-xs text-gray-600">Pivot</label>
                  <select value={pivot} onChange={e => setPivot(e.target.value)} className="input w-full mt-1 text-sm">
                    <option value="">— Seleccionar —</option>
                    {PIVOTES_LISTA.map(p => <option key={p}>{p}</option>)}
                  </select>
                </div>
                <div>
                  <label className="text-xs text-gray-600">N° OT Riego (AgriRiego)</label>
                  <input type="text" value={otRiegoNum} onChange={e => setOtRiegoNum(e.target.value)} className="input w-full mt-1 text-sm" placeholder="Ej: OT-2026-047" />
                </div>
              </div>
            </div>
          )}

          {/* Lotes */}
          {tipo === 'egreso' && (
            <div>
              <label className="text-xs text-gray-600">Lotes aplicados (separados por coma)</label>
              <input type="text" value={lotes} onChange={e => setLotes(e.target.value)} className="input w-full mt-1 text-sm" placeholder="Ej: P7-L1, P7-L2" />
            </div>
          )}

          {/* Cantidad + fecha */}
          <div className="grid grid-cols-2 gap-2">
            <div>
              <label className="text-xs text-gray-600">{tipo==='ajuste'?'Stock físico real':tipo==='ingreso'?'Cantidad ingresada':'Cantidad egresada'} ({producto.unidad})</label>
              <input type="number" step="0.01" min="0" value={cantidad} onChange={e => setCantidad(e.target.value)} className="input w-full mt-1" autoFocus />
            </div>
            <div>
              <label className="text-xs text-gray-600">Fecha</label>
              <input type="date" value={fecha} onChange={e => setFecha(e.target.value)} className="input w-full mt-1" />
            </div>
          </div>

          {/* Responsable — FIX 24/9/2026: personal de almacén (responsablesAlmacen), no OPERADORES */}
          <div>
            <label className="text-xs text-gray-600">Responsable</label>
            {!agregandoResp ? (
              <>
                <select
                  value={responsable}
                  onChange={e => {
                    if (e.target.value === '__otro__') { setAgregandoResp(true); return; }
                    setResponsable(e.target.value);
                  }}
                  className="input w-full mt-1"
                >
                  <option value="">— Seleccionar —</option>
                  {responsablesAlmacen.map(r => <option key={r}>{r}</option>)}
                  <option value="__otro__">+ Agregar otro…</option>
                </select>
                {/* AGREGADO 24/9/2026: siempre a la vista quién quedó precargado y de dónde sale
                    (el último usado en este dispositivo) — con un clic para sacarlo, nunca oculto. */}
                {responsable && responsable === responsableActivo && (
                  <p className="text-[11px] text-gray-400 mt-0.5">
                    Precargado: el último usado en este dispositivo. ¿No sos vos? <button type="button" onClick={() => setResponsable('')} className="text-sky-600 underline">cambiar</button>
                  </p>
                )}
              </>
            ) : (
              <div className="flex gap-1 mt-1">
                <input
                  type="text" autoFocus placeholder="Nombre completo"
                  value={nombreNuevoResp} onChange={e => setNombreNuevoResp(e.target.value)}
                  className="input flex-1 text-sm"
                />
                <button
                  type="button"
                  onClick={async () => {
                    if (!nombreNuevoResp.trim()) return;
                    await onAgregarResponsable(nombreNuevoResp);
                    setResponsable(nombreNuevoResp.trim());
                    setNombreNuevoResp(''); setAgregandoResp(false);
                  }}
                  className="px-2 rounded bg-purple-600 text-white text-xs font-semibold"
                >✓</button>
                <button type="button" onClick={() => { setAgregandoResp(false); setNombreNuevoResp(''); }}
                  className="px-2 rounded bg-gray-100 text-xs">✕</button>
              </div>
            )}
            {/* AGREGADO 24/9/2026 (pedido explícito — "entregada por Pablo vilca y ese es un
                operador de maquinaria no un encargado o recepcionista de almacén eso no me
                cuadra"): "+ Agregar otro…" es texto libre, sin validar que sea realmente personal
                de almacén — esto deja sacar un nombre agregado por error. Solo aplica a los
                agregados a mano (nunca a los 3 nombres base). No borra entregas ya registradas
                con ese nombre, solo evita que se lo vuelva a elegir de acá en adelante. */}
            {!agregandoResp && responsablesExtra.length > 0 && (
              <details className="mt-1">
                <summary className="text-[11px] text-gray-400 cursor-pointer">gestionar nombres agregados</summary>
                <div className="flex flex-wrap gap-1 mt-1">
                  {responsablesExtra.map(r => (
                    <span key={r} className="inline-flex items-center gap-1 bg-gray-100 text-gray-600 text-[11px] px-1.5 py-0.5 rounded">
                      {r}
                      <button type="button" onClick={() => onEliminarResponsable(r)} title={`Quitar "${r}" de la lista`} className="text-red-500 hover:text-red-700 font-bold">✕</button>
                    </span>
                  ))}
                </div>
              </details>
            )}
          </div>

          {/* Observaciones */}
          <div>
            <label className="text-xs text-gray-600">Observaciones</label>
            <input type="text" value={obs} onChange={e => setObs(e.target.value)} className="input w-full mt-1" placeholder="Proveedor, motivo, etc." />
          </div>

          {/* Preview stock */}
          {cantidad && (
            <div className={`rounded p-2 text-sm text-center font-semibold ${stockRes<0?'bg-red-100 text-red-800':'bg-green-100 text-green-800'}`}>
              Stock resultante: {stockRes.toFixed(2)} {producto.unidad}{stockRes<0?' ⚠️ NEGATIVO':''}
            </div>
          )}
        </div>
        <div className="p-4 border-t flex gap-2 justify-end">
          <button onClick={onCerrar} disabled={guardando} className="px-4 py-2 rounded text-sm bg-gray-100 hover:bg-gray-200 disabled:opacity-50">Cancelar</button>
          <button onClick={confirmar} disabled={guardando} className={`px-4 py-2 rounded text-sm text-white font-semibold disabled:opacity-60 ${tipo==='ingreso'?'bg-green-600 hover:bg-green-700':tipo==='egreso'?'bg-red-600 hover:bg-red-700':'bg-blue-600 hover:bg-blue-700'}`}>
            {guardando ? 'Guardando…' : 'Guardar movimiento'}
          </button>
        </div>
      </div>
    </div>
  );
}

// ===== MODAL ENTREGA TOTAL (una solicitud, todos sus productos pendientes de una vez) =====
// AGREGADO 24/9/2026 (pedido explícito — "me preocupa que almacén va a tener que tikear producto
// por producto y se va a molestar... esto lo estoy haciendo para que funcione y sea fácil, q me
// propones"): confirma en un solo paso la entrega de TODOS los productos pendientes de una
// solicitud — una fecha, un responsable (mismo patrón "recordado en este dispositivo" que
// ModalMovAlmacen/ModalArqueoAlmacen), una cantidad editable por producto (precargada con lo
// pedido) — y dispara `entregarSolicitudCompleta` una sola vez. Solo se abre cuando el botón que
// lo dispara ya validó que todos los pendientes tienen un producto de catálogo emparejado (nunca
// por nombre parecido, ver `obtenerMatchId`), así que acá no hace falta resolver eso de nuevo.
function ModalEntregaTotal({
  sol, productosCatalogo, obtenerMatchId, responsablesAlmacen, responsablesExtra, responsableActivo,
  onAgregarResponsable, onEliminarResponsable, onCerrar, onConfirmar,
}: {
  sol: SolicitudRiego;
  productosCatalogo: ProductoAlmacen[];
  obtenerMatchId: (solId: string, idx: number, nombre: string) => string | null;
  responsablesAlmacen: string[];
  responsablesExtra: string[];
  responsableActivo: string;
  onAgregarResponsable: (nombre: string) => Promise<void>;
  onEliminarResponsable: (nombre: string) => Promise<void>;
  onCerrar: () => void;
  onConfirmar: (sol: SolicitudRiego, cantidades: Record<number, number>, responsable: string, fecha: string) => Promise<void>;
}) {
  const pendientes = sol.productos.map((p, i) => ({ p, i })).filter(x => !x.p.entregado);
  const [cantidades, setCantidades] = useState<Record<number, string>>(() => {
    const init: Record<number, string> = {};
    pendientes.forEach(({ p, i }) => { init[i] = String(p.cantidadEstimada); });
    return init;
  });
  const [responsable, setResponsable] = useState(responsablesAlmacen.includes(responsableActivo) ? responsableActivo : '');
  const [agregandoResp, setAgregandoResp] = useState(false);
  const [nombreNuevoResp, setNombreNuevoResp] = useState('');
  const [fecha, setFecha] = useState(fechaLocalISO());
  const [guardando, setGuardando] = useState(false);

  async function confirmar() {
    if (guardando) return;
    if (!responsable.trim()) { alert('Ingrese el responsable.'); return; }
    const cantidadesNum: Record<number, number> = {};
    for (const { i } of pendientes) {
      const n = parseFloat(cantidades[i]);
      if (!n || n <= 0) { alert('Revise las cantidades — todas deben ser mayores a 0.'); return; }
      cantidadesNum[i] = n;
    }
    setGuardando(true);
    await onConfirmar(sol, cantidadesNum, responsable.trim(), fecha);
  }

  return (
    <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-3">
      <div className="bg-white rounded-xl w-full max-w-md shadow-2xl overflow-y-auto max-h-[90vh]">
        <div className="p-4 border-b">
          <h3 className="font-bold text-gray-800">🚀 Entregar todo</h3>
          <p className="text-sm text-emerald-700 font-semibold">
            {sol.origen === 'riego' ? `💧 ${sol.pivot || ''}` : `🚜 ${sol.maquina || ''}`}
            {sol.lotes?.length ? ` · ${sol.lotes.join(', ')}` : ''}
          </p>
          <p className="text-xs text-gray-500">{pendientes.length} producto{pendientes.length===1?'':'s'} pendiente{pendientes.length===1?'':'s'} de entregar</p>
        </div>
        <div className="p-4 space-y-3">
          {/* Fecha + responsable, una sola vez para toda la entrega */}
          <div className="grid grid-cols-2 gap-2">
            <div>
              <label className="text-xs text-gray-600">Fecha</label>
              <input type="date" value={fecha} onChange={e => setFecha(e.target.value)} className="input w-full mt-1" />
            </div>
            <div>
              <label className="text-xs text-gray-600">Responsable</label>
              {!agregandoResp ? (
                <select
                  value={responsable}
                  onChange={e => {
                    if (e.target.value === '__otro__') { setAgregandoResp(true); return; }
                    setResponsable(e.target.value);
                  }}
                  className="input w-full mt-1"
                >
                  <option value="">— Seleccionar —</option>
                  {responsablesAlmacen.map(r => <option key={r}>{r}</option>)}
                  <option value="__otro__">+ Agregar otro…</option>
                </select>
              ) : (
                <div className="flex gap-1 mt-1">
                  <input
                    type="text" autoFocus placeholder="Nombre completo"
                    value={nombreNuevoResp} onChange={e => setNombreNuevoResp(e.target.value)}
                    className="input flex-1 text-sm"
                  />
                  <button
                    type="button"
                    onClick={async () => {
                      if (!nombreNuevoResp.trim()) return;
                      await onAgregarResponsable(nombreNuevoResp);
                      setResponsable(nombreNuevoResp.trim());
                      setNombreNuevoResp(''); setAgregandoResp(false);
                    }}
                    className="px-2 rounded bg-purple-600 text-white text-xs font-semibold"
                  >✓</button>
                  <button type="button" onClick={() => { setAgregandoResp(false); setNombreNuevoResp(''); }}
                    className="px-2 rounded bg-gray-100 text-xs">✕</button>
                </div>
              )}
            </div>
          </div>
          {responsable && responsable === responsableActivo && !agregandoResp && (
            <p className="text-[11px] text-gray-400 -mt-2">
              Precargado: el último usado en este dispositivo. ¿No sos vos? <button type="button" onClick={() => setResponsable('')} className="text-sky-600 underline">cambiar</button>
            </p>
          )}
          {!agregandoResp && responsablesExtra.length > 0 && (
            <details className="-mt-1">
              <summary className="text-[11px] text-gray-400 cursor-pointer">gestionar nombres agregados</summary>
              <div className="flex flex-wrap gap-1 mt-1">
                {responsablesExtra.map(r => (
                  <span key={r} className="inline-flex items-center gap-1 bg-gray-100 text-gray-600 text-[11px] px-1.5 py-0.5 rounded">
                    {r}
                    <button type="button" onClick={() => onEliminarResponsable(r)} title={`Quitar "${r}" de la lista`} className="text-red-500 hover:text-red-700 font-bold">✕</button>
                  </span>
                ))}
              </div>
            </details>
          )}

          {/* Cantidad por producto — precargada con lo pedido, editable */}
          <div className="border-t pt-3 space-y-2">
            {pendientes.map(({ p, i }) => {
              const matchId = obtenerMatchId(sol.id, i, p.nombre);
              const prod = matchId ? productosCatalogo.find(pr => pr.id === matchId) : null;
              const cant = parseFloat(cantidades[i]) || 0;
              const stockInsuficiente = !!prod && cant > prod.stockActual;
              return (
                <div key={i} className="flex items-center gap-2">
                  <div className="flex-1 min-w-0">
                    <p className="text-xs font-medium text-gray-700 truncate">{p.nombre}</p>
                    <p className="text-[10px] text-gray-400">
                      Stock: {prod ? `${prod.stockActual.toFixed(1)} ${prod.unidad}` : '—'}
                      {stockInsuficiente && <span className="text-red-600 font-semibold"> · ⚠️ no alcanza</span>}
                    </p>
                  </div>
                  <input
                    type="number" step="0.01" min="0"
                    value={cantidades[i] ?? ''}
                    onChange={e => setCantidades(c => ({ ...c, [i]: e.target.value }))}
                    className="input w-24 text-sm text-right"
                  />
                  <span className="text-xs text-gray-400 w-10">{p.unidad}</span>
                </div>
              );
            })}
          </div>
        </div>
        <div className="p-4 border-t flex gap-2 justify-end">
          <button onClick={onCerrar} disabled={guardando} className="px-4 py-2 rounded text-sm bg-gray-100 hover:bg-gray-200 disabled:opacity-50">Cancelar</button>
          <button onClick={confirmar} disabled={guardando} className="px-4 py-2 rounded text-sm text-white font-semibold bg-emerald-600 hover:bg-emerald-700 disabled:opacity-60">
            {guardando ? 'Entregando…' : `Confirmar entrega (${pendientes.length})`}
          </button>
        </div>
      </div>
    </div>
  );
}

// ===== MODAL ARQUEO =====
function ModalArqueoAlmacen({
  arqueo: init, responsables, responsablesExtra, responsableActivo, onAgregarResponsable, onEliminarResponsable, onCerrar, onBorrador, onCerrar2,
}: {
  arqueo: ArqueoAlmacen;
  responsables: string[];
  responsablesExtra: string[];
  responsableActivo: string;
  onAgregarResponsable: (nombre: string) => Promise<void>;
  onEliminarResponsable: (nombre: string) => Promise<void>;
  onCerrar: () => void;
  onBorrador: (a: ArqueoAlmacen) => Promise<void>;
  onCerrar2: (a: ArqueoAlmacen) => Promise<void>;
}) {
  const [arq, setArq] = useState<ArqueoAlmacen>(init);
  const [busq, setBusq] = useState('');
  const [soloDif, setSoloDif] = useState(false);
  const [agregandoResp, setAgregandoResp] = useState(false);
  const [nombreNuevoResp, setNombreNuevoResp] = useState('');

  function setFisico(id: string, v: number) {
    setArq(prev => ({ ...prev, items: prev.items.map(it => it.productoId===id?{...it,stockFisico:v,diferencia:v-it.stockTeorico}:it) }));
  }

  const items = arq.items
    .filter(it => !busq || it.productoNombre.toLowerCase().includes(busq.toLowerCase()))
    .filter(it => !soloDif || Math.abs(it.diferencia) > 0.001);

  const totalDif = arq.items.filter(i => Math.abs(i.diferencia) > 0.001).length;

  return (
    <div className="fixed inset-0 bg-black/60 z-50 flex items-end md:items-center justify-center">
      <div className="bg-white rounded-t-2xl md:rounded-xl w-full md:max-w-2xl max-h-[92vh] flex flex-col shadow-2xl">
        <div className="p-4 border-b flex-shrink-0">
          <div className="flex items-center justify-between mb-2">
            <h3 className="font-bold">🔍 Arqueo de Inventario</h3>
            <button onClick={onCerrar} className="text-gray-400 hover:text-gray-600">✕</button>
          </div>
          {/* AGREGADO 24/9/2026 (pedido explícito — "ponelo más sencillo y fácil eso de arqueo no
              entiendo q es ni para que sirve"): una línea corta explicando qué es esto, para quien
              lo ve por primera vez. */}
          <p className="text-xs text-gray-500 mb-2">
            Contar físicamente el stock de cada producto y compararlo con lo que el sistema dice
            que debería haber (Teórico). Si hay diferencia, al cerrar el arqueo el sistema se
            AJUSTA al conteo físico real.
          </p>
          <div className="grid grid-cols-2 gap-2 mb-2">
            <div>
              <label className="text-xs text-gray-600">Fecha</label>
              <input type="date" value={arq.fecha} onChange={e => setArq(p => ({...p,fecha:e.target.value}))} className="input w-full mt-0.5" />
            </div>
            <div>
              <label className="text-xs text-gray-600">Responsable</label>
              {!agregandoResp ? (
                <>
                  <select
                    value={arq.responsable}
                    onChange={e => {
                      if (e.target.value === '__otro__') { setAgregandoResp(true); return; }
                      setArq(p => ({...p, responsable: e.target.value}));
                    }}
                    className="input w-full mt-0.5"
                  >
                    <option value="">— Seleccionar —</option>
                    {responsables.map(r => <option key={r}>{r}</option>)}
                    <option value="__otro__">+ Agregar otro…</option>
                  </select>
                  {/* AGREGADO 24/9/2026: mismo criterio que en "Registrar movimiento" — el default
                      sale del último responsable de almacén usado en este dispositivo, nunca de la
                      sesión general de la app, y siempre a la vista/cambiable con un clic. */}
                  {arq.responsable && arq.responsable === responsableActivo && (
                    <p className="text-[11px] text-gray-400 mt-0.5">
                      Precargado: el último usado en este dispositivo. ¿No sos vos? <button type="button" onClick={() => setArq(p => ({...p, responsable: ''}))} className="text-sky-600 underline">cambiar</button>
                    </p>
                  )}
                </>
              ) : (
                <div className="flex gap-1 mt-0.5">
                  <input
                    type="text" autoFocus placeholder="Nombre completo"
                    value={nombreNuevoResp} onChange={e => setNombreNuevoResp(e.target.value)}
                    className="input flex-1 text-sm"
                  />
                  <button
                    onClick={async () => {
                      if (!nombreNuevoResp.trim()) return;
                      await onAgregarResponsable(nombreNuevoResp);
                      setArq(p => ({...p, responsable: nombreNuevoResp.trim()}));
                      setNombreNuevoResp(''); setAgregandoResp(false);
                    }}
                    className="px-2 rounded bg-purple-600 text-white text-xs font-semibold"
                  >✓</button>
                  <button onClick={() => { setAgregandoResp(false); setNombreNuevoResp(''); }}
                    className="px-2 rounded bg-gray-100 text-xs">✕</button>
                </div>
              )}
              {!agregandoResp && responsablesExtra.length > 0 && (
                <details className="mt-1">
                  <summary className="text-[11px] text-gray-400 cursor-pointer">gestionar nombres agregados</summary>
                  <div className="flex flex-wrap gap-1 mt-1">
                    {responsablesExtra.map(r => (
                      <span key={r} className="inline-flex items-center gap-1 bg-gray-100 text-gray-600 text-[11px] px-1.5 py-0.5 rounded">
                        {r}
                        <button type="button" onClick={() => onEliminarResponsable(r)} title={`Quitar "${r}" de la lista`} className="text-red-500 hover:text-red-700 font-bold">✕</button>
                      </span>
                    ))}
                  </div>
                </details>
              )}
            </div>
          </div>
          <div className="flex gap-2">
            <input type="text" placeholder="🔍 Buscar..." value={busq} onChange={e => setBusq(e.target.value)} className="input flex-1 text-sm" />
            <label className="flex items-center gap-1 text-xs cursor-pointer whitespace-nowrap">
              <input type="checkbox" checked={soloDif} onChange={e => setSoloDif(e.target.checked)} />Solo con diferencia
            </label>
          </div>
          {totalDif > 0 && <p className="text-xs text-red-600 font-semibold mt-1">⚠️ {totalDif} producto{totalDif>1?'s':''} con diferencia</p>}
        </div>
        <div className="overflow-y-auto flex-1 p-3 space-y-1.5">
          {items.map(it => {
            const conDif = Math.abs(it.diferencia) > 0.001;
            return (
              <div key={it.productoId} className={`rounded-lg border p-2.5 ${conDif?'border-red-300 bg-red-50':'border-gray-100'}`}>
                <div className="flex items-center gap-2 flex-wrap">
                  <span className="flex-1 text-sm font-medium truncate">{it.productoNombre}</span>
                  <span className="text-xs text-gray-500">Teórico: <strong>{it.stockTeorico.toFixed(2)}</strong> {it.unidad}</span>
                </div>
                <div className="flex items-center gap-2 mt-1.5">
                  <label className="text-xs text-gray-600 flex-shrink-0">Stock físico:</label>
                  <input type="number" step="0.01" min="0" value={it.stockFisico === 0 ? '' : it.stockFisico}
                    onChange={e => setFisico(it.productoId, parseFloat(e.target.value)||0)}
                    className={`input w-24 text-sm ${conDif?'border-red-400':''}`} />
                  {conDif && <span className={`text-xs font-bold ${it.diferencia<0?'text-red-600':'text-green-600'}`}>{it.diferencia>0?'+':''}{it.diferencia.toFixed(2)}</span>}
                </div>
              </div>
            );
          })}
        </div>
        <div className="p-4 border-t flex gap-2 justify-end flex-shrink-0">
          <button onClick={onCerrar} className="px-3 py-2 rounded text-sm bg-gray-100">Salir</button>
          <button onClick={() => onBorrador(arq)} className="px-3 py-2 rounded text-sm bg-yellow-100 text-yellow-800 font-medium">💾 Borrador</button>
          <button onClick={() => {
            if (!arq.responsable.trim()) { alert('Ingrese el responsable.'); return; }
            if (!confirm(`¿Cerrar arqueo?\n${totalDif} ajuste${totalDif!==1?'s':''} de stock se aplicarán.`)) return;
            onCerrar2(arq);
          }} className="px-4 py-2 rounded text-sm bg-purple-600 hover:bg-purple-700 text-white font-semibold">
            ✅ Cerrar arqueo
          </button>
        </div>
      </div>
    </div>
  );
}

// ===== MODAL NUEVO PRODUCTO =====
function ModalNuevoProdAlmacen({
  onCerrar, onGuardar,
}: {
  onCerrar: () => void;
  onGuardar: (p: Omit<ProductoAlmacen,'id'|'activo'|'actualizadoEn'>) => void;
}) {
  const [f, setF] = useState({ nombre:'', unidad:'LTS', formulacion:'', ingredienteActivo:'', categoria:'Insecticida', stockActual:0, stockMinimo:0, observaciones:'' });
  return (
    <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-3">
      <div className="bg-white rounded-xl w-full max-w-md shadow-2xl">
        <div className="p-4 border-b"><h3 className="font-bold">+ Nuevo producto</h3></div>
        <div className="p-4 space-y-3">
          <div><label className="text-xs text-gray-600 font-medium">Nombre *</label>
            <input type="text" value={f.nombre} onChange={e => setF(p=>({...p,nombre:e.target.value}))} className="input w-full mt-1" autoFocus /></div>
          <div className="grid grid-cols-2 gap-2">
            <div><label className="text-xs text-gray-600">Unidad</label>
              <select value={f.unidad} onChange={e => setF(p=>({...p,unidad:e.target.value}))} className="input w-full mt-1">
                {['LTS','KGS','FCO','SOB','CJA','OTRO'].map(u => <option key={u}>{u}</option>)}</select></div>
            <div><label className="text-xs text-gray-600">Formulación</label>
              <input type="text" value={f.formulacion} onChange={e => setF(p=>({...p,formulacion:e.target.value}))} className="input w-full mt-1" placeholder="SC, SL, EC..." /></div>
          </div>
          <div><label className="text-xs text-gray-600">Categoría</label>
            <select value={f.categoria} onChange={e => setF(p=>({...p,categoria:e.target.value}))} className="input w-full mt-1">
              {CATEGORIAS_ALMACEN.map(c => <option key={c}>{c}</option>)}</select></div>
          <div><label className="text-xs text-gray-600">Ingrediente activo</label>
            <input type="text" value={f.ingredienteActivo} onChange={e => setF(p=>({...p,ingredienteActivo:e.target.value}))} className="input w-full mt-1" /></div>
          <div className="grid grid-cols-2 gap-2">
            <div><label className="text-xs text-gray-600">Stock inicial</label>
              <input type="number" step="0.01" min="0" value={f.stockActual === 0 ? '' : f.stockActual} onChange={e => setF(p=>({...p,stockActual:parseFloat(e.target.value)||0}))} className="input w-full mt-1" /></div>
            <div><label className="text-xs text-gray-600">Stock mínimo (alerta)</label>
              <input type="number" step="0.01" min="0" value={f.stockMinimo === 0 ? '' : f.stockMinimo} onChange={e => setF(p=>({...p,stockMinimo:parseFloat(e.target.value)||0}))} className="input w-full mt-1" /></div>
          </div>
        </div>
        <div className="p-4 border-t flex gap-2 justify-end">
          <button onClick={onCerrar} className="px-4 py-2 rounded text-sm bg-gray-100">Cancelar</button>
          <button onClick={() => { if(!f.nombre.trim()){alert('Ingrese nombre.');return;} onGuardar(f); }}
            className="px-4 py-2 rounded text-sm bg-green-600 hover:bg-green-700 text-white font-semibold">Guardar</button>
        </div>
      </div>
    </div>
  );
}

// ╔══════════════════════════════════════════════════════════════════╗
// ║                    PESTAÑA ARCHIVO                                  ║
// ╚══════════════════════════════════════════════════════════════════╝

// Parte diario dentro de un expediente archivado, con botón de WhatsApp
// (reutiliza el mismo ModalCompartirWhatsApp / TarjetaResumenParte que ya
// existe en Parte Diaria — ninguno de los dos depende de estado en vivo).
function TarjetaParteArchivado({ pa, ots, rol, usuarioActivo, expedienteId, partesDelExpediente, predictivo }: {
  pa: any; ots: any[]; rol: Rol; usuarioActivo: string; expedienteId: string; partesDelExpediente: any[]; predictivo?: Predictivo;
}) {
  const [mostrarWhatsApp, setMostrarWhatsApp] = useState(false);
  const [editando, setEditando] = useState(false);
  const [pinInput, setPinInput] = useState('');
  const [errorPin, setErrorPin] = useState('');
  const [borrador, setBorrador] = useState<any>(null); // copia editable, null = no entró todavía
  const ct = pa.controlTecnico;
  const h1 = pa.registrosLote?.[0]?.horaInicio || '-';
  const h2 = pa.registrosLote?.[pa.registrosLote.length - 1]?.horaFin || '-';
  const ot = ots.find((o: any) => o.id === pa.otId);
  const original = pa._original || {}; // { 'Etiqueta legible': valorViejo }

  function abrirEdicion() {
    if (pinInput !== PIN_MAESTRO) {
      setErrorPin('PIN incorrecto. Solo el Maestro puede editar un parte archivado.');
      return;
    }
    setErrorPin('');
    setBorrador(JSON.parse(JSON.stringify(pa))); // copia profunda para no mutar pa directo
    setEditando(true);
  }

  function guardarEdicion() {
    const loteConHorasAnomalas = (borrador.registrosLote || []).find(
      (r: any) => (r.horasTrabajadas || 0) > UMBRAL_HORAS_LOTE_MAX
    );
    if (loteConHorasAnomalas) {
      alert(
        `⚠️ El lote ${loteConHorasAnomalas.lote} sigue dando ${(loteConHorasAnomalas.horasTrabajadas || 0).toFixed(2)} horas — eso es imposible. ` +
        `Corregí el horómetro antes de guardar.`
      );
      return;
    }
    const cambios: Record<string, any> = { ...(pa._original || {}) };
    const marcar = (etiqueta: string, viejo: any, nuevo: any) => {
      if (viejo !== nuevo && !(etiqueta in cambios)) cambios[etiqueta] = viejo;
    };
    marcar('Fecha del parte', pa.fecha, borrador.fecha);
    (pa.registrosLote || []).forEach((r: any, i: number) => {
      const nr = borrador.registrosLote?.[i];
      if (!nr) return;
      marcar(`Lote ${r.lote} — Hora inicio`, r.horaInicio, nr.horaInicio);
      marcar(`Lote ${r.lote} — Hora fin`, r.horaFin, nr.horaFin);
      marcar(`Lote ${r.lote} — Litros aplicados`, r.litrosAplicados, nr.litrosAplicados);
      marcar(`Lote ${r.lote} — Horómetro inicial`, r.horometroInicial, nr.horometroInicial);
      marcar(`Lote ${r.lote} — Horómetro final`, r.horometroFinal, nr.horometroFinal);
      marcar(`Lote ${r.lote} — Horas trabajadas`, r.horasTrabajadas, nr.horasTrabajadas);
    });
    if (ct) {
      const nct = borrador.controlTecnico || {};
      marcar('Humedad relativa', ct.humedadRelativa, nct.humedadRelativa);
      marcar('ΔT', ct.deltaT, nct.deltaT);
      marcar('Temperatura', ct.temperatura, nct.temperatura);
      marcar('Velocidad viento', ct.velocidadViento, nct.velocidadViento);
      marcar('Dirección viento', ct.direccionViento, nct.direccionViento);
      marcar('Presión', ct.presionPSI, nct.presionPSI);
      marcar('Caudal real', ct.caudalReal, nct.caudalReal);
      marcar('Velocidad real', ct.velocidadReal, nct.velocidadReal);
      marcar('Boquilla', ct.boquillaReal, nct.boquillaReal);
    }

    const nuevoPa = {
      ...borrador,
      _original: cambios,
      _editadoPor: usuarioActivo || 'Desconocido',
      _editadoEn: new Date().toISOString(),
    };
    const nuevoArray = partesDelExpediente.map((x: any) => x.id === pa.id ? nuevoPa : x);
    setDoc(doc(db, COL.archivo, expedienteId), { partes: nuevoArray }, { merge: true }).catch(() => {});
    setEditando(false);
    setBorrador(null);
    setPinInput('');
  }

  return (
    <div className="bg-white rounded p-2 border space-y-1">
      <div className="flex items-center justify-between gap-2 flex-wrap">
        <p className="font-bold text-gray-700">🚜 Parte — {pa.fecha} · {h1}→{h2}</p>
        <div className="flex gap-1.5">
          {rol === 'maestro' && !editando && (
            <button type="button"
              onClick={() => setEditando(true)}
              className="bg-amber-500 hover:bg-amber-600 text-white px-2 py-1 rounded text-[11px] font-semibold flex items-center gap-1 shrink-0"
              title="Corregir datos de este parte (requiere PIN de Maestro)"
            >
              ✏️ Editar
            </button>
          )}
          <button type="button"
            onClick={() => setMostrarWhatsApp(true)}
            className="bg-green-500 hover:bg-green-600 text-white px-2 py-1 rounded text-[11px] font-semibold flex items-center gap-1 shrink-0"
            title="Compartir parte por WhatsApp"
          >
            📱 WhatsApp
          </button>
          <button type="button"
            onClick={() => generarPDFParte(pa, ot, predictivo)}
            className="bg-red-600 hover:bg-red-700 text-white px-2 py-1 rounded text-[11px] font-semibold flex items-center gap-1 shrink-0"
            title="Descargar el Registro de Operación en PDF, listo para imprimir/auditoría"
          >
            📄 PDF
          </button>
        </div>
      </div>

      {editando && !borrador && (
        <div className="bg-amber-50 border border-amber-300 rounded p-2 space-y-1.5">
          <p className="text-[11px] text-amber-800">Ingrese el PIN de Maestro para editar este parte archivado.</p>
          <input
            type="password"
            autoComplete="new-password"
            name="pin-editar-parte-archivado"
            value={pinInput}
            onChange={(e) => setPinInput(e.target.value)}
            className="input text-sm w-32"
            placeholder="PIN"
          />
          {errorPin && <p className="text-[11px] text-red-600">{errorPin}</p>}
          <div className="flex gap-2">
            <button type="button" onClick={abrirEdicion} className="bg-amber-600 text-white px-2 py-1 rounded text-[11px] font-semibold">Confirmar</button>
            <button type="button" onClick={() => { setEditando(false); setPinInput(''); setErrorPin(''); }} className="text-gray-500 text-[11px]">Cancelar</button>
          </div>
        </div>
      )}

      {editando && borrador && (
        <div className="bg-amber-50 border border-amber-300 rounded p-2 space-y-2">
          <p className="text-[11px] font-bold text-amber-800">Editando — quedará registrado como editado por {usuarioActivo || 'Desconocido'}</p>
          <div>
            <label className="text-[11px] text-gray-600">Fecha del parte</label>
            <input type="date" value={borrador.fecha} onChange={e => setBorrador({ ...borrador, fecha: e.target.value })} className="input text-sm" />
          </div>
          {(borrador.registrosLote || []).map((r: any, i: number) => {
            const horasAnomalas = (r.horasTrabajadas || 0) > UMBRAL_HORAS_LOTE_MAX;
            return (
            <div key={i} className="space-y-1">
              <div className="grid grid-cols-3 gap-1">
                <div>
                  <label className="text-[10px] text-gray-500">{r.lote} — Hora inicio</label>
                  <input type="time" value={r.horaInicio} onChange={e => {
                    const nuevos = [...borrador.registrosLote]; nuevos[i] = { ...nuevos[i], horaInicio: e.target.value };
                    setBorrador({ ...borrador, registrosLote: nuevos });
                  }} className="input text-sm" />
                </div>
                <div>
                  <label className="text-[10px] text-gray-500">Hora fin</label>
                  <input type="time" value={r.horaFin} onChange={e => {
                    const nuevos = [...borrador.registrosLote]; nuevos[i] = { ...nuevos[i], horaFin: e.target.value };
                    setBorrador({ ...borrador, registrosLote: nuevos });
                  }} className="input text-sm" />
                </div>
                <div>
                  <label className="text-[10px] text-gray-500">Litros aplicados</label>
                  <input type="number" value={r.litrosAplicados} onChange={e => {
                    const nuevos = [...borrador.registrosLote]; nuevos[i] = { ...nuevos[i], litrosAplicados: parseFloat(e.target.value) || 0 };
                    setBorrador({ ...borrador, registrosLote: nuevos });
                  }} className="input text-sm" />
                </div>
              </div>
              <div className="grid grid-cols-3 gap-1">
                <div>
                  <label className="text-[10px] text-gray-500">Horómetro inicial</label>
                  <input type="number" step="0.1" value={r.horometroInicial} onChange={e => {
                    const nuevos = [...borrador.registrosLote];
                    const hInicial = parseFloat(e.target.value) || 0;
                    const bruto = (nuevos[i].horometroFinal || 0) - hInicial;
                    nuevos[i] = { ...nuevos[i], horometroInicial: hInicial, horasTrabajadas: Math.round(Math.max(0, bruto) * 100) / 100 };
                    setBorrador({ ...borrador, registrosLote: nuevos });
                  }} className={`input text-sm ${horasAnomalas ? 'border-red-500' : ''}`} />
                </div>
                <div>
                  <label className="text-[10px] text-gray-500">Horómetro final</label>
                  <input type="number" step="0.1" value={r.horometroFinal} onChange={e => {
                    const nuevos = [...borrador.registrosLote];
                    const hFinal = parseFloat(e.target.value) || 0;
                    const bruto = hFinal - (nuevos[i].horometroInicial || 0);
                    nuevos[i] = { ...nuevos[i], horometroFinal: hFinal, horasTrabajadas: Math.round(Math.max(0, bruto) * 100) / 100 };
                    setBorrador({ ...borrador, registrosLote: nuevos });
                  }} className={`input text-sm ${horasAnomalas ? 'border-red-500' : ''}`} />
                </div>
                <div className="flex flex-col justify-end">
                  <span className={`text-[11px] ${horasAnomalas ? 'text-red-600 font-bold' : 'text-gray-500'}`}>
                    = {(r.horasTrabajadas || 0).toFixed(2)} h{horasAnomalas ? ' ⚠️' : ''}
                  </span>
                </div>
              </div>
              {horasAnomalas && (
                <p className="text-[10px] text-red-700 bg-red-50 border border-red-200 rounded p-1">
                  ⚠️ Físicamente imposible en un lote — revisá el dígito o el punto decimal de los horómetros.
                </p>
              )}
            </div>
            );
          })}
          <div className="flex gap-2 pt-1">
            <button type="button" onClick={guardarEdicion} className="bg-green-600 text-white px-3 py-1 rounded text-[11px] font-semibold">Guardar cambios</button>
            <button type="button" onClick={() => { setEditando(false); setBorrador(null); }} className="text-gray-500 text-[11px]">Cancelar</button>
          </div>
        </div>
      )}

      {!editando && (
        <>
          <div className="grid grid-cols-2 gap-x-3 gap-y-0.5 text-[11px]">
            <p>💧 Boquilla: <strong>{ct?.boquillaReal||'-'}</strong></p>
            <p>📐 Caudal: <strong>{ct?.caudalReal||'-'} L/ha</strong></p>
            <p>⚙️ Presión: <strong>{ct?.presionPSI||'-'} PSI</strong></p>
            <p>🏎️ Vel: <strong>{ct?.velocidadReal||'-'} km/h</strong></p>
            <p>💨 Viento: <strong>{ct?.velocidadViento||'-'} km/h {ct?.direccionViento ? `(${ct.direccionViento})` : ''}</strong></p>
            <p>💦 Humedad: <strong>{ct?.humedadRelativa||'-'}%</strong></p>
            <p>🌡️ Temp: <strong>{ct?.temperatura||'-'}°C</strong></p>
            <p>△T: <strong>{ct?.deltaT||'-'}</strong></p>
          </div>
          {pa.registrosLote?.length > 0 && (
            <div className="mt-1 pt-1 border-t border-gray-100">
              {pa.registrosLote.map((r: any, i: number) => {
                const maquinaBase = pa.registrosLote[0]?.maquina;
                return (
                <p key={i} className="text-[11px] text-gray-600">
                  • {r.lote}: {r.horaInicio}→{r.horaFin} · {Number(r.horasTrabajadas || 0).toFixed(2)}h · {r.litrosAplicados}L
                  {(r.operador && r.operador !== pa.operador) && <span className="text-purple-700 font-semibold"> · {r.operador}</span>}
                  {(r.maquina && r.maquina !== maquinaBase) && <span className="text-purple-700 font-semibold"> · {r.maquina}</span>}
                  {r.condiciones && <span className="text-purple-700"> · 🌡️{r.condiciones.temperatura}°C 💨{r.condiciones.velocidadViento}km/h</span>}
                </p>
                );
              })}
            </div>
          )}
          {Object.keys(original).length > 0 && (
            <div className="mt-1 pt-1 border-t border-gray-100">
              <p className="text-[10px] text-gray-400 italic">
                ✏️ Editado por {pa._editadoPor} · {pa._editadoEn ? new Date(pa._editadoEn).toLocaleString('es-BO') : ''}
              </p>
              {Object.entries(original).map(([etiqueta, valor]) => (
                <p key={etiqueta} className="text-[10px] text-gray-400">
                  Original — {etiqueta}: {String(valor)}
                </p>
              ))}
            </div>
          )}
        </>
      )}

      {mostrarWhatsApp && (
        <ModalCompartirWhatsApp
          id={'resumen-parte-archivo-' + pa.id}
          titulo={`Parte_${pa.fecha}_${ot?.maquina || ''}`}
          onCerrar={() => setMostrarWhatsApp(false)}
          contenido={<TarjetaResumenParte parte={pa} ot={ot} />}
        />
      )}
    </div>
  );
}

// ╔══════════════════════════════════════════════════════════════════╗
// ║                         PESTAÑA AUDITORÍA                          ║
// ╚══════════════════════════════════════════════════════════════════╝
// Acceso propio, separado del rol de sesión: aunque alguien haya entrado a
// la app como Maestro, necesita el código de Auditoría (distinto del PIN de
// Maestro) para ver esto. La primera vez ese código ES el PIN de Maestro
// actual; desde acá se puede cambiar por uno nuevo que solo Juan Carlos
// conozca — a partir de ese cambio, el PIN de Maestro normal ya NO sirve
// para entrar acá.
function PestanaAuditoria({
  usuariosIndividuales, setUsuariosIndividuales,
  rangosFolios, setRangosFolios,
  folioHistorial,
  usuarioActivo, ots,
}: {
  usuariosIndividuales: UsuarioApp[];
  setUsuariosIndividuales: (u: UsuarioApp[]) => void;
  rangosFolios: RangoFolios[];
  setRangosFolios: (r: RangoFolios[]) => void;
  folioHistorial: FolioHistorial[];
  usuarioActivo: string;
  ots: OT[];
}) {
  const [desbloqueada, setDesbloqueada] = useState(false);
  const [codigoInput, setCodigoInput] = useState('');
  const [errorCodigo, setErrorCodigo] = useState('');
  const [subtab, setSubtab] = useState<'usuarios' | 'folios'>('usuarios');

  async function intentarDesbloquear() {
    const codigoActual = await leerFirestore<string>('auditoria_pin', PIN_MAESTRO);
    if (codigoInput === codigoActual) {
      setDesbloqueada(true);
      setErrorCodigo('');
      setCodigoInput('');
    } else {
      setErrorCodigo('❌ Código incorrecto.');
    }
  }

  if (!desbloqueada) {
    return (
      <div className="max-w-sm mx-auto bg-white rounded-lg shadow p-5 mt-8">
        <h2 className="font-bold text-gray-800 mb-1">🔒 Auditoría</h2>
        <p className="text-xs text-gray-500 mb-3">
          Acceso restringido — pide un código propio, distinto del PIN de Maestro normal.
          La primera vez, ese código es el PIN de Maestro actual.
        </p>
        <form onSubmit={(e) => { e.preventDefault(); intentarDesbloquear(); }} className="flex flex-col gap-2">
          <input
            type="password"
            inputMode="numeric"
            autoComplete="new-password"
            name="codigo-auditoria"
            placeholder="Código de Auditoría"
            value={codigoInput}
            onChange={(e) => setCodigoInput(e.target.value)}
            className="input w-full"
            autoFocus
          />
          <button type="submit" className="bg-slate-800 text-white rounded-lg py-2 font-semibold">Entrar</button>
          {errorCodigo && <p className="text-xs text-red-600">{errorCodigo}</p>}
        </form>
      </div>
    );
  }

  return (
    <div className="space-y-3">
      <div className="bg-gray-800 text-white rounded-lg px-4 py-3">
        <h2 className="font-bold text-base">🔒 Auditoría</h2>
        <p className="text-gray-400 text-xs">Acceso exclusivo — usuarios, PINes y numeración controlada de OT.</p>
      </div>

      <div className="bg-slate-800 rounded-lg flex overflow-x-auto">
        {[
          { id: 'usuarios', label: '👤 Usuarios y PIN' },
          { id: 'folios', label: '🎫 Folios de OT' },
        ].map((t) => (
          <button key={t.id} onClick={() => setSubtab(t.id as any)}
            className={`px-4 py-2.5 font-semibold text-sm whitespace-nowrap ${subtab === t.id ? 'bg-green-600 text-white' : 'bg-slate-700 text-slate-300 hover:bg-slate-600 hover:text-white'}`}>
            {t.label}
          </button>
        ))}
      </div>

      {subtab === 'usuarios' && (
        <PanelUsuarios usuarios={usuariosIndividuales} usuarioActivo={usuarioActivo} />
      )}
      {subtab === 'folios' && (
        <PanelFolios rangos={rangosFolios} historial={folioHistorial} usuarioActivo={usuarioActivo} />
      )}

      <div className="bg-white rounded-lg shadow p-4">
        <h3 className="font-bold text-gray-800 text-sm mb-2">🔑 Cambiar código de Auditoría</h3>
        <CambiarCodigoAuditoria />
      </div>
    </div>
  );
}

function CambiarCodigoAuditoria() {
  const [nuevo, setNuevo] = useState('');
  const [confirmar, setConfirmar] = useState('');
  const [msg, setMsg] = useState('');
  return (
    <div className="space-y-2">
      <p className="text-xs text-gray-500">
        Después de cambiarlo, el PIN de Maestro normal deja de servir para entrar a Auditoría — solo este código nuevo.
        Guardalo en un lugar seguro; nadie más lo va a conocer.
      </p>
      <div className="grid grid-cols-2 gap-2">
        <input type="password" inputMode="numeric" placeholder="Código nuevo" value={nuevo}
          onChange={(e) => setNuevo(e.target.value)} className="input" autoComplete="new-password" />
        <input type="password" inputMode="numeric" placeholder="Repetir código" value={confirmar}
          onChange={(e) => setConfirmar(e.target.value)} className="input" autoComplete="new-password" />
      </div>
      <button
        onClick={async () => {
          if (nuevo.length < 4) { setMsg('❌ Muy corto — al menos 4 dígitos.'); return; }
          if (nuevo !== confirmar) { setMsg('❌ No coinciden.'); return; }
          if (!confirm('¿Confirmar el cambio de código de Auditoría? Anotalo antes de aceptar.')) return;
          await guardar('auditoria_pin', nuevo);
          setMsg('✅ Código actualizado.');
          setNuevo(''); setConfirmar('');
        }}
        className="bg-slate-800 text-white px-4 py-2 rounded-lg text-sm font-semibold"
      >
        Guardar código nuevo
      </button>
      {msg && <p className="text-xs">{msg}</p>}
    </div>
  );
}

function PanelUsuarios({ usuarios, usuarioActivo }: { usuarios: UsuarioApp[]; usuarioActivo: string }) {
  const [nombre, setNombre] = useState('');
  const [rolNuevo, setRolNuevo] = useState<'maestro' | 'operador'>('operador');
  const [pinNuevo, setPinNuevo] = useState('');
  const [error, setError] = useState('');

  async function crear() {
    setError('');
    if (!nombre.trim()) { setError('Falta el nombre.'); return; }
    if (pinNuevo.length < 4) { setError('El PIN debe tener al menos 4 dígitos.'); return; }
    const colision = [PIN_VISITANTE, PIN_OPERADOR, PIN_MAESTRO, PIN_EXCEPCIÓN].includes(pinNuevo)
      || usuarios.some((u) => u.pin === pinNuevo);
    if (colision) { setError('Ese PIN ya está en uso (por otra persona o por uno de los PINes genéricos). Elegí otro.'); return; }
    const nuevo: UsuarioApp = {
      id: `user_${Date.now()}`,
      nombre: nombre.trim(),
      pin: pinNuevo,
      rol: rolNuevo,
      activo: true,
      creadoEn: new Date().toISOString(),
      creadoPor: usuarioActivo || 'Auditoría',
    };
    await dbSet(COL.usuarios, nuevo.id, nuevo);
    setNombre(''); setPinNuevo('');
  }

  async function toggleActivo(u: UsuarioApp) {
    await dbSet(COL.usuarios, u.id, { ...u, activo: !u.activo });
  }

  return (
    <div className="bg-white rounded-lg shadow p-4 space-y-4">
      <div>
        <h3 className="font-bold text-gray-800 text-sm mb-2">+ Nuevo usuario</h3>
        <div className="grid grid-cols-1 md:grid-cols-4 gap-2">
          <input value={nombre} onChange={(e) => setNombre(e.target.value)} placeholder="Nombre completo" className="input" />
          <select value={rolNuevo} onChange={(e) => setRolNuevo(e.target.value as any)} className="input">
            <option value="operador">Operador</option>
            <option value="maestro">Maestro</option>
          </select>
          <input value={pinNuevo} onChange={(e) => setPinNuevo(e.target.value)} placeholder="PIN (4-6 dígitos)" inputMode="numeric" className="input" />
          <button onClick={crear} className="bg-green-600 text-white rounded-lg font-semibold text-sm">+ Crear</button>
        </div>
        {error && <p className="text-xs text-red-600 mt-1">{error}</p>}
      </div>
      <div className="border-t border-gray-200 pt-3 space-y-1.5">
        <h3 className="font-bold text-gray-800 text-sm mb-1">Usuarios registrados ({usuarios.length})</h3>
        {usuarios.length === 0 && <p className="text-xs text-gray-400">Ninguno todavía — todos entran con los PINes genéricos compartidos.</p>}
        {usuarios.map((u) => (
          <div key={u.id} className={`flex items-center justify-between rounded px-3 py-2 text-sm ${u.activo ? 'bg-gray-50' : 'bg-gray-100 opacity-60'}`}>
            <div>
              <span className="font-semibold">{u.nombre}</span>
              <span className="text-xs text-gray-500 ml-2">{u.rol === 'maestro' ? '👑 Maestro' : '🔧 Operador'} · PIN {u.pin}</span>
            </div>
            <button onClick={() => toggleActivo(u)} className={`text-xs px-2 py-1 rounded font-semibold ${u.activo ? 'bg-red-100 text-red-700' : 'bg-green-100 text-green-700'}`}>
              {u.activo ? 'Desactivar' : 'Reactivar'}
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

function PanelFolios({ rangos, historial, usuarioActivo }: { rangos: RangoFolios[]; historial: FolioHistorial[]; usuarioActivo: string }) {
  const [desde, setDesde] = useState('');
  const [hasta, setHasta] = useState('');
  const [error, setError] = useState('');
  const [busqueda, setBusqueda] = useState('');

  const historialPorNumero: Record<number, FolioHistorial> = {};
  historial.forEach((h) => { historialPorNumero[h.numero] = h; });

  const totalRango = rangos.reduce((s, r) => s + (r.hasta - r.desde + 1), 0);
  const usados = historial.filter((h) => h.estado === 'usado').length;
  const eliminados = historial.filter((h) => h.estado === 'eliminado').length;
  const disponibles = totalRango - usados - eliminados;

  async function crearRango() {
    setError('');
    const d = parseInt(desde), h = parseInt(hasta);
    if (!d || !h || h <= d) { setError('Rango inválido — "Hasta" debe ser mayor que "Desde".'); return; }
    // Chequear solapamiento con rangos existentes
    const solapa = rangos.some((r) => d <= r.hasta && h >= r.desde);
    if (solapa) { setError('Ese rango se solapa con uno que ya existe.'); return; }
    const nuevo: RangoFolios = {
      id: `rango_${Date.now()}`,
      desde: d,
      hasta: h,
      creadoEn: new Date().toISOString(),
      creadoPor: usuarioActivo || 'Auditoría',
    };
    await dbSet(COL.folios_rangos, nuevo.id, nuevo);
    setDesde(''); setHasta('');
  }

  const historialFiltrado = busqueda
    ? historial.filter((h) => String(h.numero).includes(busqueda) || (h.otNumero || '').includes(busqueda))
    : historial;

  return (
    <div className="space-y-3">
      <div className="bg-white rounded-lg shadow p-4">
        <h3 className="font-bold text-gray-800 text-sm mb-2">+ Crear rango de folios</h3>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-2">
          <input value={desde} onChange={(e) => setDesde(e.target.value)} placeholder="Desde (ej. 22000)" inputMode="numeric" className="input" />
          <input value={hasta} onChange={(e) => setHasta(e.target.value)} placeholder="Hasta (ej. 22099)" inputMode="numeric" className="input" />
          <button onClick={crearRango} className="bg-green-600 text-white rounded-lg font-semibold text-sm">+ Crear rango</button>
        </div>
        {error && <p className="text-xs text-red-600 mt-1">{error}</p>}
        <div className="mt-3 flex flex-wrap gap-2">
          {rangos.map((r) => (
            <span key={r.id} className="text-xs bg-slate-100 px-2 py-1 rounded">{r.desde} – {r.hasta}</span>
          ))}
          {rangos.length === 0 && <p className="text-xs text-gray-400">Sin rangos creados todavía — el N° de OT sigue siendo 100% manual hasta que crees uno.</p>}
        </div>
      </div>

      {rangos.length > 0 && (
        <div className="grid grid-cols-3 gap-2">
          <div className="bg-white rounded-lg shadow p-3 text-center">
            <p className="text-2xl font-bold text-green-600">{disponibles}</p>
            <p className="text-xs text-gray-500">Disponibles</p>
          </div>
          <div className="bg-white rounded-lg shadow p-3 text-center">
            <p className="text-2xl font-bold text-blue-600">{usados}</p>
            <p className="text-xs text-gray-500">Usados</p>
          </div>
          <div className="bg-white rounded-lg shadow p-3 text-center">
            <p className="text-2xl font-bold text-red-600">{eliminados}</p>
            <p className="text-xs text-gray-500">Eliminados</p>
          </div>
        </div>
      )}

      <div className="bg-white rounded-lg shadow p-4">
        <div className="flex items-center justify-between mb-2 flex-wrap gap-2">
          <h3 className="font-bold text-gray-800 text-sm">📋 Planilla de trazabilidad</h3>
          <input value={busqueda} onChange={(e) => setBusqueda(e.target.value)} placeholder="🔍 Buscar folio u OT..." className="input text-sm w-56" />
        </div>
        {historialFiltrado.length === 0 ? (
          <p className="text-xs text-gray-400 text-center py-6">Sin movimientos todavía — los folios usados/eliminados van a aparecer acá.</p>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-xs">
              <thead>
                <tr className="text-left text-gray-500 border-b border-gray-200">
                  <th className="py-1 pr-2">Folio</th>
                  <th className="py-1 pr-2">Estado</th>
                  <th className="py-1 pr-2">N° OT</th>
                  <th className="py-1 pr-2">Fecha/hora</th>
                  <th className="py-1 pr-2">Usuario</th>
                  <th className="py-1 pr-2">Motivo (si eliminado)</th>
                </tr>
              </thead>
              <tbody>
                {historialFiltrado.map((h) => (
                  <tr key={h.id} className="border-b border-gray-100">
                    <td className="py-1 pr-2 font-semibold">{h.numero}</td>
                    <td className="py-1 pr-2">
                      {h.estado === 'usado'
                        ? <span className="text-blue-700">🎫 Usado</span>
                        : <span className="text-red-700">🗑️ Eliminado</span>}
                    </td>
                    <td className="py-1 pr-2">{h.otNumero || '—'}</td>
                    <td className="py-1 pr-2">{h.estado === 'usado' ? h.usadoEn?.slice(0, 16).replace('T', ' ') : h.eliminadoEn?.slice(0, 16).replace('T', ' ')}</td>
                    <td className="py-1 pr-2">{h.estado === 'usado' ? h.usadoPor : h.eliminadoPor}</td>
                    <td className="py-1 pr-2 text-gray-500">{h.motivoEliminacion || '—'}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}

function PestanaArchivo({
  rol, predictivos, setPredictivos, ots, setOts, partes, setPartes, usuarioActivo, campanaActiva,

}: {
  rol: Rol;
  predictivos: Predictivo[];
  setPredictivos: (p: Predictivo[]) => void;
  ots: OT[];
  setOts: (o: OT[]) => void;
  partes: ParteDiario[];
  setPartes: (p: ParteDiario[]) => void;
  usuarioActivo: string;
  campanaActiva: string;
}) {
  const [datosArchivo, setDatosArchivo] = useState<ExpedienteArchivo[]>(() => cacheGet('af_archivo', [] as ExpedienteArchivo[]));
  const [cargando, setCargando] = useState(() => cacheGet('af_archivo', [] as ExpedienteArchivo[]).length === 0);
  const [busqueda, setBusqueda] = useState('');
  const [filtroCampana, setFiltroCampana] = useState('');
  const [filtroMaquina, setFiltroMaquina] = useState('');
  const [expandido, setExpandido] = useState<string | null>(null);
  // Subpestañas de consumo — antes vivían en Almacén; se mudaron acá porque
  // conceptualmente son un reporte sobre lo YA TRABAJADO/archivado, no sobre
  // el stock en sí (eso se quedó en Almacén: Inventario + Arqueo).
  const [subtabArchivo, setSubtabArchivo] = useState<'expedientes'|'maquina'|'lotepivot'|'dashboard'>('expedientes');
  const [movimientos, setMovimientos] = useState<MovimientoAlmacen[]>(() => cacheGet(COL.almacen_movimientos, [] as MovimientoAlmacen[]));
  const [filtroPivot, setFiltroPivot] = useState('');
  // Igual que el cartel global del header: el primer snapshot puede venir
  // del caché local (IndexedDB) y estar incompleto hasta que Firestore
  // reconcilia con el servidor unos segundos después.
  const [archivoConfirmadoServidor, setArchivoConfirmadoServidor] = useState(false);

  // Suscripción ÚNICA a af_archivo — no depende de predictivos/ots/partes,
  // así no se da de baja y se re-crea cada vez que esas colecciones cambian
  // de referencia mientras sincronizan (eso era lo que colgaba "Cargando
  // archivo..." en conexiones lentas: se reiniciaba el pedido de red antes
  // de recibir la primera respuesta).
  useEffect(() => {
    const unsub = onSnapshot(
      collection(db, COL.archivo),
      (snap) => {
        const data = snap.docs.map(d => d.data() as ExpedienteArchivo);
        setDatosArchivo(data);
        cacheSet('af_archivo', data);
        setCargando(false);
        if (!snap.metadata.fromCache) setArchivoConfirmadoServidor(true);
      },
      () => setCargando(false)
    );
    const unsubMov = onSnapshot(collection(db, COL.almacen_movimientos), (snap) => {
      const data = snap.docs.map(d => d.data() as MovimientoAlmacen)
        .sort((a, b) => (b.creadoEn || '').localeCompare(a.creadoEn || ''));
      setMovimientos(data);
      cacheSet(COL.almacen_movimientos, data);
    }, () => {});
    return () => { unsub(); unsubMov(); };
  }, []);

  // El merge con predictivos/ots/partes SÍ puede recalcularse libremente
  // cuando cambian — es cálculo local en memoria, no vuelve a tocar la red.
  const expedientes = useMemo(() => {
    const predsArchivados = predictivos.filter(p => p.archivado);
    const expDatos: ExpedienteArchivo[] = [];
    for (const pred of predsArchivados) {
      if (datosArchivo.some(e => e.predictivo.id === pred.id)) continue;
      const otsRelac = ots.filter(o => o.predictivoId === pred.id);
      const idsOTs = otsRelac.map(o => o.id);
      const partesRelac = partes.filter(pa => idsOTs.includes(pa.otId));
      expDatos.push({
        id: `AF-${pred.creadoEn?.slice(0,4)}-${pred.id.slice(-5)}`,
        campana: pred.campana || campanaActiva,
        fechaCierre: pred.editadoEn ? fechaLocalISO(new Date(pred.editadoEn)) : pred.creadoEn ? fechaLocalISO(new Date(pred.creadoEn)) : '',
        cerradoPor: pred.editadoPor || 'Sistema',
        predictivo: pred,
        ots: otsRelac,
        partes: partesRelac,
        _maquinas: [...new Set(otsRelac.map(o => o.maquina))],
        _operadores: [...new Set(partesRelac.map(pa => pa.operador))],
        _productos: [...new Set(otsRelac.flatMap(o => o.productos.map(pr => pr.nombre)))],
        _lotes: [...new Set(otsRelac.flatMap(o => o.lotes))],
        _cultivo: pred.cultivo,
        _fechaInicio: pred.fechaDesde || pred.creadoEn,
      });
    }
    return [...datosArchivo, ...expDatos].sort((a, b) => b.fechaCierre.localeCompare(a.fechaCierre));
  }, [datosArchivo, predictivos, ots, partes, campanaActiva]);

  const campanasUnicas = [...new Set(expedientes.map(e => e.campana))];
  const maquinasUnicas = [...new Set(expedientes.flatMap(e => e._maquinas))];

  // Consumo real reconstruido (en vivo + archivado) — mismo cálculo que
  // antes vivía en Almacén. Usa `expedientes` (no `datosArchivo` a secas)
  // porque ya incluye el caso de un predictivo archivado que aún no generó
  // su documento en af_archivo.
  const aplicacionesReales = useMemo(
    () => construirAplicacionesReales(ots, partes, expedientes),
    [ots, partes, expedientes]
  );
  const movimientosManualesNoMaquinaria = movimientos.filter(
    m => !(m.tipo === 'egreso' && m.tipoAplicacion === 'maquinaria')
  );
  const movimientosCompletos: MovimientoAlmacen[] = [
    ...aplicacionesReales,
    ...movimientosManualesNoMaquinaria,
  ].sort((a, b) => (b.fecha || '').localeCompare(a.fecha || ''));

  const expedientesFiltrados = expedientes.filter(e => {
    const q = busqueda.toLowerCase();
    if (filtroCampana && e.campana !== filtroCampana) return false;
    if (filtroMaquina && !e._maquinas.includes(filtroMaquina)) return false;
    if (!q) return true;
    return (
      e.id.toLowerCase().includes(q) ||
      e.predictivo.idOrdenServicio?.toLowerCase().includes(q) ||
      e._cultivo.toLowerCase().includes(q) ||
      e._maquinas.some(m => m.toLowerCase().includes(q)) ||
      e._operadores.some(o => o.toLowerCase().includes(q)) ||
      e._productos.some(p => p.toLowerCase().includes(q)) ||
      e._lotes.some(l => l.toLowerCase().includes(q)) ||
      e.cerradoPor.toLowerCase().includes(q)
    );
  });

  if (cargando) return (
    <div className="flex items-center justify-center py-20 text-gray-400">
      <p>⏳ Cargando archivo...</p>
    </div>
  );

  // ===== AGRUPAR POR MES para manejar miles de registros =====
  const meses: Record<string, ExpedienteArchivo[]> = {};
  expedientesFiltrados.forEach(e => {
    const mes = e.fechaCierre?.slice(0, 7) || 'Sin fecha'; // "2026-06"
    if (!meses[mes]) meses[mes] = [];
    meses[mes].push(e);
  });
  const mesesOrdenados = Object.keys(meses).sort((a, b) => b.localeCompare(a));
  // Mes calendario real de hoy — no "el más reciente de la lista" — para
  // decidir qué grupo arranca desplegado.
  const mesActualYm = new Date().toISOString().slice(0, 7);

  const nombreMes = (ym: string) => {
    if (ym === 'Sin fecha') return 'Sin fecha';
    const [y, m] = ym.split('-');
    const nombres = ['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
    return `${nombres[parseInt(m)-1]} ${y}`;
  };

  return (
    <div className="space-y-3">
      {/* Header compacto */}
      <div className="bg-gray-800 text-white rounded-lg px-4 py-3 flex items-center justify-between">
        <div>
          <h2 className="font-bold text-base">📁 Archivo de Expedientes</h2>
          <p className="text-gray-400 text-xs">{expedientes.length} registros · Solo lectura</p>
        </div>
      </div>

      {/* Sub-tabs */}
      <div className="bg-slate-800 rounded-lg flex overflow-x-auto">
        {[
          {id:'expedientes',label:'📁 Expedientes'},
          {id:'maquina',label:'🚜 Máquina'},
          {id:'lotepivot',label:'📍 Lote/Pivot'},
          {id:'dashboard',label:'📈 Dashboard'},
        ].map(t => (
          <button key={t.id} onClick={() => setSubtabArchivo(t.id as any)}
            className={`px-4 py-2.5 font-semibold text-sm whitespace-nowrap transition-colors ${subtabArchivo===t.id ? 'bg-green-600 text-white' : 'bg-slate-700 text-slate-300 hover:bg-slate-600 hover:text-white'}`}>
            {t.label}
          </button>
        ))}
      </div>

      {subtabArchivo === 'expedientes' && (
      <>
      {/* Filtros compactos */}
      <div className="bg-white rounded-lg p-2 shadow flex gap-2 flex-wrap">
        <input
          type="text"
          name="buscar-archivo-expedientes"
          autoComplete="off"
          placeholder="🔍 Buscar ID, cultivo, máquina, operador, lote..."
          value={busqueda}
          onChange={e => setBusqueda(e.target.value)}
          className="input flex-1 min-w-[180px] text-sm"
        />
        <select value={filtroCampana} onChange={e => setFiltroCampana(e.target.value)} className="input text-sm">
          <option value="">Todas las campañas</option>
          {campanasUnicas.map(c => <option key={c}>{c}</option>)}
        </select>
        <select value={filtroMaquina} onChange={e => setFiltroMaquina(e.target.value)} className="input text-sm">
          <option value="">Todas las máquinas</option>
          {maquinasUnicas.map(m => <option key={m}>{m}</option>)}
        </select>
        {(busqueda || filtroCampana || filtroMaquina) && (
          <>
            <span className="text-xs text-gray-500 self-center">{expedientesFiltrados.length} resultado{expedientesFiltrados.length!==1?'s':''}</span>
            <button
              type="button"
              onClick={() => { setBusqueda(''); setFiltroCampana(''); setFiltroMaquina(''); }}
              className="text-xs text-purple-600 hover:text-purple-800 font-semibold self-center underline"
            >
              ✕ Limpiar filtros
            </button>
          </>
        )}
      </div>

      {/* Lista agrupada por mes */}
      {expedientesFiltrados.length === 0 ? (
        <div className="bg-white rounded-lg p-8 text-center text-gray-400">
          <p className="text-3xl mb-2">📁</p>
          {expedientes.length === 0
            ? <p className="text-sm">Sin expedientes archivados todavía.</p>
            : (
              <>
                <p className="text-sm mb-2">Sin resultados para ese filtro.</p>
                <button
                  type="button"
                  onClick={() => { setBusqueda(''); setFiltroCampana(''); setFiltroMaquina(''); }}
                  className="text-sm text-purple-600 hover:text-purple-800 font-semibold underline"
                >
                  ✕ Limpiar filtros
                </button>
              </>
            )}
        </div>
      ) : (
        <div className="space-y-2">
          {mesesOrdenados.map(mes => (
            <GrupoMes
              key={mes}
              titulo={nombreMes(mes)}
              esMesActual={mes === mesActualYm}
              expedientes={meses[mes]}
              expandidoId={expandido}
              setExpandidoId={setExpandido}
              rol={rol}
              usuarioActivo={usuarioActivo}
              onEliminar={(exp) => {
                dbDelete(COL.archivo, exp.id);
                exp.partes.forEach((pa: any) => dbDelete(COL.partes, pa.id));
                exp.ots.forEach((o: any) => dbDelete(COL.ots, o.id));
                if (exp.predictivo?.id) dbDelete(COL.predictivos, exp.predictivo.id);
                setDatosArchivo(prev => prev.filter(e => e.id !== exp.id));
              }}
            />
          ))}
        </div>
      )}
      </>
      )}

      {/* ===== MÁQUINA — consumo agrupado por máquina (antes "Movimientos") ===== */}
      {subtabArchivo === 'maquina' && (() => {
        const grupos: Record<string, MovimientoAlmacen[]> = {};
        movimientosCompletos.forEach(m => {
          const key = m.tipoAplicacion === 'maquinaria' ? (m.maquina || 'Sin máquina')
                    : m.tipoAplicacion === 'pivote'     ? `💧 ${m.pivot || 'Pivot'}`
                    : m.tipo === 'ingreso'              ? '📦 Ingresos'
                    :                                     '⇔ Ajustes';
          if (!grupos[key]) grupos[key] = [];
          grupos[key].push(m);
        });
        const gruposOrdenados = Object.entries(grupos).sort(([a],[b]) => a.localeCompare(b));

        return (
          <div className="bg-white rounded-lg shadow p-3 space-y-2">
            <div className="flex items-center justify-between">
              <p className="text-xs text-gray-500">{movimientosCompletos.length} movimientos totales</p>
            </div>
            {movimientosCompletos.length === 0 ? (
              <div className="text-center py-10 text-gray-400"><p className="text-3xl mb-2">🚜</p><p>Sin movimientos todavía.</p></div>
            ) : (
              <div className="space-y-2">
                {gruposOrdenados.map(([grupo, movs]) => (
                  <GrupoMovimientosAlmacen key={grupo} titulo={grupo} movimientos={movs} />
                ))}
              </div>
            )}
          </div>
        );
      })()}

      {/* ===== LOTE/PIVOT — agrupado por pivot (antes "Por Lote/Pivot") ===== */}
      {subtabArchivo === 'lotepivot' && (() => {
        const egresosConLote2 = movimientosCompletos.filter(m => m.tipo==='egreso' && m.lotes?.length > 0);
        const porPivot: Record<string, MovimientoAlmacen[]> = {};
        egresosConLote2.forEach(m => {
          m.lotes?.forEach(lote => {
            const pivot = lote.split('-')[0] || lote.split('L')[0] || lote;
            if (!porPivot[pivot]) porPivot[pivot] = [];
            if (!porPivot[pivot].some(x => x.id === m.id)) porPivot[pivot].push(m);
          });
        });
        const pivotsFiltradosLocal = filtroPivot
          ? Object.keys(porPivot).filter(p => p === filtroPivot)
          : Object.keys(porPivot).sort();

        return (
          <div className="bg-white rounded-lg shadow p-3 space-y-2">
            <select value={filtroPivot} onChange={e => setFiltroPivot(e.target.value)} className="input text-sm w-full">
              <option value="">Todos los pivots</option>
              {PIVOTES_LISTA.map(p => <option key={p}>{p}</option>)}
            </select>
            {egresosConLote2.length === 0 ? (
              <div className="text-center py-10 text-gray-400">
                <p className="text-3xl mb-2">📍</p>
                <p className="text-sm">Sin aplicaciones registradas todavía.</p>
              </div>
            ) : (
              <div className="space-y-2">
                {pivotsFiltradosLocal.map(pivot => {
                  const movsPivot = egresosConLote2.filter(m => m.lotes?.some(l => l.startsWith(pivot)));
                  const lotesPivot = [...new Set(movsPivot.flatMap(m => m.lotes?.filter(l => l.startsWith(pivot)) || []))].sort();
                  const totalProductos = [...new Set(movsPivot.map(m => m.productoNombre))].length;
                  return (
                    <GrupoPivotAlmacen
                      key={pivot}
                      pivot={pivot}
                      lotes={lotesPivot}
                      movimientos={movsPivot}
                      totalProductos={totalProductos}
                    />
                  );
                })}
              </div>
            )}
          </div>
        );
      })()}

      {/* ===== DASHBOARD ===== */}
      {subtabArchivo === 'dashboard' && (
        <div className="bg-white rounded-lg shadow">
          <DashboardAlmacen
            ots={ots}
            partes={partes}
            movimientos={movimientosCompletos}
            archivoExpedientes={expedientes}
            confirmadoServidor={archivoConfirmadoServidor}
          />
        </div>
      )}
    </div>
  );
}

// ===== GRUPO DE MES — colapsable =====
function GrupoMes({
  titulo, esMesActual, expedientes, expandidoId, setExpandidoId, rol, onEliminar, usuarioActivo,
}: {
  titulo: string;
  esMesActual: boolean;
  expedientes: ExpedienteArchivo[];
  expandidoId: string | null;
  setExpandidoId: (id: string | null) => void;
  rol: Rol;
  onEliminar: (exp: ExpedienteArchivo) => void;
  usuarioActivo: string;
}) {
  // Solo el mes calendario en curso arranca desplegado; los meses ya
  // pasados arrancan plegados (igual se pueden abrir con un clic).
  const [abierto, setAbierto] = useState(esMesActual);

  return (
    <div className="bg-white rounded-lg shadow overflow-hidden">
      {/* Cabecera del mes — clic para colapsar todo el mes */}
      <button
        onClick={() => setAbierto(!abierto)}
        className="w-full flex items-center justify-between px-4 py-2.5 bg-gray-800 text-white hover:bg-gray-700 transition-colors"
      >
        <span className="font-semibold text-sm">📅 {titulo}</span>
        <div className="flex items-center gap-3">
          <span className="text-xs bg-gray-600 px-2 py-0.5 rounded">
            {expedientes.length} aplicación{expedientes.length!==1?'es':''}
          </span>
          <span className="text-gray-400 text-xs">{abierto ? '▲' : '▼'}</span>
        </div>
      </button>

      {/* Filas de expedientes — ultra compactas */}
      {abierto && (
        <div className="divide-y divide-gray-100">
          {expedientes.map(exp => (
            <FilaExpediente
              key={exp.id}
              exp={exp}
              expandido={expandidoId === exp.id}
              onToggle={() => setExpandidoId(expandidoId === exp.id ? null : exp.id)}
              rol={rol}
              usuarioActivo={usuarioActivo}
              onEliminar={() => onEliminar(exp)}
            />
          ))}
        </div>
      )}
    </div>
  );
}

// ===== FILA COMPACTA DE EXPEDIENTE =====
function FilaExpediente({
  exp, expandido, onToggle, rol, onEliminar, usuarioActivo,
}: {
  exp: ExpedienteArchivo;
  expandido: boolean;
  onToggle: () => void;
  rol: Rol;
  onEliminar: () => void;
  usuarioActivo: string;
}) {
  const maquinas = exp._maquinas.join(', ');
  const lotes = exp._lotes.slice(0, 3).join(', ') + (exp._lotes.length > 3 ? ` +${exp._lotes.length-3}` : '');
  const operador = exp._operadores[0]?.split(' ')[0] || exp.cerradoPor.split(' ')[0];
  const fecha = exp.fechaCierre?.slice(8) || ''; // Solo el día DD
  const tuvoExcepcion = exp.ots?.some((ot: any) => ot.excepciónAprobado);
  const tieneAnalisisGotas = !!exp.predictivo?.analisisGotasBase64;

  return (
    <div>
      {/* FILA COMPACTA — una sola línea. Fondo lila tenue + borde izquierdo
          si el predictivo tiene análisis de gotas subido, para poder
          identificarlo de un vistazo sin tener que expandir cada fila. */}
      <div
        className={`flex items-center gap-2 px-3 py-2 hover:bg-gray-50 cursor-pointer text-xs ${
          tieneAnalisisGotas ? 'bg-purple-50 border-l-4 border-purple-400' : ''
        }`}
        onClick={onToggle}
      >
        {/* Máquina */}
        <span className="bg-gray-700 text-white px-1.5 py-0.5 rounded font-mono text-[11px] flex-shrink-0">
          {maquinas}
        </span>
        {/* Análisis de gotas — visible sin expandir */}
        {tieneAnalisisGotas && (
          <span className="flex-shrink-0" title="Tiene análisis de deposición de gotas subido">💧</span>
        )}
        {/* Excepción — visible sin expandir */}
        {tuvoExcepcion && (
          <span className="flex-shrink-0" title="Esta OT usó excepción de contaminación cruzada">⚠️</span>
        )}
        {/* Cultivo */}
        <span className="text-green-700 font-semibold flex-shrink-0">{exp._cultivo}</span>
        {/* Lotes */}
        <span className="text-gray-500 truncate flex-1 min-w-0">📍{lotes}</span>
        {/* Operador */}
        <span className="text-gray-600 flex-shrink-0">👤{operador}</span>
        {/* Día */}
        <span className="text-gray-400 flex-shrink-0">día {fecha}</span>
        {/* Expand */}
        <span className="text-blue-400 flex-shrink-0">{expandido ? '▲' : '▼'}</span>
      </div>

      {/* DETALLE EXPANDIDO */}
      {expandido && (
        <div className="bg-gray-50 border-t border-gray-100 p-3 space-y-3 text-xs">

          {/* ID + acciones */}
          <div className="flex items-center justify-between flex-wrap gap-2">
            <span className="font-mono text-gray-500 text-[11px]">{exp.id}</span>
            <div className="flex gap-3">
              {rol === 'maestro' && (
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    const pin = prompt('PIN Maestro para eliminar:');
                    if (pin !== PIN_MAESTRO) { alert('PIN incorrecto.'); return; }
                    if (!confirm(`¿Eliminar expediente ${exp.id}? No se puede deshacer.`)) return;
                    onEliminar();
                  }}
                  className="text-red-500 hover:text-red-700 text-xs"
                >
                  🗑️ Eliminar
                </button>
              )}
            </div>
          </div>

          {/* Banner solo lectura */}
          <div className="bg-amber-50 border border-amber-200 rounded px-2 py-1 text-amber-800 text-center text-[11px] font-semibold">
            🔒 Solo lectura — expediente archivado
          </div>

          {/* Responsables */}
          <div className="bg-green-50 border border-green-200 rounded p-2 space-y-1">
            <p className="font-bold text-green-800 text-[11px] mb-1">👥 Responsables</p>
            <p>📋 <strong>Predictivo:</strong> {exp.predictivo.creadoPor || exp.predictivo.responsable || '—'}</p>
            {exp.ots.map((ot: any) => (
              <p key={ot.id} className={ot.excepciónAprobado ? 'text-red-700 font-semibold' : ''}>
                📝 <strong>OT {ot.numeroOT || ot.id.slice(-6)}:</strong> {ot.creadoPor || ot.especialista || '—'}
                {ot.excepciónAprobado && (
                  <span className="ml-2 text-xs px-1.5 py-0.5 rounded font-bold" style={{ background: '#A32D2D', color: 'white' }}>⚠️ Usó excepción</span>
                )}
              </p>
            ))}
            {exp.partes.map((pa: any) => (
              <p key={pa.id}>🚜 <strong>Parte diario:</strong> {pa.operador || pa.creadoPor || '—'} · {pa.fecha}</p>
            ))}
            <p className="pt-1 mt-1 border-t border-green-200">📁 <strong>Archivado por:</strong> {exp.cerradoPor || '—'} · {exp.fechaCierre || '—'}</p>
          </div>

          {/* Análisis de deposición de gotas — si se subió antes de archivar */}
          {tieneAnalisisGotas && (
            <div className="bg-purple-50 border border-purple-200 rounded p-2 flex items-center gap-2 flex-wrap">
              <span className="text-purple-800 font-bold">💧 Análisis de gotas:</span>
              <a
                href={exp.predictivo.analisisGotasBase64}
                download={exp.predictivo.analisisGotasNombre || 'analisis_gotas.pdf'}
                onClick={(e) => e.stopPropagation()}
                className="text-blue-600 hover:underline font-medium"
              >
                📥 {exp.predictivo.analisisGotasNombre || 'descargar PDF'}
              </a>
              <span className="text-gray-500">
                · {exp.predictivo.analisisGotasSubidoPor}
                {exp.predictivo.analisisGotasSubidoEn && ` · ${fechaLocalISO(new Date(exp.predictivo.analisisGotasSubidoEn))}`}
              </span>
            </div>
          )}

          {/* Datos técnicos del parte */}
          {exp.partes.map((pa: any) => (
            <TarjetaParteArchivado
              key={pa.id}
              pa={pa}
              ots={exp.ots}
              rol={rol}
              usuarioActivo={usuarioActivo}
              expedienteId={exp.id}
              partesDelExpediente={exp.partes}
              predictivo={exp.predictivo}
            />
          ))}

          {/* Productos */}
          {exp.ots.map((ot: any) => ot.productos?.length > 0 && (
            <div key={ot.id} className="bg-white rounded p-2 border">
              <p className="font-bold text-gray-700 mb-1">🧪 Productos aplicados</p>
              {ot.productos.map((pr: any, i: number) => (
                <p key={i} className="text-[11px]">• {pr.nombre} — {pr.dosis} {pr.unidadDosis}/ha · Total: {pr.cantTotal}</p>
              ))}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

